quests[13146] = { id = 13146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jede Menge Großzügigkeit", description = "Wir müssen für ein wenig Tumult sorgen, um diese Todesritter von ihren Anführern wegzubekommen. Ich nehme an, dass, sollten wir ihre Untergebenen dort unten beseitigen, sie ihren Operationen mehr Aufmerksamkeit widmen müssten.\n\nMonstrositäten sind leichte Beute - langsam, berechenbar und was am allerwichtigsten ist: sie sind dumm. Nutzt ihr Vertrauen zu den Pirschern, um die Geißelbomben, die überall in dem Gebiet herumliegen, zu ihnen zu schleifen. Ihr werdet sie anzünden können, lange bevor die Monstrositäten überhaupt herausfinden, wie ihnen geschieht.", sourceObjective = "Vereth der Gewiefte möchte, dass Ihr nach Malykriss geht und mithilfe der Eisenkette des geschmeidigen Pirschers eine Geißelbombe zu einer schwerfälligen Schreckensgestalt zieht. Tötet auf diese Weise 4 schwerfällige Schreckensgestalten.", completion = "Sie sind nicht einmal auf den Gedanken gekommen, Hand an Euch zu legen, stimmt's? Wenigstens sind sie berechenbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[13147] = { id = 13147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kuppler", description = "Der Hauptunterschied zwischen Vargul und niederen untoten Günstlingen ist, dass die Vargul noch über so viel Verstand verfügen, um es zu verabscheuen, als Arbeiter herangezogen zu werden. Niemals wird es einem Vargul gefallen, an der Seite von Skeletten oder Ghulen arbeiten zu müssen.\n\nWir werden uns diese Abneigung zunutze machen und Zwietracht zwischen den Umbralschlägern und den anderen Untoten in Malykriss säen. Das sollte die Produktion abbremsen und die Todesritter zum Babysitting zwingen.\n\nSollte einfach zu machen sein - ein paar Steine auf die Schläger, sobald sie sich den niederen Untoten nähern, werden genügen.", sourceObjective = "Vereth der Gewiefte auf der Anhöhe des Leidens möchte, dass Ihr einen geschmeidigen Pirscher benutzt, um in Malykriss Steine auf Umbralschläger zu werfen, sobald sie sich niederen Untoten nähern. Kehrt zurück, sobald Ihr 5 Kämpfe provoziert habt.", completion = "Gibt also keinen Grund, unsere eigenen Männer zu opfern, wenn sie sich so leicht beeinflussen lassen, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[13148] = { id = 13148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halskettenreparatur", description = "Bei der kaputten Halskette liegt eine Rechnung, auf der steht: \"Eigentum von Jonas Timotheus - Cartier & Co., edle Juwelierwaren - Handelsmarkt der Magier - Dalaran\".\n\nVielleicht solltet Ihr sie reparieren und zu ihm zurückbringen.", sourceObjective = "Repariert die Halskette mit einem einzigen Chalzedon und bringt sie zu Jonas Timotheus im Juwelierladen auf dem Handelsmarkt der Magier in Dalaran.", progress = "Was führt Euch hierher?", completion = "Wo habt Ihr das gefunden?! Vor ein paar Wochen ging eine Lieferung von mir raus und viele dieser Halsketten wurden daraus gestohlen! Lasst mich meine Schuld begleichen und Euch dieses Juwelierssymbol geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13149] = { id = 13149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Illusionen bannen", description = "Der ewige Drachenschwarm möchte Prinz Arthas hinters Licht führen und auf diese Weise die Geschichte verändern.\n\nWenn er sich davon überzeugen lässt, dass keines der Körner hier verseucht ist, dann wird er seine verhängnisvolle Entscheidung niemals treffen und die Einwohner Stratholmes am Leben lassen.\n\nWendet diesen arkanen Disruptor auf alle Kornkisten an, die Euch verdächtig erscheinen.", sourceObjective = "Chromie möchte, dass Ihr den arkanen Disruptor auf die verdächtigen Kisten im Stratholme der Vergangenheit anwendet und sie anschließend am Eingang von Stratholme trefft.", completion = "Das habt Ihr gut gemacht, Freund. Arthas' Truppen haben das verseuchte Korn entdeckt.\n\nHört jetzt gut zu. Es gibt noch mehr zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[13150] = { id = 13150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ZZOLDLost: Widget", description = "Unten am Apparat ist eine Rechnung, laut der \"Jonas Timotheus - Juwelier\" in Dalaran der Besitzer ist. Wenn Ihr ihn reparieren und zu ihm zurückbringen würdet, vielleicht würde er Euch dann belohnen.", sourceObjective = "Repariert den Apparat und bringt ihn zu Jonas Thimotheus im Juwelierladen in Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[13151] = { id = 13151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eskorte des Königs", description = "Schon bald wird Arthas vor einem verzweifelten Dilemma stehen und eine folgenschwere Entscheidung treffen.\n\nIch muss Euch bitten, den Prinzen bei seiner Ausmerzaktion in Stratholme zu begleiten.\n\nArthas muss lebend durch Stratholme kommen und Ihr müsst dafür sorgen, dass er Mal'Ganis besiegt!", sourceObjective = "Chromie möchte, dass Ihr Arthas bei seiner Ausmerzaktion in Stratholme begleitet. Ihr sollt wieder mit ihr sprechen, nachdem Mal'Ganis besiegt ist.", completion = "Das habt Ihr gut gemacht, {name}.\n\nDer Plan des ewigen Drachenschwarms wurde durchkreuzt und die Geschichte bleibt, wie sie ist.\n\nEure Unterstützung war von unschätzbarem Wert - nehmt meinen Dank und auch den des gesamten bronzenen Drachenschwarms.", sourceObjectiveStatus = "unverified-source-field" }
quests[13152] = { id = 13152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Besuch beim Doktor", description = "Sie haben diese Ghule also unten im Sanktum der Reanimation mit zerbrochenen Saronitsplittern ausgestattet? Wir müssen dem ein Ende setzen, bevor sie diese Ghule gegen unsere Truppen einsetzen.\n\nFindet den Eingang zum Sanktum der Reanimation im Gebiet um das Fleischriesenlabor in den Fleischwerken. Dort hält das Ghulgenie Doktor Sabnok seine schaurigste Schöpfung 'Flicken' fest. Befreit Flicken von seinen Ketten und helft ihm, sich am Doktor zu rächen. Möge seine eigene Kreatur sein Untergang sein.", sourceObjective = "Dunkelreiterin Arly von der Schwarzwacht möchte, dass Ihr den Metallpflock, an den 'Flicken' im Sanktum der Reanimation gekettet ist, zerstört und diesem helft, sich an Doktor Sabnok zu rächen.", progress = "Habt Ihr die Schöpfung des Doktors schon freigelassen?", completion = "<Dunkelreiterin Arly wirft den Kopf in den Nacken und lacht finster.>\n\nEin passendes Ende für den 'guten' Doktor, findet Ihr nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[13153] = { id = 13153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krieger schützen", description = "{name}, gut, Euch zu sehen. Wir müssen uns beeilen, solange sich die Schlacht etwas gelegt hat, und unsere Vorräte aufstocken. Meine Untersuchungen deuten darauf hin, dass die Rüstungen der kürzlich in den Eiswasserfällen erschlagenen Soldaten mit unglaublichen Mengen Energie erfüllt werden. Man hat beobachtet, wie die Horde in dieser Gegend Rüstungen einsammelt.\n\nBegebt Euch zu den Eiswasserfällen und erschlagt jeden Anhänger der Horde, der Euch dort über den Weg läuft. Bringt ihre energieerfüllten Rüstungen wieder zu mir zurück.\n\nWenn Ihr keine Hordler finden könnt, dann vielleicht die Rüstung eines Abenteurers, der von den Elementaren getötet wurde.", sourceObjective = "Zauberin Kaylana in der Tausendwinterfestung möchte, dass Ihr zu den Eiswasserfällen geht und den Hordlern dort 10 magieerfüllte Rüstungen abnehmt.", progress = "Habt Ihr die Rüstungen nun gefunden?", completion = "Oh, die tropfen noch immer. Hättet Ihr sie nicht zuerst abtrocknen können?", sourceObjectiveStatus = "unverified-source-field" }
quests[13154] = { id = 13154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfeil und Knochen", description = "Drachen sind unglaubliche Wesen! Nun, zumindest ihre Knochen! Ich habe unsere Bogenschützen mit Pfeilspitzen aus Drachenknochen ausgerüstet. Unglücklicherweise ist es seit dem Massaker bei Angrathar fast unmöglich geworden, Knochen aus der Drachenöde zu bekommen.\n\nIm Schattenwald am westlichen Rand von Tausendwinter gibt es jedoch genug Knochen, um uns über die Runden zu helfen.\n\nGeht also dorthin und bringt so viele Knochensplitter zurück, wie Ihr nur finden könnt!\n\nMan hat Diener der Horde dabei beobachtet, wie sie Knochensplitter in der Gegend einsammeln. Tötet sie!", sourceObjective = "Bogenmacher Randolph in der Tausendwinterfestung möchte, dass Ihr in den Schattenwald geht und den Hordlern dort 10 Köcher mit Drachenknochenpfeilen abnehmt.", progress = "Wie ist die Jagd gelaufen? Ich habe Gerüchte darüber gehört, dass es an dem Ort spuken soll. Ich gehe jedoch nie selbst dorthin.", completion = "Ausgezeichnet! Das wird helfen, die Flammen des Krieges einige Tage lang zu schüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13155] = { id = 13155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vereth der Gewiefte", description = "Ich habe schon Gerüchte über Malykriss und Arthas' neuen Todesritterorden gehört, bin jedoch davon ausgegangen, dass es sich dabei nur um etwas handelt, das dazu dienen soll, die Lücke wieder aufzufüllen. Ihre Zahl lässt jedoch darauf schließen, dass er versucht, einen Zahn zuzulegen.\n\nWir haben vor nicht allzu langer Zeit einen unserer Besten nach Malykriss entsandt - Vereth den Gewieften. Ihr solltet ihn auf der Anhöhe des Leidens gleich westlich von Malykriss im Hof der Knochen antreffen.\n\nVersucht, auf Eurem Weg dorthin nicht zu viel Aufmerksamkeit auf Euch zu ziehen.", sourceObjective = "Meldet Euch bei Vereth dem Gewieften auf der Anhöhe des Leidens in Eiskrone.", completion = "Die unheilvolle Festung... ein Zeugnis dessen, wie ungern Arthas verliert. Lasst uns die Klinge tief hineintreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13156] = { id = 13156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein seltenes Kraut", description = "Du meine Güte, es ist ziemlich frisch hier oben! Erinnert mich an die stürmischen Gipfel von Kaarinos auf Argus. Doch bei all dem Schnee und Eis können sich unsere Soldaten schnell eine Erkältung einfangen.\n\nGeht hinaus in die Lebendige Steppe in Tausendwinters Südwesten und bringt mir zehn der Kräuterbeutel der Horde, die Ihr dort finden könnt. Ich werde sie zu einer Medizin zermahlen, die gegen die Kälte schützen wird.\n\nDiener der Horde waren damit beschäftigt, die Pflanzen in der Gegend zu sammeln. Wenn Ihr sie seht, dann zögert nicht und erschlagt sie und nehmt ihnen die Kräuter ab!", sourceObjective = "Anachoret Tessa in der Tausendwinterfestung möchte, dass Ihr in die Lebendige Steppe geht und den Hordlern dort 10 Kräuterbeutel der Horde abnehmt.", progress = "Hoffe, Ihr habt aus Versehen keine dieser Peitscher herausgezogen! Die haben den Gefreiten Doane letzte Woche ziemlich übel verpeitscht.", completion = "Ausgezeichnet! Das wird helfen, unsere Truppen vor der Kälte zu schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13157] = { id = 13157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kreuzfahrerturm", description = "Ihr könnt stolz darauf sein, dass Ihr es wart, der der Argentumdämmerung dazu verholfen hat, in Eiskrone Fuß zu fassen, {name}. Der Kreuzfahrerturm bietet dem Lichkönig und seinen missratenen Günstlingen nun direkt die Stirn.\n\nHochlord Fordring und die Kreuzfahrer, die überlebt haben, erwarten Eure Ankunft beim Kreuzfahrerturm. Durchquert erneut die Bresche und sucht den Hochlord auf!", sourceObjective = "Sucht den Hochlord Tirion Fordring beim Kreuzfahrerturm in Eiskrone auf.", completion = "Der Weg zu den Toren der Eiskronenzitadelle wird lang und beschwerlich. Ich und die Soldaten der Argentumdämmerung möchten Euch für alles danken, was Ihr bisher getan habt. Es beruhigt uns, zu wissen, dass Ihr an diesem verfluchten Ort an unserer Seite kämpfen werdet.\n\n<Hochlord Tirion Fordring salutiert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[13158] = { id = 13158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diskretion ist der Schlüssel", description = "Hört mir zu, {race}.\n\nMir wurde soeben mitgeteilt, dass sich in der Violetten Festung ein Zwischenfall ereignet hat. Es scheint, als würde der blaue Drachenschwarm eine groß angelegte Invasion Dalarans in die Wege leiten!\n\nIch möchte, dass Ihr Euch umgehend zum Gefängnis aufmacht und mit Aufseher Alturas sprecht. Er wird Euch die Einzelheiten erklären.\n\nDas ist nicht alles: Die Sache muss mit äußerster Diskretion behandelt werden. Wir müssen versuchen, die Einwohner Dalarans wenn möglich nicht zu beunruhigen. Habe ich mich klar ausgedrückt?\n\nSehr gut. Nun geht!", sourceObjective = "Rhonin möchte, dass Ihr zur Violetten Festung in Dalaran geht und mit Aufseher Alturas sprecht.", completion = "Keinen Augenblick zu früh.\n\nSeid Ihr bereit, Dalaran zu verteidigen, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[13159] = { id = 13159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindämmung", description = "Hier ist der Gefängnisschlüssel.\n\nMeine Männer und ich werden als letzte Verteidigungslinie hier bleiben, falls Ihr dem Angriff nicht standhalten könnt.\n\nSprecht auf jeden Fall mit Leutnant Sinclari. Sie wird Euch Zugang zu den Verteidigungsvorrichtungen des Gefängnisses beschaffen.\n\nBeeilt Euch, {race}. Es bleibt nur wenig Zeit. Die Wenigen, die ich zurückgelassen habe, werden ohne Eure Hilfe nicht lange durchhalten. Meldet Euch wieder bei mir, sobald die Invasoren erfolgreich zurückgeschlagen wurden.", sourceObjective = "Aufseher Alturas möchte, dass Ihr die Violette Festung betretet und den Invasionsstreitkräften des blauen Drachenschwarms ein Ende bereitet. Ihr sollt Euch wieder bei ihm melden, sobald Cyanigosa getötet wurde.", progress = "Ist es vorbei? Konntet Ihr dem Angriff standhalten?", completion = "Die Krise ist also abgewendet?\n\nDas sind wirklich gute Neuigkeiten. Ich werde sie an Rhonin weiterleiten.\n\nBitte, nehmt dies als Zeichen des Danks, den Euch Dalaran entgegenbringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13160] = { id = 13160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine überwältigende Aussicht", description = "Gargoyles eignen sich sehr gut als Kundschafter und können tödlich sein, wenn man ihnen den Angriff aus der Luft überlässt, doch haben sie einen offensichtlichen Schwachpunkt. Die meisten von ihnen müssen längere Zeit in Steinform verbringen, um sich zu erholen und die Energie zu sammeln, die sie brauchen, um ihre schweren Körper durch die Luft zu bewegen.\n\nAls ich durch das von Euch benutzte Auge geblickt habe, sind mir Dutzende von Eishautwachposten aufgefallen, die an den östlichen und südlichen Innenwänden ruhten. Benutzt den Jäger, um zu ihnen hinauf zu gelangen und vernichtet sie, während sie schlafen.", sourceObjective = "Vereth der Gewiefte möchte, dass Ihr die Hebefähigkeiten des geschmeidigen Pirschers benutzt, um 12 schlafende Eishautwachposten zu zerstören.", completion = "Die stellen keine so große Bedrohung mehr da, wenn sie schlafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13161] = { id = 13161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Reiter des Unheiligen", description = "Es ist Zeit, dass wir damit anfangen, den Kopf des Ganzen zu beseitigen.\n\nIch diente ziemlich lange neben Rokir. Er kennt die unheiligen Künste besser als jeder andere Todesritter, den ich getroffen habe, und er ist genauso skrupellos. Nehmt es nicht zu leicht.\n\nRokirs Stärken treten dann am stärksten hervor, wenn er sich auf seinem eigenen Grund und Boden befindet. Leider haben wir in dieser Hinsicht keine andere Wahl. Bleibt jedoch auf den Beinen, um seinen untoten Dienern aus dem Weg zu gehen, und Ihr solltet siegreich hervorgehen.\n\nSeid flink, {class}, und nehmt die Sache nicht zu leicht.", sourceObjective = "Vereth der Gewiefte auf der Anhöhe des Leidens wünscht, dass Ihr Rokir, den Reiter des Unheiligen, tötet.", completion = "Die Welt wird ohne Rokir ein viel besserer Ort sein - glaubt mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[13162] = { id = 13162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reiterin des Frostes", description = "Saph... So einen Todesritter wie sie gibt es kein zweites Mal. Sie wird Euch mit sanften Worten übergießen und während Ihr Euch absolut sicher seid, dass kein Funken Boshaftigkeit in ihr steckt, wird sie Euch durchlöchern - weiterhin ein Lächeln auf den Lippen. Unterschätzt sie nicht.\n\nIch mache mir keine Sorgen, dass Ihr Saph besiegen könnt, doch werdet bloß nicht zu übermütig. Ihre Stärke liegt darin, ihre Opfer in falscher Zuversicht zu wiegen und sie kurz darauf mit einem heftigen Frosthagel in tausend Einzelteile zu zerschießen.\n\nSeid immer auf der Hut und unterschätzt sie nicht.", sourceObjective = "Vereth der Gewiefte auf der Anhöhe des Leidens wünscht, dass Ihr Saph, die Reiterin des Frostes tötet.", completion = "Ich muss gestehen, dass ich ihr Lachen vermisse... und dieses Lächeln, das langsam in ihr Gesicht schlich, bevor sie jemanden tötete. Muss jetzt jedoch weniger auf der Hut sein, also nehme ich an, dass ich mich nicht beschweren kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[13163] = { id = 13163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Reiter des Blutes", description = "Baelok ist einer der wenigen Vrykul, den ich jemals in den Rängen aufsteigen sah, und das war größtenteils seiner schieren Brutalität zu verdanken. Wenn die Konkurrenz erst einmal tot ist, gibt es um einiges weniger, mit dem man konkurrieren müsste.\n\nEure Gruppe muss sich verteilen und so viel Abstand voneinander halten wie Ihr es die Situation zulässt, wenn der Kampf beginnt. Er wird nicht zögern, Eure Lebensenergie zu rauben, also werdet Ihr ihn so oft wie möglich daran hindern müssen.\n\nIch vertraue auf Euch. Seht zu, dass er stirbt.", sourceObjective = "Vereth der Gewiefte auf der Anhöhe des Leidens möchte, dass Ihr Baelok, den Reiter des Blutes, tötet.", completion = "Er hat also endlich den Kürzeren gezogen? Gut zu hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[13164] = { id = 13164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutbanns Schicksal", description = "Nun, da die Reiter der Heerschar des Leids tot sind, ist die Zeit gekommen, ihrem wahren Anführer ein Ende zu bereiten: Orbaz Blutbann.\n\nMograine war hier, als Ihr weg wart, und hat mir gesagt, dass er herausgefunden hat, wo sich Orbaz versteckt hält. Unter der Eiskronenzitadelle befindet sich eine riesige Grube - und Orbaz befindet sich am Rand dieser Grube.\n\nEinige der stärksten Agenten der Schwarzen Klinge wurden schon ausgesandt - holt also Hilfe und auf mit Euch in den Kampf. Es ist Zeit, dass Blutbann stirbt.", sourceObjective = "Vereth auf der Anhöhe des Leidens hat Euch ausgesandt, um Orbaz Blutbann zu töten.", progress = "Sind wir diesen jämmerlichen Möchtegernarthas los?", completion = "Also ist Mograine höchstpersönlich erschienen, um die Sache zu Ende zu bringen? Ich kann mir vorstellen, dass es böses Blut zwischen den beiden gegeben haben muss - kein Wunder also, dass er ein Stück vom Kuchen abbekommen wollte.\n\nIhr habt außerordentlich gute Arbeit geleistet, {race}, und sollt dementsprechend belohnt werden. Die Schwarze Klinge spricht Euch ihren Dank aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[13165] = { id = 13165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Acherus zurückerobern", description = "Der Dunstschleier hat sich gelüftet. Nun kann ich genauso klar sehen wie an dem Tag, als ich den Aschenbringer in mein eigenes Herz rammte, um meines Vaters verfluchte Seele zu befreien – dies ist meine letzte Erinnerung an mein Leben als freier Mann.\n\nWir müssen Acherus von der Geißel zurückerobern, wenn unser Orden in dieser neuen Welt überleben will. Ich habe Euch gezeigt, wie man ein schwarzes Tor beschwören kann. Das Tor wird Euch zurück nach Acherus befördern, wenn Ihr es ruft, {name}. Ruft es herbei und trefft mich dort. Die erste Schlacht der Ritter der Schwarzen Klinge ist in vollem Gange!", sourceObjective = "Benutzt Euren Zauber 'Schwarzes Tor' und kehrt nach Acherus, der Schwarzen Festung, zurück. Meldet Euch bei Hochlord Darion Mograine, sobald Ihr dort seid.", completion = "Der Lichkönig ist nach Nordend zurückgekehrt, verwundet vom Aschenbringer, doch auf der zweiten Ebene befindet sich noch immer die letzte seiner Armeen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13166] = { id = 13166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um die Schwarze Festung", description = "Die Hallen des Befehls wurden gesichert, doch der Lichkönig hat uns ein kleines Geschenk im Herzen von Acherus zurückgelassen. Der zusammengenähte Schrecken Flickwerk und eine Horde von Monstrositäten haben die zweite Ebene in ihre Kontrolle gebracht.\n\nBenutzt den Teleporter, um auf die zweite Ebene zu gelangen, und zerstört die restlichen Streitkräfte der Geißel. Greift Flickwerk auf keinen Fall alleine an! Ihr müsst das Ungetüm mit anderen Todesrittern von Acherus bekämpfen!\n\nGeht, {name}. Meine Kraft wird Euch tragen!", sourceObjective = "Vernichtet 10 Diener der Geißel und helft, Flickwerk zu vernichten. Kehrt zu Hochlord Darion Mograine zurück, solltet Ihr erfolgreich sein.", progress = "Acherus wird unser sein!", completion = "Gut gemacht, {class}. Um die verbliebenen Diener der Geißel wird man sich im Nu gekümmert haben und der Wiederaufbau kann von Neuem beginnen.\n\nIch habe eine allerletzte Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[13167] = { id = 13167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod dem Verräterkönig", description = "Anub'arak der Verräterkönig ist im einst stolzen unterirdischen Azjol-Nerub zuhause.\n\nNach seinem Verrat hat er unser Heimatland entstellt und verdorben und es schließlich zu dem erbärmlichen Haufen Dreck gemacht, zu dem es heute geworden ist. Er herrscht über eine Armee untoter Neruber, die wie ihr Anführer dem Lichkönig die Treue geschworen haben.\n\nSetzt der Herrschaft des Verräterkönigs ein Ende, {class}. damit würdet Ihr unseren beiden Völkern einen großen Dienst erweisen.\n\nBringt mir Anub'araks Panzer, wenn Ihr schaffen solltet, was noch keiner vor Euch geschafft hat.", sourceObjective = "Kilix der Entwirrer in der Grube von Narjun hat Euch damit beauftragt, Anub'arak in Azjol-Nerub zu besiegen. Danach sollt Ihr Kilix Anub'araks zerbrochenen Panzer zurückbringen.", progress = "Ist es vollbracht, {class}? Hat der Verräterkönig letztendlich sein Ende gefunden?", completion = "<Kilix starrt den Panzer an und jedes einzelne seiner Augen fängt an, intensiv zu leuchten.>\n\nEs ist VOLLBRACHT!\n\n{race}! Euer Name soll in die Geschichte meines Volkes eingehen.\n\nIch stehe in Eurer Schuld...", sourceObjectiveStatus = "unverified-source-field" }
quests[13168] = { id = 13168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abschiedsgeschenke", description = "Schaut, was wir hier haben... Augen der Herrschaft. Normalerweise tut der Kult alles nur Erdenkliche, um diese Dinger geheim zu halten, aber vermutlich haben sie ziemlich wenig Rückzugsmöglichkeiten, wenn wir sie in ihrem eigenen Haus erschlagen.\n\nDie Augen erlauben es jedem Wesen von relativer Macht, die Handlungen eines untoten Dieners präzise zu kontrollieren. Wie Ihr Euch vorstellen könnt, kann dies im Falle des typischen unbeholfenen Ghuls oder Skeletts extrem praktisch sein.\n\nHabt Ihr Lust, es einmal auszuprobieren? Benutzt eines der Augen bei einem der gefangenen Schatten.", sourceObjective = "Keritose Blutklinge im Schattengewölbe möchte, dass Ihr eins der Augen der Herrschaft benutzt, um die Kontrolle über einen gefangenen Eidolonwächter zu übernehmen.", progress = "Die Tricks, die durch diese Augen möglich werden, sind offenkundig. Dies werden sehr nützliche Werkzeuge sein.", completion = "Gar nicht schwer, hm? Jedes halbwegs intelligente Wesen sollte wenig Schwierigkeiten haben, niedere Untote zu kontrollieren. Ich schätze, nur ein echter Totenbeschwörer kann diese benutzen, um die Kontrolle über eines der mächtigeren untoten Geschöpfe zu ergreifen. Das dürfte allerdings kein Problem sein. Mir fallen bereits diverse Varianten der Zerstörung ein, die wir mithilfe der erbärmlichsten Diener ausführen können.\n\nSollen wir es einmal ausprobieren?", sourceObjectiveStatus = "unverified-source-field" }
quests[13169] = { id = 13169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der beste Freund des Untoten", description = "Unter den Untoten in der Saronitmine gen Süden ist es üblich, ihre Seuchenhunde hungern zu lassen, um sie besonders aggressiv zu halten. Benutzt den Schemen, um nahe heranzukommen und füttert einige der Hunde. Ich verspreche Euch, Ihr werdet fortan keinerlei Schwierigkeiten mehr mit ihnen haben. Vielleicht werden sie sich ihrem Wohltäter sogar anschließen.\n\nKommt den Dingern jedoch nicht zu nahe, bevor Ihr sie gefüttert habt. Ihre Nasen lassen sich von Eurem Schemen nicht so leicht hinters Licht führen.", sourceObjective = "Keritose Blutklinge im Schattengewölbe wünscht, dass Ihr mithilfe des Eidolonwächters 18 hungernde Seuchenhunde füttert.", completion = "Sie sind sofort eingeschlafen, stimmts?", sourceObjectiveStatus = "unverified-source-field" }
quests[13170] = { id = 13170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehre ist was für Schwächlinge", description = "Ghule sind sehr zerbrechlich, wenn es hart auf hart kommt, und die Aufklärer in der Saronitmine den Weg hinunter in Richtung Südwesten sind da keine Ausnahme. Mithilfe eines Schattens sollte es Euch eigentlich nicht schwerfallen, ranzuschleichen und ihre Aufklärer geräuschlos auszuschalten.\n\nBeseitigt so viele Aufklärer, wie Ihr in angemessener Zeit erwischen könnt... Ihre Reihen sollen gelichtet werden, bevor wir das nächste Mal angreifen.", sourceObjective = "Keritose Blutklinge im Schattengewölbe hätte gerne, dass Ihr 20 ruhelose Aufklärer tötet.", completion = "Ohne Euch auch nur die Hände schmutzig gemacht zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13171] = { id = 13171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schickt sie zurück", description = "Meine Hauptsorge ist die Saronitmine, die sich den Weg hinunter in Richtung Südwesten befindet. Sie holen unglaubliche Mengen an Erz aus dieser Mine und ich würde schon gerne wissen, was sie damit vorhaben. Um das herauszufinden, fangen wir damit an, ihre Verteidigung zu schwächen.\n\nMir sind mehrere Kristalle aufgefallen, die in der ganzen Basis verteilt stehen, und nehme an, dass es sich hier um irgendwelche Verteidigungsanlagen handelt, ähnlich den Ziggurats. Zerstört mithilfe des Eidolonwächters jeden Kristall, den Ihr finden könnt.", sourceObjective = "Keritose Blutklinge im Schattengewölbe hat Euch ausgesandt, um 10 Eindämmungskristalle der Geißel zu bannen.", completion = "Ausgezeichnete Arbeit. In der Luft sollte also so gut wie keine Gefahr mehr lauern.", sourceObjectiveStatus = "unverified-source-field" }
quests[13172] = { id = 13172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chaos säen", description = "Effektives Werkzeug, nicht wahr? Sehr gut gemacht, wie Ihr ihre Verteidigung geschwächt habt, {class}. Nun können wir den Hauptangriff vorantreiben.\n\nDer Plan ist einfach und direkt - wir wollen alles beseitigen, was sich bewegt, und die Verwirrung ausnutzen, um ein paar Informationen in die Hände zu bekommen.\n\nSagt mir Bescheid, wenn Ihr bereit seid, und ich werde Euch einen Skelettgreif besorgen.", sourceObjective = "Keritose Blutklinge im Schattengewölbe hat Euch ausgesandt, um 80 Untote im Tränenbruch abzuschlachten. Sprecht mit ihm, um Euch einen Skelettgreifen für den Angriff zu sichern.", completion = "Sie sind so gut wie schutzlos ausgeliefert. Viel einfacher geht's wohl nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13173] = { id = 13173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Durcheinander nutzen", description = "Uns ist es gelungen, eine ganze Reihe von Arbeitern in die Finger zu bekommen. Sie sollten sich gut eignen.\n\nIch möchte, dass Ihr eins der Augen benutzt, um einen Arbeiter in die Mine zu schicken. Wenn das ganze Lager in Aufruhr ist, sollte es ihnen unmöglich sein, Euch von einem der anderen Arbeiter zu unterscheiden, die nach dem Angriff umherlaufen.\n\nFindet denjenigen, der für die ganze Operation zuständig ist und macht Euch an die Arbeit. Mit etwas Glück werden wir recht schnell herausfinden, wohin das Saronit verschickt wird. Ich werde Euch durch das Auge hindurch beobachten." }
quests[13174] = { id = 13174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Durcheinander nutzen", description = "Den Betrieb zum Stillstand zu bringen ist nur die eine Hälfte des Plans. Das andere wichtige Ziel an dieser Stelle ist es, herauszufinden, wohin all das Saronit geschickt wird. Uns sind ein paar Orte bekannt, an denen es wieder auftaucht, doch bei der Menge, die sie aus dem Boden holen, liegt die Vermutung nahe, dass da ein viel größeres Projekt läuft.\n\nSeid Ihr einmal in der Mine, so nehmt alle Dokumente mit, die Ihr finden könnt. Solltet Ihr den Ort mit einem der Greifen angreifen, so könnt Ihr Euch fallenlassen, sobald Ihr die Arbeit erledigt habt.", sourceObjective = "Keritose Blutklinge im Schattengewölbe verlangt ein Dokument des Tränenbruchs, ein Geschäftsbuch des Tränenbruchs, eine Karte des Tränenbruchs und einen Zeitplan des Tränenbruchs.", progress = "Habt Ihr das, was ich wollte?", completion = "Dann lasst uns mal sehen... Was haben wir denn hier...\n\n<Keritose durchforstet die Papiere und scheint wenig zu finden, was er nicht schon vorher wusste - als er plötzlich auf das stößt, wonach er suchte...>\n\nMalykriss! Die unheilvolle Festung. Es scheint, als hätte der Verlust seiner Todesritter Arthas nicht allzu glücklich gemacht... Ich bin mir nicht sicher, was er mit dem ganzen Saronit anfängt, doch er scheint in übertriebenem Maße etwas ausgleichen zu wollen.\n\nDer Junge ist nicht daran gewöhnt, zu verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13175] = { id = 13175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kontrolle zurückgewinnen" }
quests[13176] = { id = 13176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lieferung vorbereiten" }
quests[13177] = { id = 13177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Gnade für die Gnadenlosen", description = "Willkommen in der Tausendwinterfestung, {name}. Eure Mission hier ist einfach: Besiegt zehn der besten Kämpfer, die die Horde zu bieten hat. Nun geht! Zum Sieg der Allianz!", sourceObjective = "Hauptmann Zanneth in der Tausendwinterfestung möchte, dass Ihr 10 Mitglieder der Horde tötet.", completion = "Wie ruhmreich! Wahrlich, Ihr gehört zu den Champions der Allianz.", sourceObjectiveStatus = "unverified-source-field" }
quests[13178] = { id = 13178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet sie alle!", description = "Willkommen in der Tausendwinterfestung, {name}. Kriegsherr Garrosh verlangt nur eins: tötet sie alle!\n\nKehrt wieder zu mir zurück, wenn zehn der stärksten Mitglieder der Allianz tot sind.", sourceObjective = "Kommandant Dardosh in der Tausendwinterfestung möchte, dass Ihr 10 Mitglieder der Allianz tötet.", completion = "Lok'tar! Sieg für die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[13179] = { id = 13179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Gnade für die Gnadenlosen", description = "Willkommen in Tausendwinter, {name}. Eure Mission hier ist einfach: Besiegt zehn der besten Kämpfer, die die Horde zu bieten hat. Nun geht! Zum Sieg der Allianz!", sourceObjective = "Hauptmann Zanneth in Tausendwinter möchte, dass Ihr 10 Mitglieder der Horde tötet.", completion = "Wie ruhmreich! Wahrlich, Ihr gehört zu den Champions der Allianz.", sourceObjectiveStatus = "unverified-source-field" }
quests[13180] = { id = 13180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet sie alle!", description = "Willkommen in Tausendwinter, {name}. Kriegsherr Garrosh verlangt nur eins: tötet sie alle!\n\nKehrt wieder zu mir zurück, wenn zehn der stärksten Mitglieder der Allianz tot sind.", sourceObjective = "Kommandant Dardosh in Tausendwinter möchte, dass Ihr 10 Mitglieder der Allianz tötet.", completion = "Lok'tar! Sieg für die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[13181] = { id = 13181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg in Tausendwinter", description = "Hauptmann Zanneth mag vielleicht zufrieden damit sein, einen Haufen Hordeleichen vor sich liegen zu haben, doch die Kontrolle über die Tausendwinterfestung zu erlangen, ist für die Expedition Valianz von äußerster Wichtigkeit. Kümmert Euch darum, dass sie weiterhin in unseren Händen bleibt.\n\nGlaubt jedoch bloß nicht, dass wir Euch einfach so herumstehen lassen werden, während Eure Mitstreiter die Drecksarbeit für Euch erledigen. Wenn Ihr bis zum Ende der Schlacht nicht mindestens ein Rekrut zweiten Grades seid, dann braucht Ihr nicht zurückkommen.", sourceObjective = "Gewinnt einen Kampf auf dem Schlachtfeld in Tausendwinter und kehrt dann zu Taktikoffizier Ahbramis zurück. Ihr müsst an der Schlacht teilgenommen haben, um für den Sieg belohnt zu werden.", completion = "Genau das, was ich hören wollte! Ein Sieg auf dem Tausendwintersee - selbst ein vorübergehender - ist ein äußerst wichtiger Bestandteil unserer Gesamtstrategie gegen die Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13182] = { id = 13182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergesst die Eier nicht!", description = "In ganz Azjol-Nerub liegen Eier verteilt, die von den Nerubern der Geißel gehegt und gepflegt werden und schon bald schlüpfen werden. Sie werden ihre Zahl noch zusätzlich mehren.\n\nEs würde nicht viel nützen, wenn alle Untoten aus den Höhlen getilgt und diese faulen Eier ausschlüpfen würden, nur damit sie an ihre Stelle treten.\n\nKümmert Euch auf jeden Fall darum, dass unsere uralte Heimat von allen Eiern der Geißel gereinigt wird, während Ihr den Ort erkundet, der einst Azjol-Nerub gewesen ist.", sourceObjective = "Kilix der Entwirrer in der Grube von Narjun möchte, dass Ihr Azjol-Nerub betretet und 6 Eier der Geißelneruber zerstört.", completion = "Es macht mich traurig zu sehen, dass es dazu gekommen ist. Wenn wir unser Reich nur wieder zu dem machen könnten, was es einst war...", sourceObjectiveStatus = "unverified-source-field" }
quests[13183] = { id = 13183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg in Tausendwinter", description = "Dardosh mag es zwar genügen, unsere Feinde zu töten, doch es ist von äußerster Wichtigkeit, dass wir die Tausendwinterfestung kontrollieren. Tut, was auch immer nötig ist, damit Tausendwinter uns gehört.\n\nGlaubt jedoch bloß nicht, dass wir Euch einfach so herumstehen lassen werden, während Eure Mitstreiter die Drecksarbeit für Euch erledigen. Wenn Ihr bis zum Ende der Schlacht nicht mindestens ein Rekrut zweiten Grades seid, dann braucht Ihr nicht zurückkommen.", sourceObjective = "Gewinnt einen Kampf in einem Schlachtfeld von Tausendwinter und kehrt anschließend zu Taktikoffizier Kilrath in Tausendwinter zurück. Ihr müsst an der Schlacht teilgenommen haben, um für den Sieg belohnt zu werden.", completion = "Ihr habt heute wahrlich etwas Großartiges fertiggebracht. Euer Opfer wird geschätzt!", sourceObjectiveStatus = "unverified-source-field" }
quests[13184] = { id = 13184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nützlichkeit überdauern" }
quests[13185] = { id = 13185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt der Belagerung ein Ende", description = "Ich sie gehört! Die Allianz bald kommen. Mach drei Belagerungsmaschinen kaputt und komm dann wieder zu Murp.", sourceObjective = "Leutnant Murp in der Tausendwinterfestung möchte, dass Ihr 3 Belagerungsmaschinen der Allianz zerstört.", progress = "Hast du ihre Belagerungsmaschinen kaputt gemacht?", completion = "Gute Arbeit. Murp wäre gern dabei gewesen, um zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13186] = { id = 13186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt der Belagerung ein Ende", description = "Es ist nur eine Frage der Zeit, bis diese Burg von den Streitkräften der Horde belagert wird. Zerstört drei ihrer Belagerungsmaschinen und kehrt anschließend zu mir zurück.", sourceObjective = "Chefdemolierer Legoso in der Tausendwinterfestung möchte, dass Ihr 3 Belagerungsmaschinen der Horde zerstört.", completion = "Ausgezeichnet. Das sollte ihren Angriff verlangsamen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13187] = { id = 13187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gesichtslosen", description = "Jedes Mal, wenn mein Volk im Kampf gegen die Streitkräfte der Untoten an Boden verlor, grub es tiefer.\n\nVersehentlich legten sie Diener der Alten Götter frei, Wesen, die nur als die Gesichtslosen bekannt sind.\n\nAm Ende konnten wir nicht an zwei Fronten kämpfen.\n\nMit Eurer Hilfe werden die Gesichtslosen hoffentlich endlich fallen.", sourceObjective = "Seher Ixit möchte, dass Ihr Herold Volazj und die drei Vergessenen an seiner Seite tötet.", completion = "Gut gemacht, {class}.\n\nDank Eures Sieges über die Diener der Alten Götter kann sich nun mein Volk aufmachen, die Stadt seiner Vorfahren zu erobern.", sourceObjectiveStatus = "unverified-source-field" }
quests[13188] = { id = 13188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Spuren der Könige", description = "Ihr seid von nun an für den Rest der Ewigkeit ein Ritter der Schwarzen Klinge, {name}, doch wisset: Einst wart Ihr ein Held der Allianz.\n\n<Darion starrt Euch an.>\n\nDieser Orden muss Verbündete finden, wenn er überleben will. Ihr sollt der Repräsentant der Ritter der Schwarzen Klinge sein und Euch der Allianz zeigen.\n\nAuf der Plattform südöstlich von mir befindet sich ein Portal nach Sturmwind. Hier, nehmt diesen Brief - Lord Fordring trug mir auf, ihn Euch zu geben. Ihr sollt ihn König Varian Wrynn bringen. Benutzt das Portal.", sourceObjective = "Bringt den Brief zu König Varian Wrynn, Anhänger der Allianz in Burg Sturmwind in Sturmwind.", progress = "Ihr habt nur noch Sekunden zu leben.", completion = "<Varian starrt in die Ferne.>\n\nIn der Tat, alter Freund... Blut und Ruhm.\n\n<Varian richtet seinen Blick auf Euch.>\n\nWäre dieser Brief von Tirion nicht, wärt Ihr nichts weiter als ein Fleck auf meinem Boden. Nur die Empfehlung eines der größten Paladine, der jemals gelebt hat, hätte Euer Überleben sichern können.\n\nWir... Wir werden zusammen gegen die Geißel kämpfen - gegen den Lichkönig!\n\nEHRE DER ALLIANZ!", sourceObjectiveStatus = "unverified-source-field" }
quests[13189] = { id = 13189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen des Kriegshäuptlings", description = "Ihr seid von nun an für den Rest der Ewigkeit ein Ritter der Schwarzen Klinge, {name}, doch wisset: Einst wart Ihr ein Held der Horde.\n\n<Darion starrt Euch an.>\n\nDieser Orden muss Verbündete finden, wenn er überleben will. Ihr sollt der Repräsentant der Ritter der Schwarzen Klinge sein und Euch der Horde zeigen.\n\nAuf der Plattform südöstlich von mir befindet sich ein Portal nach Orgrimmar. Hier, nehmt diesen Brief - Lord Fordring trug mir auf, ihn Euch zu geben. Ihr sollt ihn dem Kriegshäuptling überbringen. Benutzt das Portal.", sourceObjective = "Bringt den Brief zum Kriegshäuptling der Horde in Orgrimmar.", progress = "Eine interessante Wende der Ereignisse.", completion = "Es ist diesem Paladin zu verdanken, dass Etrigg am Leben ist. Hätte Lord Fordring ihn nicht aus Stratholme befreit, wäre er hingerichtet worden.\n\nDass Tirion Fordring alles geopfert hat, um das Leben eines Orcs zu retten... Ich kenne nur einen Menschen, der solch ein Opfer gebracht hat.\n\n<Thrall hält eine Träne zurück.>\n\nDu wirst immer in meinem Herzen bleiben, Taretha.\n\nJa. Für Tirion Fordring und Etrigg! Wir werden Euch als Mitglied der Horde akzeptieren und Euren Orden als Verbündete betrachten.\n\nBlut und Donner! Für die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[13190] = { id = 13190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles zu seiner Zeit", description = "Ahn'kahet, woher wir einst kamen...\n\nIch träume davon, dass wir eines Tages Tod und Dunkelheit, in deren Griff sich unsere uralte Heimat befindet, überwinden werden. Zu diesem Zweck habe ich einen Plan entworfen, mit dem wir unsere Feinde entmutigen können.\n\nIhre kostbaren Wächter müssen brennen!\n\nLegt ihre Leichen auf die Kohlenpfanne tief im Inneren der Stadt. Der Geruch ihrer verbrannten Überreste wird in der Luft hängen und unseren Feind an seine Schwäche erinnern.\n\nGeht mit Bedacht vor, {class}! Ihre untoten Leichen sind äußerst zerbrechlich und werden rasch verrotten.", sourceObjective = "Kilix der Entwirrer in der Grube von Narjun möchte, dass Ihr die Leiche eines Wächters der Ahn'kahar beschafft und sie auf das Kohlenbecken von Ahn'kahet in Ahn'kahet legt.\n\nDiese Quest kann nur auf dem Schwierigkeitsgrad 'Heroisch' beendet werden.", progress = "Konntet Ihr die Leiche eines Wächters verbrennen, {race}?", completion = "Aha!\n\nMöge der spöttische Geruch des Versagens an ihren leeren Seelen nagen!\n\nIch danke Euch, {class}. Ihr habt den Untoten an diesem heutigen Tage einen Schlag versetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13191] = { id = 13191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwüster auftanken", description = "Lok'tar, {name}! Die Schlacht mag vielleicht geschlagen sein, doch wir müssen uns auf den nächsten Angriff der Allianz vorbereiten! Reist zum Flammenkessel im Südosten von Tausendwinter und bringt zehn Stück Immerglut zurück.\n\nDie Glutstücke werden mit Kohle vermengt, um Treibstoff für die Verwüster und Belagerungsmaschinen zu liefern.\n\nWir haben Berichte darüber gehört, dass die Schweine von der Allianz den ganzen Tag über die Glutstücke sammeln. Tötet sie und nehmt sie ihnen weg! Wenn die Anhänger der Allianz die Gegend schon aufgegeben haben, dann macht Euch darauf gefasst, die Feuerelementare in der Gegend zu bekämpfen, bis Ihr welche findet!", sourceObjective = "Belagerungsschmied Starkhuf in der Tausendwinterfestung möchte, dass Ihr zum Flammenkessel geht und den Allianzlern dort 10 Stück Immerglut abnehmt.", progress = "Nun? Konntet Ihr die Glutstücke finden? oder hat die Allianz alles gestohlen und Euch weinend zurückgelassen?", completion = "Ausgezeichnet! Das wird uns dabei helfen, die Allianz in den kommenden Schlachten zu besiegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13192] = { id = 13192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wälle schützen", description = "Hey, Mann. Bei dem Ort hier krieg ich 'ne Gänsehaut, weißt du?\n\nHier spuken viel zu viele Geister rum. Ich will Hoodoobarrieren aufstellen, brauch aber 'n paar Seelen dafür, Mann. Aber nich' irgendwelche Seelen; nur die eines starken Kämpfers ist dafür gut.\n\nDie Eiswasserfälle im Osten von Tausendwinter haben spezielle Eigenschaften, durch die man 'ne Seele heraussaugen kann. Bring die Allianzler dort um - vielleicht haben sie das Zeug, das wir brauchen.\n\nBring die Rüstungen der Toten hierher zu mir. Wenn da keine Allianzler sin', dann haben die Elementare vielleicht welche, Mann.", sourceObjective = "Hoodoomeister Fu'jin in der Tausendwinterfestung möchte, dass Ihr 10 verzauberte Brustplatten der Allianz aus dem Gebiet der Eiswasserfälle beschafft.", progress = "Hast du die Rüstungen mit dabei, Mann?", completion = "Ooh, ja, das is' das Zeug, Mann!", sourceObjectiveStatus = "unverified-source-field" }
quests[13193] = { id = 13193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfeil und Knochen", description = "Weshalb würden sie mich mit der Aufgabe betreuen, unsere Bogenschützen auszurüsten? Ich war ein Dichter, kein Waldläufer! Tja, jammern hilft nichts. {name}, ich brauche Drachenknochen für unsere Pfeilspitzen.\n\nReist zum Schattenwald an der westlichen Seite von Tausendwinter. Seit dem letzten Scharmützel haben die Diener der Allianz die Gegend nach Drachenknochen durchstöbert. Tötet sie und nehmt ihnen die Knochen ab.\n\nWenn das nicht funktionieren sollte, dann könnt Ihr vielleicht welche von den Geistern dort bekommen, wenn Ihr Glück habt. Ich habe gehört, dass sie liebend gerne ihre sterbenden Opfer auf den Knochen aufspießen.", sourceObjective = "Leutnant Vieron Flammenfeder in der Tausendwinterfestung möchte, dass Ihr in den Schattenwald geht und den Allianzlern dort 10 Köcher mit Drachenknochenpfeilen abnehmt.", progress = "Schon so früh zurück? Verflixt, hatte gehofft, mich einen Moment lang ausruhen zu können.", completion = "Tja, ich nehme an, das heißt für mich: noch eine Nacht Knochen schärfen. Wieso bin ich nicht wie mein Bruder in Silbermond geblieben?", sourceObjectiveStatus = "unverified-source-field" }
quests[13194] = { id = 13194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Rosen heilen", description = "Zwischen den Schlachten mag einer schon fast daran glauben, dass es Hoffnung auf Frieden in diesem Land gäbe. Leider hat unser Schicksal anderes mit uns vor.\n\nReist zur lebendigen Steppe im Südwesten von Tausendwinter. Ich benötige die dort wachsenden Rosen, um daraus eine Heilsalbe für die Verwundeten herzustellen.\n\nLeider ist die Rose eher selten geworden, weil die Allianz sie zu schnell aberntet. Geht zur lebendigen Steppe, tötet sie und nehmt ihnen ihre Kräuterbeutel ab.\n\nWenn das nicht funktionieren sollte, dann schnappt Euch die Peitscher. Ein paar von denen haben vielleicht welche dabei.", sourceObjective = "Primalist Mulfort möchte, dass Ihr in die Lebendige Steppe geht und den Allianzlern dort 10 Kräuterbeutel der Allianz abnehmt.", progress = "Habt Ihr die Kräuter dabei? Die Verwundeten und Kranken werden von Stunde zu Stunde mehr.", completion = "Ich danke Euch, das wird uns eine große Hilfe bei der Behandlung unserer verwundeten Soldaten sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13195] = { id = 13195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein seltenes Kraut", description = "Du meine Güte, es ist ziemlich frisch hier oben! Erinnert mich an die stürmischen Gipfel von Kaarinos auf Argus. Doch bei all dem Schnee und Eis können sich unsere Soldaten schnell eine Erkältung einfangen.\n\nGeht hinaus in die Lebendige Steppe in Tausendwinters Südwesten und bringt mir zehn Kräuterbeutel der Horde. Ich werde sie zu einer Medizin zermahlen, die gegen die Kälte schützen wird.\n\nDiener der Horde waren damit beschäftigt, die Pflanzen in der Gegend zu sammeln. Wenn Ihr sie seht, dann zögert nicht und erschlagt sie und nehmt ihnen ihre Kräuter ab!\n\nDie Peitscher in der Gegend können auch welche bei sich haben.", sourceObjective = "Anachoret Tessa in Tausendwinter möchte, dass Ihr in die Lebendige Steppe geht und den Hordlern dort 10 Kräuterbeutel abnehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13196] = { id = 13196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfeil und Knochen", description = "Drachen sind unglaubliche Wesen! Nun, zumindest ihre Knochen! Ich habe unsere Bogenschützen mit Pfeilspitzen aus Drachenknochen ausgerüstet. Unglücklicherweise ist es seit dem Massaker bei Angrathar fast unmöglich geworden, Knochen aus der Drachenöde zu bekommen.\n\nIm Schattenwald am westlichen Rand von Tausendwinter gibt es jedoch genug Knochen, um uns über die Runden zu helfen.\n\nGeht also dorthin und bringt so viele Knochensplitter zurück, wie Ihr nur finden könnt!\n\nMan hat Diener der Horde dabei beobachtet, wie sie Knochensplitter in der Gegend einsammeln. Tötet sie!", sourceObjective = "Bogenmacher Randolph in Tausendwinter möchte, dass Ihr in den Schattenwald geht und den Hordlern dort 10 Köcher mit Drachenknochenpfeilen abnehmt.", progress = "Wie ist die Jagd gelaufen? Ich habe Gerüchte darüber gehört, dass es an dem Ort spuken soll. Ich gehe jedoch nie selbst dorthin.", completion = "Ausgezeichnet! Das wird helfen, die Flammen des Krieges einige Tage lang zu schüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13197] = { id = 13197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwüster auftanken", description = "{name}! Wurde auch langsam Zeit, dass Ihr auftaucht. Wir mögen zwar die letzte Schlacht verloren haben, doch wir sollten uns noch immer auf die nächste vorbereiten! Reist zum Flammenkessel im südöstlichen Teil von Tausendwinter und beschafft mehrere Stück Immerglut.\n\nDie Glutstücke werden mit Kohle vermengt, um Treibstoff für die Verwüster und Belagerungsmaschinen zu liefern.\n\nOh, eins noch: Falls Ihr zufällig Anhänger der Horde im Flammenkessel sehen solltet, dann zögert nicht, tötet sie und nehmt ihnen die Glutstücke weg. Wir müssen verhindern, dass die Festung in ihrer Kontrolle bleibt!", sourceObjective = "Belagerungsschmied Starkhand in Tausendwinter möchte, dass Ihr zum Flammenkessel geht und den Hordlern dort 10 Stück Immerglut abnehmt.", progress = "Nun? Konntet Ihr die Glutstücke finden? Oder ist Euch die Horde zuvorgekommen und hat Euch weinend zurückgelassen?", completion = "Ausgezeichnet! Das wird helfen, die Flammen des Krieges einige Tage lang zu schüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13198] = { id = 13198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krieger schützen", description = "{name}, gut, Euch zu sehen. Wir müssen uns auf unseren nächsten Angriff auf die Festung vorbereiten. Meine Untersuchungen deuten darauf hin, dass die Rüstungen der kürzlich in den Eiswasserfällen erschlagenen Soldaten mit unglaublichen Mengen Energie erfüllt werden. Die Horde war damit beschäftigt, in dieser Gegend Rüstungen einzusammeln.\n\nBegebt Euch zu den Eiswasserfällen und erschlagt jeden Anhänger der Horde, der Euch dort über den Weg läuft. Bringt ihre energieerfüllten Rüstungen wieder zu mir zurück.\n\nWenn Ihr keine Hordler finden könnt, dann vielleicht die Rüstung eines Abenteurers, der von den Elementaren getötet wurde.", sourceObjective = "Zauberin Kaylana in Tausendwinter möchte, dass Ihr zu den Eiswasserfällen geht und den Hordlern dort 10 magieerfüllte Rüstungen der Horde abnehmt.", progress = "Habt Ihr die Rüstungen nun gefunden?", completion = "Oh, die tropfen noch immer. Hättet Ihr sie nicht zuerst trocknen können?", sourceObjectiveStatus = "unverified-source-field" }
quests[13199] = { id = 13199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfeil und Knochen", description = "Weshalb würden sie mich mit der Aufgabe betreuen, unsere Bogenschützen auszurüsten? Ich war ein Dichter, kein Waldläufer! Tja, jammern hilft nichts. {name}, ich brauche Drachenknochen für unsere Pfeilspitzen.\n\nReist zum Schattenwald an der westlichen Seite von Tausendwinter. Seit dem letzten Scharmützel haben die Diener der Allianz die Gegend nach Drachenknochen durchstöbert. Tötet sie und nehmt ihnen die Knochen ab.\n\nWenn das nicht funktionieren sollte, dann könnt Ihr vielleicht welche von den Geistern dort bekommen, wenn Ihr Glück habt. Ich habe gehört, dass sie liebend gerne ihre sterbenden Opfer auf den Knochen aufspießen.", sourceObjective = "Leutnant Vieron Flammenfeder in Tausendwinter möchte, dass Ihr in den Schattenwald geht und den Allianzlern dort 10 Köcher mit Drachenknochenpfeilen abnehmt.", progress = "Schon so früh zurück? Verflixt, hatte gehofft, mich einen Moment lang ausruhen zu können.", completion = "Tja, ich nehme an, das heißt für mich: noch eine Nacht Knochen schärfen. Wieso bin ich nicht wie mein Bruder in Silbermond geblieben?", sourceObjectiveStatus = "unverified-source-field" }
quests[13200] = { id = 13200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwüster auftanken", description = "Lok'tar, {name}! Die Schlacht mag vielleicht geschlagen sein, doch wir müssen uns auf den nächsten Angriff der Allianz vorbereiten! Reist zum Flammenkessel im Südosten von Tausendwinter und bringt zehn Stück Immerglut zurück.\n\nDie Glutstücke werden mit Kohle vermengt, um Treibstoff für die Verwüster und Belagerungsmaschinen zu liefern.\n\nWir haben Berichte darüber gehört, dass die Schweine von der Allianz den ganzen Tag über die Glutstücke sammeln. Tötet sie und nehmt sie ihnen weg! Wenn die Anhänger der Allianz die Gegend schon aufgegeben haben, dann macht Euch darauf gefasst, die dortigen Feuerelementare zu bekämpfen, bis Ihr welche findet!", sourceObjective = "Belagerungsschmied Starkhuf in Tausendwinter möchte, dass Ihr zum Flammenkessel geht und den Allianzlern dort 10 Stück Immerglut abnehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13201] = { id = 13201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Rosen heilen", description = "So viele unserer Tapferen sind in der Schlacht gefallen, doch noch mehr werden sterben, wenn sie nicht behandelt werden.\n\nReist zur lebendigen Steppe im Südwesten von Tausendwinter. Ich benötige die dort wachsenden Rosen, um daraus eine Heilsalbe für die Verwundeten herzustellen.\n\nLeider ist die Rose eher selten geworden, weil die Allianz sie zu schnell aberntet. Geht zur lebendigen Steppe, tötet sie und nehmt ihnen die Kräuterbeutel ab.\n\nWenn das nicht funktionieren sollte, dann schnappt Euch die Peitscher. Ein paar von denen haben vielleicht welche dabei.", sourceObjective = "Primalist Mulfort in Tausendwinter möchte, dass Ihr in die Lebendige Steppe geht und den Allianzlern dort 10 Kräuterbeutel der Allianz abnehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13202] = { id = 13202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mauern verhexen", description = "Hey, Mann. Siehst du, wie die Allianzler sich's in ihrer Festung bequem machen?\n\nDenke, die sehen ein wenig zu bequem aus, findste nich'? Ich will den Ort verhexen, aber ich brauch dafür 'n paar Seelen, Mann. Aber nich' irgendwelche Seelen; nur die eines starken Kämpfers ist dafür gut.\n\nDie Eiswasserfälle im Osten von Tausendwinter haben spezielle Eigenschaften, durch die man 'ne Seele heraussaugen kann. Bring die Allianzler dort um - die haben das Zeug, das wir brauchen.\n\nBring die Rüstungen der Toten hierher zu mir. Wenn da keine Allianzler sin', dann haben die Elementare vielleicht welche, Mann.", sourceObjective = "Hoodoomeister Fu'jin in Tausendwinter möchte, dass Ihr zu den Eiswasserfällen geht und Allianzspielern dort 10 verzauberte Brustplatten der Allianz abnehmt.", progress = "Hast du die Rüstungen mit dabei, Mann?", completion = "Ooh, ja, das is' das Zeug, Mann!", sourceObjectiveStatus = "unverified-source-field" }
quests[13203] = { id = 13203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk" }
quests[13204] = { id = 13204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgefahrene Pilze", description = "Ein unförmiges Stück pilzähnlichen Fungus fällt von einem besonders übel riechenden, schlammbedeckten Teil des Fleischs der Höhlenbestie. Als Ihr ihn näher betrachtet, werdet Ihr von dessen Gestank überwältigt und weicht angewidert zurück.\n\nIhr wundert Euch, ob die Neruber so etwas appetitlich finden. Ihr steckt den klebrigen Organismus in Eure Tasche und seid fest dazu entschlossen, es herauszufinden...", sourceObjective = "Ihr sollt 6 groteske Pilze von den wilden Höhlenbestien in Ahn'kahet sammeln und sie bei Kilix dem Entwirrer in der Grube von Narjun abliefern.", progress = "Was im Namen der Schöpfung ist das?!", completion = "Habt Ihr irgendeine Vorstellung davon, was Ihr da mit Euch herumgetragen habt, {class}?\n\nDie Höhlenbestien, von denen Ihr das habt, sondern ihren Abfall nicht auf die dahergebrachte Art und Weise ab. Ihr solltet Eure Hände waschen...\n\nDanke, dass Ihr an uns gedacht habt, doch falls Ihr noch mehr von diesen Dingern finden solltet, dann haltet Euch davon fern.", sourceObjectiveStatus = "unverified-source-field" }
quests[13205] = { id = 13205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abrüstung", description = "Glaubt mir, <Kamerad/Fräulein>, die Waffen der Vrykul sind durchweg gefährlich!\n\nIch habe ihre Schneiden am eigenen Leib erfahren und muss sagen, dass sie etwas Unnatürliches an sich haben. Sie sind täuschend gut ausbalanciert und unverschämt scharf - kurz gesagt einfach tödlich.\n\nGelangt in ihre Festung und krallt Euch zumindest einige dieser Waffen! Vielleicht können wir etwas von ihnen lernen, vielleicht auch nicht.\n\nIm Endeffekt ist es so: Je weniger Äxte sie herumschwingen, desto besser.", sourceObjective = "Verteidiger Mordun möchte, dass Ihr Burg Utgarde betretet und 5 Waffen der Vrykul stehlt.", progress = "Habt Ihr Euch ein paar dieser Vrykuläxte gekrallt?", completion = "<Mordun pfeift.>\n\nSeht Euch die nur mal an! Unglaublich.\n\nIch hatte eigentlich erwartet, dass diese Steinzeitmenschen mit Knüppeln herumfuchteln und Steine werfen.\n\nKein Glück...", sourceObjectiveStatus = "unverified-source-field" }
quests[13206] = { id = 13206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abrüstung", description = "Wir müssen hinter das Geheimnis der Waffen dieser Barbaren kommen!\n\nWenn Ihr nur gesehen hättet, wie leicht sie meine Gefährten in Stücke schnitten, würdet Ihr verstehen, weshalb ich so dränge.\n\nSucht den Ort ab. Sammelt so viele ihrer Waffen, wie Ihr nur tragen könnt.", sourceObjective = "Dunkelläuferin Marrah möchte, dass Ihr 5 Waffen der Vrykul aus Burg Utgarde stehlt und sie ihr in Burg Utgarde bringt.", progress = "Konntet Ihr ihre Waffen stehlen?", completion = "Jede Waffe, die wir ihnen abnehmen, wird nicht im Fleisch eines Soldaten landen.\n\nDanke.", sourceObjectiveStatus = "unverified-source-field" }
quests[13207] = { id = 13207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hallen des Steins", description = "Also ich bin überrascht, an einem Ort wie diesem andere Abenteurer anzutreffen.\n\nWenn meine Untersuchungen über diese Hallen stimmen, dann sind hier gewaltige Entdeckungen zu machen!\n\nIhr könnt gerne mitkommen, wenn ich mich darauf verlassen kann, dass Ihr mir Rückendeckung gebt.", sourceObjective = "Brann Bronzebart möchte, dass Ihr ihn bei der Suche nach den Geheimnissen, die in den Hallen des Steins verborgen liegen, begleitet.", progress = "Tja, nun, es hat sich letztlich als gut herausgestellt, dass wir uns begegnet sind.", completion = "Gibt immer mehr Fragen als Antworten, nicht wahr, Kamerad?", sourceObjectiveStatus = "unverified-source-field" }
quests[13211] = { id = 13211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Feuer wird Euch läutern", description = "Die Geißel benutzt unsere eigenen Gefallenen gegen uns, indem sie sie als Ghule oder Skelette wiederauferstehen lässt oder ihre Körper zerlegt und die Einzelteile benutzt, um neue Monstrositäten herzustellen. Das muss aufhören!\n\nDie Toten sind Helden, die in Verteidigung allen Lebens fielen und ein solch grausiges Schicksal muss ihnen erspart bleiben. Darüber hinaus können wir es uns einfach nicht leisten, ihnen im Feld erneut gegenüberzustehen, als Waffen gegen uns eingesetzt. Nehmt diese Fackel mit Euch in die Fleischwerke und verbrennt alle Leichen, die Ihr im Sanktum der Reanimation oder im Monstrositätenlabor finden könnt.", sourceObjective = "Kreuzfahrer Olakin Sainrith bei der Schwarzwacht möchte, dass Ihr mithilfe Olakins Fackel 7 eitrige Leichen verbrennt.", completion = "<Kreuzfahrer Olakin Sainrith hört aufmerksam zu, während Ihr Bericht erstattet.>\n\nEs ist nicht das Begräbnis, das sie verdient hätten, aber es ist besser als nichts und besser für die, die noch leben. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13212] = { id = 13212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Brüche gegangen", description = "Die Entführung des Kreuzzüglers Olakin lässt die Streitkräfte des Argentumkreuzzugs beim letzten Sturm auf die Fleischwerke führerlos dastehen. Obwohl für mich ein Kreuzzügler aussieht wie der andere, sehen die Argentumsoldaten das anders.\n\nEs gefällt mir gar nicht, unsere Zeit mit einer Schnitzeljagd zu verschwenden, aber ich habe keine andere Wahl. Unser heldenhafter Kreuzzügler wurde vermutlich schon längst in seine Einzelteile zerlegt und seine Überreste beim Zusammenbau von Monstrositäten verwendet. Geht hinunter in die Fleischwerke, tötet die Schrecken, die unsere Truppen bekämpfen, und bringt Olakins Körperteile zurück.", sourceObjective = "Bergt Olakins Oberkörper, Olakins Beine, Olakins linken Arm und Olakins rechten Arm und bringt sie der Dunkelreiterin Arly in der Schwarzwacht.", progress = "Habt Ihr die, äh, Überreste von Kreuzfahrer Olakin?", completion = "Nun, ich denke, es ist gut, dass wir den Kreuzfahrer \"gerettet\" haben, obwohl ich bezweifle, dass es dies war, was seine Kameraden im Sinn hatten. Dann lasst uns mal sehen, was wir tun können, um ihn wieder auf die Beine zu bringen, damit wir diese Farce hinter uns bringen und unsere Mission hier vollenden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13213] = { id = 13213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf bei Valhalas", description = "Ich sehe und höre viele Dinge, {name}, und etwas sehr Wichtiges ist passiert, seitdem Ihr Oberthan Balgarde besiegt habt: Man will gegen Euch in Valhalas kämpfen!\n\nDie Kampfgrube befindet sich gen Norden. Geht jetzt, nehmt Eure Freunde mit, und sprecht mit Geirrvif der Val'kyr. Bei den Herausforderern, die sie gegen Euch in den Ring werfen wird, werdet Ihr sicherlich Unterstützung brauchen.\n\nViel Glück.", sourceObjective = "Sprecht mit Geirrvif in Valhalas.", completion = "Ihr habt unsere besten Kämpfer besiegt. Euer Name ist in aller Munde, {name}.\n\nWomöglich denkt Ihr, das mich das stört - doch das tut es nicht. Wenn sie Euch unterliegen, dann sind sie unwürdig und nichts weiter als niedere Vargul!\n\nDoch vielleicht kann ich Euch und Euren Freunden etwas anderes geben, mit dem Ihr Euch vergnügen könnt. Valhalas ist unter anderem ein Ort, in dem Kämpfe jeglicher Art mit verschiedenartigen Gegnern geboten werden.\n\nSprecht mich wieder an, wenn Eure Freunde und Ihr bereit seid weiterzumachen. Wir werden sehen, ob Ihr wahrhaftig würdig seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[13214] = { id = 13214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf bei Valhalas: Gefallene Helden", description = "Wenn Ihr glaubt, soweit zu sein, dann habe ich genau den richtigen Kampf für Euch, um Euch Eure ersten Sporen zu verdienen.\n\nEine andere Gruppe von Außenseitern dachte, sie wären bereit, sich der Härte Valhalas zu stellen. Sie schwangen große Reden und fielen am Ende doch wie all die anderen vor ihnen.\n\nWenn Ihr Euch für so anders haltet - wenn Ihr glaubt, Ihr hättet die Fähigkeiten und die Erfahrung, hier gegen solch sagenumwobene Krieger anzutreten - dann nehmt die Herausforderung bitte an.", sourceObjective = "Geirrvif in Valhalas hat Euch dazu herausgefordert, im Einzelkampf alle sechs gefallenen Helden zu besiegen: Eldreth, Geness Halbseele, Jhadras, Masud, Rith und Talla.\n\nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.", completion = "Frischfleisch.\n\n<Der Todesritter der Vrykul spuckt Euch vor die Füße.>\n\nIhr denkt alle, dass Ihr das Zeug dazu habt, hier zu kämpfen.\n\nIhr seid nichts angesichts der Macht der Vrykul und der Geißel!\n\nDoch immerhin habt Ihr es geschafft, sechs inkompetente Leichen zu besiegen - Ihr müsst also was können. Doch höchstwahrscheinlich nicht genug für das, was als nächstes kommen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[13215] = { id = 13215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf bei Valhalas: Khit'rix der Dunkle Meister", description = "Verschiedene Wesen reisen um die ganze Welt, um sich in Valhalas selbst zu beweisen; einige kommen sogar aus der Unterwelt.\n\nKhit'rix der Dunkle Meister ist so einer.\n\nEr ist in den Tiefen dieser Erde geboren, dort, wo Wahnsinn herrscht, und er verlangt nach jemandem, der anders als die meisten ist und sich ihm im Ring stellen wird. Ihr werdet genügen.\n\nWagt Ihr es, {race}, dem nerubischen Alptraum gegenüberzutreten?", sourceObjective = "Geirrvif in Valhalas hat Euch dazu herausgefordert, Khit'rix den Dunklen Meister zu vernichten.\n\nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.", completion = "Ihr wollt mich damit beeindrucken, dass Ihr gemeinsam mit Euren Freunden einen einzelnen nerubischen Priester umhauen konntet?\n\nGeht mir aus den Augen, bevor ich meine Ghule auf Euch hetze!", sourceObjectiveStatus = "unverified-source-field" }
quests[13216] = { id = 13216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf bei Valhalas: Die Rückkehr von Sigrid Eiskind", description = "Ein alter Feind von Euch ist zurückgekehrt: Sigrid Eiskind. Vielleicht könnt Ihr Euch noch daran erinnern, wie Ihr sie auf der Wilden Klippe besiegt habt?\n\nEgal, sie kann sich noch sehr gut an Euch erinnern. Sie besteht darauf, sich noch einmal beweisen zu dürfen.\n\nIch persönlich denke, dass es eher um Rache geht, doch auch das kann hier nützlich sein.\n\nIch überlasse es Euch, {name}. Werdet Ihr Euch einmal mehr Sigrid Eiskind stellen?", sourceObjective = "Geirrvif in Valhalas hat Euch dazu herausgefordert, Sigrid Eiskind zu vernichten.\n\nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.", completion = "Der Sieg über eine der Hyldnir ist schon ein bisschen beeindruckend, {race}, aber Ihr hattet die Hilfe Eurer Freunde.\n\nIhr hattet Glück, dass Ihr Drache nicht mit von der Partie war.", sourceObjectiveStatus = "unverified-source-field" }
quests[13217] = { id = 13217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf bei Valhalas: Massaker!", description = "Ihr habt es zwar bis hierher geschafft, {name}, doch um weiterhin in Valhalas zu kämpfen, müsst Ihr einem gigantischen Schrecken gegenübertreten, wie Ihr ihn Euch gar nicht vorstellen könnt.\n\nIch muss Euch dazu raten, jetzt kehrt zu machen. Massaker ist ein Fleischberg, erschaffen von den grausamsten Köpfen, die im Dienste des Lichkönigs stehen.\n\nIch kann mir nicht vorstellen, wie Eure Freunde und Ihr ihn besiegen wollt. Die Entscheidung liegt jedoch bei Euch.", sourceObjective = "Geirrvif in Valhalas hat Euch dazu herausgefordert, Massaker zu vernichten.\n\nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.", completion = "Euer Können im Ring flößt mir langsam Respekt ein, {name}. Jetzt kann ich Euch wirklich nicht leiden.\n\nIch hätte es lieber gehabt, Eure Freunde und Euch an der Fußsohle dieses Fleischriesens kleben zu sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13218] = { id = 13218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf bei Valhalas: Than Todesstoß", description = "Die Vrykul von Jotunheim haben nicht übersehen, welches Können Ihr an den Tag legt, {name}. Than Banahogg hat ein persönliches Interesse an Euch gezeigt und darauf bestanden, Euer nächster Gegner zu sein.\n\nWenn Ihr Massaker schlimm fandet, dann wäre es wohl besser, wenn Ihr jetzt nach Hause geht. Than Banahoggs Spitzname ist \"Todesstoß\". Ich denke, Ihr könnt erraten, wie er sich den verdient hat.\n\nAkzeptiert Ihr die Herausforderung des Thans?", sourceObjective = "Geirrvif in Valhalas hat Euch dazu herausgefordert, Than Banahogg den \"Todesstoß\" zu besiegen.\n\nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.", completion = "Ich weiß nicht, welche Tricksereien Ihr aus dem Ärmel gezogen habt, um den Than umzuhauen - von hier aus konnte ich's nicht sehen -, doch ich kann Euch versichern, dass Ihr Euren nächsten Kampf nicht überleben werdet.\n\nJa, ich weiß, wer es ist. Rennt, {race}, rennt weg! Flieht in die letzten Ecken dieser Welt.\n\nOder bleibt und sterbt - mir ist es gleich.", sourceObjectiveStatus = "unverified-source-field" }
quests[13219] = { id = 13219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf bei Valhalas: Letzte Herausforderung", description = "Ich fürchte, dass Euer Erfolg auch Euer Untergang sein wird, {name}.\n\n<Könnte die Val'kyr noch bleicher werden, dann würde sie das gerade.>\n\nNachrichten über Euren Erfolg in Valhalas sind bis tief in die Eiskronenzitadelle vorgedrungen und haben jemanden wachgerufen, den Ihr lieber nicht kennen möchtet.\n\nPrinz Sandoval höchstpersönlich ist in diesem Augenblick auf dem Weg hierher. Gjonner hat Euch gewarnt und gesagt, dass Ihr wegrennen solltet, und ich kann ihm nicht widersprechen.\n\nWas werdet Ihr tun? Er ist auf dem Weg hierher. Werdet Ihr Euch dem Blutprinzen im letzten Kampf entgegenstellen?", sourceObjective = "Geirrvif in Valhalas hat Euch dazu herausgefordert, Prinz Sandoval zu besiegen.\n\nSprecht mit Gjonner dem Erbarmungslosen am südlichen Rand von Valhalas, solltet Ihr erfolgreich sein.", completion = "Euer Sieg über Prinz Sandoval macht mich krank. Ein ungewaschener Bauer wie Ihr es seid hätte freiwillig sein Leben dafür geben sollen, auch nur die Chance zu bekommen, ihm begegnen und vor seinen Füßen niederknien zu dürfen.\n\nIhr habt Eure verdammte Belohnung verdient. Entscheidet Euch schnell.", sourceObjectiveStatus = "unverified-source-field" }
quests[13220] = { id = 13220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Olakin wieder zusammensetzen", description = "Wir können es uns nicht leisten, irgendwelche Zeit zu verlieren und Olakin wieder zusammenzusetzen. Zum Glück bietet Euch die Geißel den perfekten Ort, um ihn wieder zusammenzuflicken.\n\nIn der Nähe des Fleischriesenlabors in den Fleischwerken befindet sich das Sanktum der Reanimation. Sucht in der Gegend nach einer Garnspule und dem Spalter des Doktors. Bringt anschließend Olakins sterbliche Überreste zur großen Platte in der Mitte des Sanktums und macht Euch an die Arbeit.", sourceObjective = "Beschafft Euch eine Garnspule und den Spalter des Doktors. Geht dann zur Steinplatte des Sanktums der Reanimation und versucht, Kreuzfahrer Olakins sterbliche Überreste wiederzubeleben. Kehrt zu Dunkelreiterin Arly in die Schwarzwacht zurück, sobald die Aufgabe vollbracht ist.", completion = "Olakin sollte sich glücklich schätzen. Niemand wird aus den Fängen der Geißel befreit, niemand. Kein Garn der Welt und keine heldenhafte Tat wird ihn jedoch ein zweites Mal retten. Ich werde dafür sorgen, dass er sich daran erinnert.", sourceObjectiveStatus = "unverified-source-field" }
quests[13221] = { id = 13221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch bin ich nicht tot!", description = "Das Licht ist mir hold. Noch bin ich in diesem wahrgewordenen Alptraum nicht umgekommen, doch die Geißel wird mich mit Sicherheit töten und meinen Körper in Stücke reißen und in ihrem 'Werk' verwenden, wenn es mir nicht gelingt, zu entkommen.\n\nAlleine werde ich es nicht schaffen, mein Kind, aber mit Eurer Hilfe könnte ich überleben, auf dass ich der Geißel erneut entgegentreten kann.\n\nWerdet Ihr mir helfen, zu entkommen, bevor die Schlächter der Geißel eintreffen, um mich zu erledigen?", sourceObjective = "Bringt Vater Kamaros in Sicherheit und erstattet dann Absalan dem Frommen an Bord der Himmelsbrecher Bericht.", completion = "Dem Licht sei Dank. Ich glaubte, Vater Kamaros sei tot, oder ihm sei noch Schlimmeres zugestoßen. Eure Tapferkeit und Euer Mitgefühl haben dazu geführt, dass ein wichtiger Verbündeter zum Argentumkreuzzug zurückkehren konnte. Ihr habt meinen Dank und den des Kreuzzugs.", sourceObjectiveStatus = "unverified-source-field" }
quests[13222] = { id = 13222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerungsmaschinen verteidigen", description = "An vorderster Front, {name}! Wir starten unseren Angriff auf die Tausendwinterfestung. Diese barbarischen Hordler denken wohl, sie könnten sich feige hinter ihren Mauern verkriechen? Nun, ich denke nicht! Wir werden ihnen zeigen, wie mächtig gnomische Technologie ist, und ihre Mauern zertrümmern!\n\nDoch ohne Mannschaft ist selbst die stärkste Belagerungsmaschine hilflos ausgeliefert. Steuert oder beschützt eine unserer Belagerungsmaschinen - es müssen drei Gebäude der Horde zerstört werden.", sourceObjective = "Chefdemolierer Legoso in Tausendwinter möchte, dass Ihr eine Belagerungsmaschine steuert oder beschützt. Die Maschine muss drei Gebäude zerstören.\n\nSpieler, die den Rang \"Gefreiter\" oder höher besitzen, können Belagerungsmaschinen in Goblinwerkstätten bauen.", completion = "Das sollte ihnen zeigen, wie mächtig gnomische Erfindungen sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[13223] = { id = 13223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerungsmaschinen verteidigen", description = "Die Allianz die Festung nicht mehr lange halten wird. Murp würde Mauern kaputt hauen, doch Murp muss im Lager bleiben. Murp wünscht sich, er könnte Allianzler kaputt hauen, die Verwüster von Horde wehtun wollen.\n\nDu, {name}! Du gehst anstatt Murp. Beschütz 3 Belagerungsmaschinen, wenn die gerade die Allianzgebäude kaputt machen. Zeig der Allianz wie klug Murp ist!", sourceObjective = "Leutnant Murp in Tausendwinter möchte, dass Ihr eine Belagerungsmaschine steuert oder verteidigt. Die Maschinen müssen 3 Gebäude der Allianz zerstören.\n\nBelagerungsmaschinen können von Spielern der Horde, die einen Rang haben, in Goblinwerkstätten gebaut werden.", completion = "Gute Arbeit. Murp wäre gern dabei gewesen, um zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13224] = { id = 13224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orgrims Hammer", description = "Der Argentumkreuzzug hat meinen böse zugerichteten Körper von der Zerbrochenen Front hergeschleppt. Was für ein ruhmreicher Kampf, {race}. Meine Axt sang, als sie ohne Unterschied Allianzabschaum und Geißler niedermachte.\n\nMeine Zeit ist vorüber. Es wird ein guter Tod sein. Überbringt eine Nachricht für mich, Soldat.\n\nUnsere Basis fliegt außerhalb der Reichweite der Geißel - hoch droben, zwischen Mord'rethar und Aldur'thar. Sie wird \"Orgrims Hammer\" genannt.\n\n<Hork bemüht sich vergeblich, zu salutieren.>\n\nFliegt hoch und geht dem Monstervehikel der Allianz aus dem Weg, der Himmelsbrecher. Sagt Korm... Sagt ihm, dass ich gestorben bin... im Kampf... Für die Horde.", sourceObjective = "Sucht Himmelshäscher Korm Schwarznarbe an Bord der Orgrims Hammer über dem Eiskronengletscher auf.", completion = "<Korm salutiert.>\n\nVerdammt soll die Geißel sein - und die Allianz! Hork war einer unserer Besten. Wir werden unsere Rache haben. Für Höllschrei und für die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[13225] = { id = 13225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Himmelsbrecher", description = "Wir steckten bis zum Hals in Einheiten der Geißel und der Horde. Die Schreie der Sterbenden erfüllten das Feld. Es war die reine Folter... erbarmungslos!\n\nMein Körper hat einfach irgendwann aufgegeben und ich fiel. Der Argentumkreuzzug hat mich wieder zurückgeholt. Sie haben mich von der Zerbrochenen Front geholt und hergebracht. Ich werde es aber nicht schaffen. Bitte, gewährt Ihr einem sterbenden Soldaten einen letzten Wunsch, {race}? Unsere Basis, die Himmelsbrecher, fliegt über der Eiskrone. Dort werdet Ihr meinen befehlshabenden Offizier, Stabshauptmann Bartlett antreffen. Sagt ihm, dass ich als Soldat der Allianz gestorben bin.", sourceObjective = "Sprecht mit Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher, die über der Eiskrone fliegt.", completion = "<Stabshauptmann Bartlett salutiert.>\n\nEr war ein verdammt guter Soldat. Verflucht sei die Horde und verflucht sei die Geißel!", sourceObjectiveStatus = "unverified-source-field" }
quests[13226] = { id = 13226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tag der Abrechnung kommt!", description = "Alleine können wir den Lichkönig nicht besiegen. Uneinigkeit ist unser Untergang!\n\nIch beschwöre Euch, <Bruder/Schwester>, folgt dem Ruf. Der Argentumkreuzzug nimmt jeden in seine Reihen auf, der sich als Freiwilliger zur Teilnahme an den Kampfmaßnahmen meldet. Hochlord Tirion Fordring selbst erwartet Euch an der Argentumvorhut! Nehmt Euer Reittier und fliegt zu den südöstlichen Ausläufern der Eiskrone. Dort werdet Ihr Lord Fordring und die Soldaten des Argentumkreuzzugs antreffen.\n\nGeht jetzt, {class}, der Tag der Abrechnung steht bevor!", sourceObjective = "Meldet Euch bei Hochlord Tirion Fordring an der Argentumvorhut in Eiskrone.", completion = "Meine treuen Ritter haben mir einen guten Dienst erwiesen. Es scheint, dass Ihre Anwerbungsbemühungen uns einen Helden beschert haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[13227] = { id = 13227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tag der Abrechnung kommt!", description = "Alleine können wir den Lichkönig nicht besiegen. Uneinigkeit ist unser Untergang!\n\nIch beschwöre Euch, <Bruder/Schwester>, folgt dem Ruf. Der Argentumkreuzzug nimmt jeden in seine Reihen auf, der sich als Freiwilliger zur Teilnahme an den Kampfmaßnahmen meldet. Hochlord Tirion Fordring selbst erwartet Euch an der Argentumvorhut! Nehmt Euer Reittier und fliegt zu den südöstlichen Ausläufern der Eiskrone. Dort werdet Ihr Lord Fordring und die Soldaten des Argentumkreuzzugs antreffen.\n\nGeht jetzt, {class}, der Tag der Abrechnung steht bevor!", sourceObjective = "Meldet Euch bei Hochlord Tirion Fordring an der Argentumvorhut in Eiskrone.", completion = "Meine treuen Ritter haben mir einen guten Dienst erwiesen. Es scheint, dass Ihre Anwerbungsbemühungen uns einen Helden beschert haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[13228] = { id = 13228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zerbrochene Front", description = "Welche Schlacht?! Diese Truppen waren auf Aufklärungsmission!\n\nUnd was soll das Gerede von wegen Allianz?\n\nJetzt hört mir mal zu, {name}! Ich muss wissen, was hier vor sich geht und ich muss es JETZT wissen!\n\nBewegt Euch und besorgt mir ein paar Antworten! Durchkämmt das Schlachtfeld und sucht nach Überlebenden - Hinweisen - irgendwas etwas!", sourceObjective = "Korm Schwarznarbe an Bord der Orgrims Hammer möchte, dass Ihr Euch an die Zerbrochene Front begebt und einen sterbenden Berserker dazu befragt, was geschehen ist.", completion = "Sie haben gesehen, dass die Allianz das Tor angegriffen hat und sie sind ihnen in den Rücken gefallen...\n\n<Nach einer kurzen Pause bricht Korm in Gelächter aus.>\n\nDAS ist genau das, wofür die HORDE steht!\n\nWenn sie nicht gewesen wären, so würden die Allianzmaden nun vermutlich das Tor halten!\n\nIhr Mut hat uns kostbare Zeit verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[13229] = { id = 13229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch bin ich nicht tot!", description = "Das Licht ist mir hold. Noch bin ich in diesem wahr gewordenen Alptraum nicht umgekommen, doch die Geißel wird mich mit Sicherheit töten und meinen Körper in Stücke reißen und in ihrem 'Werk' verwenden, wenn es mir nicht gelingt, zu entkommen.\n\nAlleine werde ich es nicht schaffen, {class}, aber mit Eurer Hilfe könnte ich überleben, auf dass ich der Geißel erneut entgegentreten kann.\n\nWerdet Ihr mir helfen, zu entkommen, bevor die Schlächter der Geißel eintreffen, um mich zu erledigen?", sourceObjective = "Bringt Vater Kamaros in Sicherheit und erstattet dann Bruder Keltan an Bord der Orgrims Hammer Bericht.", completion = "Ihr habt gute Arbeit geleistet. Wir glaubten Vater Kamaros verloren. Eure Tapferkeit wird allen denen, die sich der Geißel widersetzen, als Beispiel dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13230] = { id = 13230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rächt mich!", description = "Ich kann sie hören, <Bruder/Schwester>...\n\nDas Stöhnen der verwundeten Allianzler... Sie verspotten mich...\n\nBeendet, was wir hier begonnen haben, {class}. Zeigt keine Gnade... Lasst niemanden am Leben.\n\nFür die Horde...", sourceObjective = "Ein sterbender Berserker hat Euch darum gebeten, 5 sterbende Soldaten an der Zerbrochenen Front zu töten. Erstattet Himmelshäscher Korm Schwarznarbe auf der Orgrims Hammer Bericht, sobald dies erledigt ist.", completion = "Die Zeiten der Toleranz gegenüber der Allianz sind vorbei, {name}.\n\nSie haben unseren Hass verdient! Sie sollen in Angst vor der Horde zittern, solange, bis sie nicht länger unsere Welt verschmutzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13231] = { id = 13231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zerbrochene Front", description = "Was?! Neeeiinn!\n\nWir haben uns doch solche Mühe gegeben, diesen Angriff geheim zu halten. Woher wusste die Horde Bescheid? Die Reserven... Die Männer... Alles verloren? Unfassbar!\n\nUnsere Pläne in Eiskrone basierten darauf, dass das Tor vor der Horde genommen werden würde. Wir müssen uns schnell neu formieren und uns darauf vorbereiten, eine weitere Offensive zu starten.\n\nBegebt Euch zum Schlachtfeld und sucht nach Überlebenden. Versucht, so viele Informationen wie möglich über diese Tragödie zu sammeln.\n\nUnd macht Euch bereit, {name}, für einen Krieg - an zwei Fronten...", sourceObjective = "Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher möchte, dass Ihr Euch an die Zerbrochene Front begebt, den sterbenden Soldaten befragt und ihm dann erneut Bericht erstattet.", completion = "Wir mussten also eine Schlappe einstecken - eine verheerende Niederlage... Dies wird nicht vergessen werden.\n\nMerkt Euch meine Worte, {class}. Die Horde wird hierfür bezahlen... Es wird keine Gnade geben!", sourceObjectiveStatus = "unverified-source-field" }
quests[13232] = { id = 13232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet mich!", description = "Sie verspotten uns - selbst noch hier, während sie im Sterben liegen...\n\nIch bitte Euch... Lasst es nicht zu, dass ihr Spott das Letzte sein wird, was ich höre...\n\nTötet mich... erlöst mich von dieser Qual... und führt mich... zum Licht.\n\nGeht zu meinen Gefährten... gewährt ihnen dieselbe Gnade.\n\nHinterlasst der Geißel nichts, das sie wiederbeleben könnte!\n\nIch flehe Euch an...", sourceObjective = "Der sterbende Soldat an der Zerbrochenen Front möchte, dass Ihr 5 sterbende Soldaten erlöst und dann Stabshauptmann Justin Bartlett auf der Himmelsbrecher Bericht erstattet.", completion = "Was Ihr getan habt, war nicht einfach, {class}, aber das Richtige.\n\nLasst Euch von den Erinnerungen an das, was Ihr getan habt, nicht quälen. Nutzt Eure Gefühle aus - den Kummer und den Schmerz! Nutz sie aus und richtet sie gegen die Schuldigen.\n\nDie Horde muss bezahlen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13233] = { id = 13233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Gnade!", description = "Es ist, wie ich es Euch gesagt habe. Es waren nicht nur leere Worte, im Zorn gesprochen.\n\nWieder und wieder hat die Horde gezeigt, dass sie nichts auf das gibt, was uns am Herzen liegt. Für ihre Sünden gegen das Licht müssen sie mit dem Leben zahlen!\n\nJeder einzelne von ihnen.\n\nStellt Euch nur vor, {name}, eine Welt ohne ihren Makel. Malt Euch aus, wie glücklich unsere Kinder aufwachsen könnten. Denkt daran, wie ehrfürchtig Eure Nachkommen Euren Namen aussprechen würden - da sie doch wissen, dass sie all ihr Glück nur Euch zu verdanken haben.\n\nGeht nun und lasst die Vision Realität werden!", sourceObjective = "Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher möchte, dass Ihr in Eiskrone 15 Spieler der Horde tötet.", completion = "Gut gemacht, {name}!\n\nBringt sie zur Strecke und lasst sie dafür bezahlen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13234] = { id = 13234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie müssen zahlen!", description = "Die Zeit ist gekommen!\n\nViel zu lange mussten wir die Selbstgerechtigkeit der Allianz ertragen! Viel zu lange mussten wir uns zurückhalten, haben unsere Welt nicht von Schwachen und Verzweifelten gereinigt.\n\nJetzt endlich werden wir die Erniedrigung beenden! Jetzt werden wir ihnen die wahre Bedeutung von Angst zeigen! Jetzt werden wir der Horde Ehre machen!\n\nHier, in Eiskrone, werden wir die Allianz brechen!\n\nGeht, {class}. Geht und bringt sie zur Strecke. Brecht sie! Nehmt ihnen den Willen zu leben!", sourceObjective = "Himmelshäscher Korm Schwarznarbe möchte, dass Ihr 15 Spieler der Allianz in Eiskrone tötet.", completion = "Ihr habt gute Arbeit geleistet, {class}.\n\nSchon bald wird die Allianz ängstlich vor Euch flüchten und die Horde wird Euren Namen ehren!", sourceObjectiveStatus = "unverified-source-field" }
quests[13235] = { id = 13235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gigantische Fleischgigant", description = "Mit der Zerstörung der Fleischwerke und der Vernichtung der Diener des Lichkönigs habt Ihr gute Arbeit geleistet. Nun ist alles, was noch zu tun bleibt, die Vernichtung des Meisterwerks der Fleischwerke - die Vernichtung des Fleischgiganten namens Morbidus.\n\nEs wird kein einfacher Kampf sein, doch das Schattengewölbe hat Markgraf Dhakar mit ein paar Unterstützungstruppen entsandt. Trefft Euch mit ihm beim höchsten Punkt der Fleischwerke am westlichen Rand. Sagt ihm Bescheid, wenn Ihr angriffsbereit seid, und er wird seine Truppen in die Schlacht schicken.", sourceObjective = "Sprecht mit Markgraf Dhakar am westlichen Ende der Fleischwerke, um die Aufmerksamkeit von Morbidus zu erregen. Erstattet der Dunkelreiterin Arly an der Schwarzwacht Bericht, nachdem Ihr Morbidus getötet habt.", completion = "Nun da des Lichkönigs Fleischgigant vernichtet ist, muss ihm klar sein, dass auch der Rest seiner Truppen nicht unverwundbar ist. Mit Euch an unserer Seite wird es uns gelingen, den Lichkönig erneut das Fürchten zu lehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13236] = { id = 13236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armee der Verdammten", description = "Ihr glaubt wahrscheinlich, Ihr wärt ziemlich stark - wie Ihr so gegen diese Untoten kämpft und ihre Knochen mit Euren Kriegsmaschinen zermalmt.\n\nDas ist jedoch nichts im Vergleich mit der Stärke, der es bedurfte, um sie zu erschaffen.\n\nIch habe gesehen, wie der Prinz selbst es gemacht hat. Ich kann Euch zeigen, wie das geht... wenn Ihr wollt.", sourceObjective = "Matthias Lehner im Vorhutslager der Ersten Legion möchte, dass Ihr eine Armee von 100 ghulischen Dienern auferstehen lasst.", completion = "Die wahre Macht des Prinzen lag nicht darin, aus Leichen Armeen zu erschaffen... das war einfach.\n\nAber seine eigenen Männer zu töten, diejenigen, an deren Seite er viele Kämpfe bestritten hat... Die wahre Macht des Prinzen lag darin, das tun zu können, was er tun musste.", sourceObjectiveStatus = "unverified-source-field" }
quests[13237] = { id = 13237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stechen und Stoßen", description = "Verlasst Euch drauf, während Euer Hauptmann von seinem Hass auf die Rivalen Eurer Allianz abgelenkt ist, richte ich meine volle Aufmerksamkeit auf den wahren Feind hier: den Lichkönig und seine Untergebenen.\n\nUm auch nur darauf hoffen zu können, ihn in seiner Zitadelle zu besiegen, müssen Eure Leute beide Tore erobern und halten.\n\nKonzentrieren wir uns für den Augenblick jedoch auf das Erste. Kehrt zur Front zurück und stoßt durch ihre Verteidigungslinie. Sucht nach irgendwelchen Schwachstellen, die wir ausnützen könnten.\n\nIch erwarte Euren Bericht, {class}.", sourceObjective = "Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr Euch an die Zerbrochene Front begebt und 5 bullige Monstrositäten, 5 bösartige Totenbeschwörer und 5 Schattenadepten besiegt.", completion = "Wirklich, {class}?\n\nNichts Besonderes zu berichten?\n\n\n\nDa bin ich anderer Meinung...", sourceObjectiveStatus = "unverified-source-field" }
quests[13238] = { id = 13238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu etwas zu gebrauchen?", description = "Goblins! Überdrehte Wichtigtuer...\n\nHört mal, {name}. Kupferklammer, unser Hausingenieur, besteht darauf, dass er etwas Nützliches gefunden hat, was er mir unbedingt zeigen muss.\n\nIch bin nicht in der Stimmung, mir sein piepsiges Gezeter anzuhören. Das letzte Mal, dass ich ihm Aufmerksamkeit schenkte, hat er glatt eine Stunde lang durchgequäkt. Ich konnte mich gerade noch davon abhalten, ihn mit einem Tritt in Sindragosas Sturz zu befördern!\n\nIhr werdet an meiner Statt gehen und ihm Honig ums Maul schmieren. Lasst es mich wissen, falls er tatsächlich etwas herausgefunden haben sollte.", sourceObjective = "Himmelshäscher Korm Schwarznarbe möchte, dass Ihr mit dem Chefingenieur Kupferklammer an Bord der Orgrims Hammer sprecht.", completion = "Zu beschäftigt? Pühhh! Das Baby hier fliegt sich doch selbst!\n\nVergesst das. Ihr tut's auch...", sourceObjectiveStatus = "unverified-source-field" }
quests[13239] = { id = 13239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verflüchtigung", description = "Wo soll ich anfangen...? Nun, Ihr müsst wissen, dass ich als Chefingenieur dieses Fahrzeugs Zugang zu allen möglichen nachrichtendienstlichen Berichten habe – ja, ja, es ist wahr, und seit Kurzem interessiere ich mich ganz besonders für die Frostwyrms, die Ihr im Süden gesichtet habt. Ich denke, ich habe einen Plan entwickelt, wie ihnen beizukommen sein könnte... Gut, ein paar Kleinigkeiten müssen noch von Euch erledigt werden, aber eigentlich nur Folgendes: Ihr baut eine Attrappe aus Rüstungsteilen und bestreicht sie mit dieser Lösung hier und dann geht Ihr in Deckung!\n\n... Immer noch da, {race}?", sourceObjective = "Chefingenieur Kupferklammer möchte, dass Ihr Kupferklammers flüchtiges Öl an der Zerbrochenen Front benutzt um 3 Frostbrutvollstrecker anzulocken.\n\nUm das Öl benutzen zu können, müsst Ihr auf dem Schlachtfeld einen Knochenhaufen, einen zurückgelassenen Helm und zurückgelassene Rüstung einsammeln.", completion = "Juhuu! Ich hab' von hier aus gesehen, wie sie in Flammen aufgegangen sind! Ich werde das mal als weiteren Erfolg verzeichnen und anfangen, das Zeug für die Invasion abzufüllen - obwohl es natürlich noch einiger weiterer Versuche bedarf, wenn es Euch interessiert...", sourceObjectiveStatus = "unverified-source-field" }
quests[13240] = { id = 13240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timear prophezeit Zentrifugenkonstrukte in Eurer Zukunft!", description = "Ihr müsst zum Oculus über Kaltarra reisen, {name}.\n\nIch habe eine Situation vorausgesehen, in der Ihr die dortigen Zentrifugenkonstrukte zerstören müsst. Ich kann Euch versichern, dass, solltet Ihr nicht zuerst diese magischen Schöpfungen beseitigen, Eure Gruppe versagen wird.\n\nDies habe ich gesehen und dies müsst Ihr tun.", sourceObjective = "Erzmagier Timear in Dalaran hat vorausgesehen, dass Ihr 10 Zentrifugenkonstrukte zerstören müsst.", completion = "<Der Erzmagier nickt, bevor Ihr überhaupt etwas gesagt habt.>\n\nIch weiß. Ihr habt die Konstrukte, wie ich vorhergesehen habe, zerstört und konntet dann dazu überschreiten, gegen Varos Wolkenwanderer zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13241] = { id = 13241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timear prophezeit Berserker der Ymirjar in Eurer Zukunft!", description = "In nicht allzu ferner Zukunft werden zwischen Euch und dem Sieg lediglich König Ymirons Champions stehen.\n\nIhr werdet zur Festung namens Turm Utgarde tief in den Wäldern des Heulenden Fjords reisen. Ich kann nicht genug betonen, wie wichtig es ist, dass Ihr und Eure Reisegefährten Euch um die dortigen Berserker der Ymirjar kümmert.\n\nSolltet Ihr dies versäumen, ist es gut möglich, dass es Euch zum Verhängnis werden wird, {name}!", sourceObjective = "Erzmagier Timear in Dalaran möchte, dass Ihr 7 Berserker der Ymirjar tötet.", completion = "Ausgezeichnete Arbeit, {name}.\n\nHättet Ihr dies nicht getan, hättet Ihr im Kampf mit dem König sicherlich gegen unzählige der überlebenden Berserker kämpfen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13242] = { id = 13242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dunkelheit regt sich", description = "Die Dunkelheit regt sich, {name}. Etwas Tragisches hat sich ereignet, das niemand außer der Zeitlose selbst voraussehen hätte können. Bald wird Euer Volk von Wut und Hass erfasst werden. Krieg ist am Horizont.\n\nDer rote Drachenschwarm hat alles getan, was in seiner Macht steht. Was als Nächstes passiert, liegt in den Händen der sterblichen Völker Azeroths.\n\nLeider beginnt Eure Reise mit Schmerz. Ein Vater hat heute ein Kind verloren und Ihr müsst die schlimme Nachricht überbringen. Sammelt Saurfangs Rüstung ein und bringt sie zum Ältesten Saurfang zurück.", sourceObjective = "Geht aufs Schlachtfeld hinaus, sucht nach Saurfangs Schlachtrüstung und bringt sie zu Hochfürst Saurfang in der Kriegshymnenfestung in der Boreanischen Tundra.", progress = "<Saurfangs Miene verzieht sich.>\n\nMein Herz... meine Stärke...", completion = "<Saurfang blickt gen Himmel.>\n\nWie auch Brox, so starb auch mein Sohn als Held. Trauert nicht über ihn, {name}. Für einen Orc gibt es kein besseres Ende! Keine größere Ehre! In diesem Moment schwillt mein Herz vor Stolz.\n\nIch danke Euch dafür, dass Ihr unsere Schlachtrüstung zurückgebracht habt. Sie wird auf seinen Scheiterhaufen auf dem Ahnengrund in Nagrand gelegt werden.\n\nWir müssen unsere volle Aufmerksamkeit dringlicheren Angelegenheiten zuwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13243] = { id = 13243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timear prophezeit Ewige Agenten in Eurer Zukunft!", description = "Die Zeitlinie wird vom ewigen Drachenschwarm bedroht. Ohne Euer Eingreifen wird die Zeit zunichtegemacht werden!\n\nIhr müsst in die Höhlen der Zeit gehen und zu einem Zeitpunkt zurückreisen, an dem ein Ereignis namens 'das Ausmerzen von Stratholme' stattfand.\n\nMir bereitet es Kopfschmerzen, auch nur zu versuchen, in alle möglichen Vergangenheiten zu blicken, doch ich weiß, dass es äußerst wichtig für Euch ist, die ewigen Agenten zu töten.\n\nNur durch ihren Tod wird die wahre Vergangenheit beibehalten und Gegenwart und Zukunft werden davor bewahrt, für immer ungeschehen gemacht zu werden!", sourceObjective = "Erzmagier Timear in Dalaran hat prophezeit, dass Ihr 4 ewige Agenten töten müsst.", completion = "Für den Augenblick sind wir gerettet. Habt Dank.\n\nUnglücklicherweise bieten sich den Ewigen aufgrund der Art und Weise ihres Eingreifens beinahe endlos viele Möglichkeiten, dies wieder zu tun.\n\nWas ich erkennen kann, ist, dass in Zukunft Ihr im Herzen des Kampfes gegen sie stehen werdet, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13244] = { id = 13244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timear prophezeit Titanvorposten in Eurer Zukunft!", description = "Ganz Azeroth ist in Gefahr. Der verrückte Gott Loken besitzt die Macht, allem ein Ende zu bereiten!\n\nIm Irdischen Wachturm in den Hallen der Blitze stehen Titanvorposten kurz davor, Lokens schrecklichen Willen auszuführen - dem würden unzählige Ahnungslose zum Opfer fallen.\n\nIch habe in die Zukunft geblickt, {name}. Ihr seid <derjenige, der/diejenige> die; sich darum kümmern wird, dass dies nicht geschieht!", sourceObjective = "Erzmagier Timear in Dalaran hat prophezeit, dass Ihr 7 Titanvorposten töten müsst.", completion = "Wir stehen alle in Eurer Schuld, {name}.\n\nWenn ich mir über irgendetwas sicher bin, dann ist es das, dass Ihr uns in der Vergangenheit nicht enttäuscht habt und dies auch in Zukunft nicht tun werdet!", sourceObjectiveStatus = "unverified-source-field" }
quests[13245] = { id = 13245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Ingvar der Brandschatzer", description = "Ihr müsst eine Gruppe zusammenstellen und sie nach Burg Utgarde führen. Dort sollt Ihr dann nach Ingvar dem Brandschatzer suchen und ihn töten, bevor er mit seinen Vrykultruppen die nahegelegenen Städten der Allianz und Horde überfallen und plündern kann.\n\nIch brauche seine Axt als Beweis dafür, dass man sich um ihn gekümmert hat. Es wäre ja nicht so, dass ich Euch nicht vertrauen würde. Doch es ist einfach nur klug, sich absolut sicher zu sein, ob die Aufgabe nun erledigt wurde.", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit der Axt des Brandschatzers zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Habt Ihr die Axt? Ist Ingvar tot?", completion = "Sehr gut. Legt die Axt einfach bei der Wand dort drüben ab.\n\nIch bin mir sicher, dass man in Valgarde und im Hafen der Vergeltung heute Abend etwas ruhiger ist, nun, da Ihr Euch um den Barbaren gekümmert habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13246] = { id = 13246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Keristrasza", description = "Seid Ihr mit der Geschichte von Keristrasza vertraut?\n\nDamit, dass sie maßgeblich daran beteiligt war, Saragosa, Malygos' Gefährtin, zu töten? Wie er wiederum Keristrasza zur Gemahlin nahm und sie in einen Block aus Eis einschloss?\n\nWir wissen nun, dass Malygos seine Magie dazu benutzt hat, um ihren Willen zu brechen, was sie in den Wahnsinn getrieben hat.\n\n{name}, Ihr müsst in den Nexus nach Kaltarra gehen und ihr ein Ende bereiten, bevor sie komplett überläuft.\n\nZwar macht es mich traurig, doch ich muss darauf bestehen, dass Ihr mir ihr Herz als Beweis bringt.", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit Keristraszas gebrochenem Herzen zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Wenn wir einen Weg gewusst hätten, wie wir sie erlösen können, hätten wir Euch nicht darum gebeten, ihrem Leben ein Ende zu bereiten.\n\nWir wissen jedoch, wie mächtig Malygos' Beherrschung der magischen Kräfte geworden ist. Seiner Beeinflussung der Leylinen Azeroths ist es zu verdanken, dass ihm heute niemand gleich kommt, wenn es um das Arkane geht.", completion = "Bedauerlich, doch äußerst notwendig.\n\nDie Kirin Tor könnten es sich nicht leisten, einen der wichtigsten roten Großdrachen an unseren größten Feind zu verlieren. Hätte Malygos sie im Nexuskrieg gegen uns eingesetzt, wäre dies verheerend gewesen.\n\nIch bedauere es einfach, dass wir sie stattdessen nicht haben retten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13247] = { id = 13247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Leywächter Eregos", description = "Der Nexuskrieg tobt weiter und wir müssen etwas unternehmen, um das Blatt zu wenden! Seid Ihr willens, ins Herz der Schlacht zu fliegen, {name}?\n\nLeywächter Eregos ist der Beschützer des Kanals, durch den Malygos die magische Energie von Azeroths Leylinien schleust. Würde er getötet, wäre dies ein großer Rückschlag für den Feind.\n\nBitte bringt mir einen seiner Leylinienempfänger, damit wir ihn untersuchen können.", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit einem Leylinienempfänger zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Habt Ihr Euch um den Leywächter gekümmert, {class}?\n\nIch muss Euch nicht daran erinnern, dass Malygos versucht, jeglichen Gebrauch von Magie auf der Welt zu unterbinden, und dass der blaue Drachenschwarm jeden tötet, der mit ihr umgehen kann und nicht auf ihrer Seite ist.", completion = "Habt Dank, {name}. Die Untersuchung dieses Empfängers sollte uns weitere Einblicke darüber verschaffen, wie Malygos die Leylinien manipuliert.\n\nWenn wir eine Schwachstelle in seinem Ansatz finden können, wären wir vielleicht in der Lage, sie auszunutzen und das Blatt zu wenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13248] = { id = 13248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: König Ymiron", description = "König Ymiron im Turm Utgarde ist der Lieblingsvrykul des Lichkönigs. Das alleine ist Grund genug, ihm ein Ende zu bereiten.\n\nDoch sollte er die Hörner erschallen lassen und alle Anführer der Ymirjar sowie der Mjordin zu sich rufen, würden die Vrykul zu einer Macht heranwachsen, die stärker als jede andere Gruppe innerhalb der Geißel wäre!\n\nEs liegt an Euch, {name}, dafür zu sorgen, dass dies nicht geschieht. Bringt mir das Medaillon, das er um seinen Hals trägt, damit ich weiß, dass Ymiron keine Gefahr mehr darstellt.", sourceObjective = "Erzmagier Lan'dalok in Dalaran möchte, dass Ihr mit dem Medaillon der verstorbenen Königin zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Ymiron darf das Reich der Vrykul nicht vereinen. Sollte er triumphierend nach Eiskrone zurückkehren, wird sehr wahrscheinlich alles verloren sein.", completion = "<Der Erzmagier nickt ernst, als Ihr ihm das etwas große geratene Schmuckstück überreicht.>\n\nWas getan ist, ist getan. Welch edles Volk, diese Vrykul. Schade nur, dass der Lichkönig seine tödlichen Haken in sie hineingetrieben hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13249] = { id = 13249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Der Prophet Tharon'ja", description = "Einst war die Feste Drak'Tharon eine stolze Bastion des Drakkarireiches. Nun ist sie nichts weiter als ein Sprungbrett für den Lichkönig in seinem Kampf, Zul'Drak ein Ende zu bereiten und die Kräfte der Trollgötter an sich zu reißen.\n\nDoch sollten wir ihren Anführer Prophet Tharon'ja ausschalten, könnten wir vielleicht den Zustrom weiterer Trolle der Geißel verhindern. Das Mindeste, was dabei herauskommen könnte, wäre, dass der Argentumkreuzzug in Zul'Drak eine Sorge weniger hat.\n\nBringt mir sein Tiki, damit ich weiß, dass der Prophet tot ist.", sourceObjective = "Erzmagier Lan'dalok in Dalaran möchte, dass Ihr mit dem verzauberten Tiki des Propheten zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Habt Ihr Euch dem Propheten schon gestellt? Habt Ihr das Tiki bei Euch?", completion = "Mit etwas Glück wird die Feste Drak'Tharon jetzt, da sie ohne Anführer ist, ein kleineres Problem für diejenigen darstellen, die in dieser Region gegen die Geißel kämpfen.\n\n<Der Erzmagier blickt auf das Tiki in Eurer Hand.>\n\nAuch ist es gut, dass das Tiki sein Mojo verloren hat. Ich hätte keine Vorstellung davon gehabt, wie man es benutzt, geschweige denn, ob es das Richtige wäre, dergleichen zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[13250] = { id = 13250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Gal'darah", description = "Die Drakkaripropheten von Zul'Drak haben das undenkbare getan: Sie haben die meisten ihrer Götter getötet und ihre Kraft in sich aufgenommen! Der gefährlichste von allen ist Akalis Hochprophet Gal'darah.\n\nGal'darah hält sich in den Tiefen von Gundrak verborgen und hat fast das gesamte Mojo des toten Akali in sich aufgesaugt. Nun ist er kurz davor, mit seinen Anhängern aus der Stadt auszubrechen. Wenn wir ihn jetzt nicht töten, werden wir in einem Meer des Wahnsinns ertrinken und von unvorstellbarer Macht erdrückt!\n\nBeeilt Euch, {name}, bringt mir, was von Akalis Mojo übrig geblieben ist.", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit den Überresten von Akalis Mojo zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Habt Ihr das Mojo dabei?\n\nEs macht mich krank, mit ansehen zu müssen, wie ein weiteres großes Trollreich zugrunde geht.\n\nIch kann mir nur denken, dass, hätte sich der Lichkönig nicht eingemischt, die Trolle sich nicht dazu gezwungen gesehen hätten, sich gegen ihre eigenen Götter zu wenden und ihre Kraft zu stehlen, um sie als Verteidigung gegen die Geißel einzusetzen.", completion = "Habt Dank, {name}. Ich werde mich darum kümmern, dass die Essenz der Götter so lange sicher aufbewahrt wird, bis sie an den Stamm der Zandalari übergeben werden kann.\n\nVielleicht werden sie in der Lage sein, einen Weg zu finden, Akali mit dieser Essenz wieder ins Leben zu rufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13251] = { id = 13251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Mal'Ganis", description = "{name}, ein Freund innerhalb des bronzenen Drachenschwarms hat mir Informationen zukommen lassen, die wir ausnützen müssen.\n\nDie mysteriösen Geschöpfe der Brennenden Legion namens Schreckenslords werden in Hinblick auf ihre Rasse auch als die Nathrezim bezeichnet. Wenig ist über ihre Heimatwelt bekannt, und selbst das ist nur ein Gerücht.\n\nEs ist jedoch bekannt, dass Mal'Ganis in der Vergangenheit einen entscheidenden Fehler gemacht hat: er hinterließ ein Artefakt seiner Heimatwelt!\n\nÜber die Höhlen der Zeit müsst Ihr in der Zeit zurückreisen und einem Ereignis beiwohnen, das auch 'das Ausmerzen von Stratholme' genannt wird. Beschafft das Artefakt.", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit dem Artefakt aus der Heimatwelt der Nathrezim zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Wir müssen Mal'ganis' Fehler ausnutzen. Es kommt nicht jeden Tag vor, dass sich uns solch eine Chance bietet.\n\nWenn wir dieses Artefakt untersuchen können, könnten wir die Nathrezim vielleicht besser verstehen!", completion = "Erstaunlich! Ich habe noch nie etwas ähnliches gesehen. Ich werde mich darum kümmern, dass es den richtigen Händen in der Violetten Zitadelle übergeben wird.\n\nWenn man Euch nur erlaubt hätte, den Lauf der Geschichte zu ändern. Wenn man Arthas vielleicht davon abgehalten hätte... nein, so etwas führt nur ins Chaos.\n\nDie Hüter der Zeit kennen sich mit solchen Angelegenheiten am besten aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[13252] = { id = 13252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Sjonnir der Eisenformer", description = "Nur wenig ist über das Leiden bekannt, welches 'Fluch des Fleisches' genannt wird. In den Hallen des Steins gibt es jedoch Informationen zu holen.\n\nSjonnir der Eisenformer scheint sich ziemlich gut mit dem Fluch auszukennen. Wir wissen aus guter Quelle, dass er eine titanische Informationsscheibe bei sich hat, die all unsere Fragen beantworten könnte.\n\nBesorgt mir diese Scheibe, {name}, damit wir mehr erfahren können.", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit der 'Datenscheibe: Fluch des Fleisches' zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Habt Ihr die Scheibe?", completion = "Ist sie nicht erstaunlich, die Titanentechnologie? Die Informationen befinden sich in der Scheibe selbst!\n\nIch hoffe nur, wir können herausfinden, wie wir sie aus der Scheibe herausbekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13253] = { id = 13253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Loken", description = "Loken im Inneren der Hallen der Blitze steht kurz davor, unserer Welt ein Ende zu bereiten. Muss ich noch mehr sagen, {name}?\n\nEr sitzt dort und lauscht dem verrückten Geflüster des Alten Gottes, der unter Nordend gefangen ist. Ihr müsst umgehend mit einer Gruppe zu den Sturmgipfeln reisen!\n\nGeht zum Irdischen Wachturm und stellt Euch Loken zum Kampf. Haltet ihn auf, bevor es zu spät ist! Bringt mir seinen Rubinring, damit ich weiß, dass wir wieder sicher sind.", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit dem himmlischen Rubinring zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Wir sprechen wieder miteinander, {name}. Bedeutet das, dass wir vor Lokens Wahnsinn sicher sind? Oder sind wir dem Untergang geweiht.", completion = "<Erzmagier Lan'dalock seufzt vor Erleichterung.>\n\nUm ehrlich zu sein, hatte ich befürchtet, dass Euch das Schlimmste zugestoßen wäre. Es ist schwierig, untätig herumzustehen, während andere wie Ihr sich mit Angelegenheiten auseinandersetzen, bei denen es um Leben und Tod geht und die unsere Welt anscheinend tagtäglich beschäftigen.\n\nWas werden wir mit diesem gigantischen Ring jetzt bloß nur anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[13254] = { id = 13254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Anub'arak", description = "Die Neruber der Geißel sind eine Plage für unsere Truppen.\n\nHier, über der Welt schwebend, sind wir zwar vor ihnen sicher, doch setzt man seinen Fuß auf das Land unter uns, hat man ständig den Gedanken im Hinterkopf, dass die untoten Neruber aus den Tiefen Azjol-Nerubs jeden Augenblick aus der Erde springen und angreifen könnten.\n\nEs liegt im besten Interesse von uns allen, wenn sie ins Chaos gestürzt werden. Tötet ihren früheren König, den Majordomus des Lichkönigs, den Gruftlord Anub'arak.\n\nBitte bringt mir seine Krone... es wäre ja nicht so, dass er sie noch trägt.", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit der unnützen Krone Anub'araks zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Ich bin froh, dass Ihr es seid, der nach Azjol-Nerub hinabsteigt, nicht ich.\n\nIch bin nicht gerne unter der Erde.", completion = "Welchen Schrecken Ihr begegnet sein müsst, als Ihr die Oberstadt durchquert habt.\n\n<Lan'dalock wirft einen Blick auf die stumpfe Krone in Eurer Hand.>\n\nVielleicht sollten wir das für den Zeitpunkt beiseite legen, wenn sich die Neruber dazu entschließen, einen neuen König zu krönen?", sourceObjectiveStatus = "unverified-source-field" }
quests[13255] = { id = 13255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Herold Volazj", description = "Die Neruber von Ahn'kahet gruben zu tief, als sie versuchten, dem Überfall der Geißel zu entkommen. Sie kamen dem alten Gott in den Tiefen Nordends zu nah.\n\nDer Alte Gott, von ihnen wach gerufen, hetzte seine wild gewordenen Kreaturen auf sie - die Neruber saßen also sprichwörtlich in der Klemme.\n\nHerold Volazj, der Anführer der Streitkräfte des alten Gottes, ist eines der alptraumhaften Wesen, die auch die Gesichtslosen genannt werden. Beseitigt ihn und bringt mir sein verdorrtes Gehirn.\n\nNur bitte ich Euch, dass Ihr versucht, bei Verstand zu bleiben.", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit dem siechenden Gehirn des Gesichtslosen zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "{name}? Seid Ihr noch bei Verstand?", completion = "<Der Erzmagier beäugt das Gehirn misstrauisch.>\n\nWo ich gerade daran denke: Ich bin mir nicht so ganz sicher, ob man sich ohne Gefahr so nah an diesem Ding aufhalten kann. Ihr meint also, dass es noch immer am Leben ist?\n\n<Er schüttelt seinen Kopf.>\n\nWir haben einen Platz für solche Dinge hier in der Zitadelle. Ich werde mich darum kümmern, dass einer meiner Lehrlinge es umgehend dorthin bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13256] = { id = 13256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Cyanigosa", description = "Wir werden überfallen! Der blaue Drachenschwarm hat sich in die Violette Festung teleportiert und sie planen, von dort auszubrechen und sich im Rest von Dalaran zu verbreiten!\n\nEs gab schon Berichte von Gefangenen, die dadurch versehentlich befreit wurden. Es würde mich nicht wundern, wenn sie einige von ihnen absichtlich freilassen würden.\n\n{name}, könnt Ihr schnell ein Team zusammenstellen und Euch dorthin begeben? Cyanigosa ist die Anführerin der Invasionstruppen. Bringt mir ihren Kopf!", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr mit Cyanigosas Kopf zurückkehrt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden.", progress = "Wenn ich so darüber nachdenke: Weshalb würde sich jemand in ein Gefängnis hineinteleportieren, nur um dann wieder auszubrechen? Es handelt sich hier ja nur um den sichersten Ort in der ganzen Stadt.\n\nDie Blauen müssen wirklich verrückt geworden sein!", completion = "Die Gefahr ist vorüber und der Rest der Gefangenen, die ausgebrochen sind, sitzen einmal mehr im Gefängnis.\n\nDalaran schuldet Euch Dank, {name}!\n\nNun muss ich mit jemanden darüber sprechen, wieso es so einfach gewesen ist, den Teleportationsschutz des Gefängnisses zu umgehen?!", sourceObjectiveStatus = "unverified-source-field" }
quests[13257] = { id = 13257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbote des Krieges", description = "Champion, der Kriegshäuptling braucht Euch. Über Orgrimmar ist das Kriegsrecht verhängt worden. Alle Handels- und Dienstleistungsaktivitäten wurden eingestellt, während sich der Kriegshäuptling auf einen unvermeidlichen Konflikt vorbereitet.\n\nMehr kann ich Euch nicht sagen - nicht jetzt, nicht hier.\n\nDer Kriegshäuptling befiehlt, dass sich die stärksten Champions in seinem Thronsaal melden. Geht jetzt, {name}! Nehmt das Portal zurück nach Orgrimmar und sucht Thrall auf.", sourceObjective = "Meldet Euch bei Thrall in der Feste Grommash in Orgrimmar.", completion = "Dämonenfürst Varimathras und Chefapotheker Putress sind für diesen Verrat verantwortlich.\n\n<Thrall nickt.>\n\nDerselbe Putress, der auch das Heilmittel gegen die letzte Seuche der Geißel gefunden hat.\n\nDiejenigen, die sich ihrem Regime nicht anschließen wollten, sind hingerichtet oder verbannt worden. Sylvanas wurde bei dem Staatsstreich beinahe getötet.\n\nFür die Horde ist die Unterstadt verloren. Orgrimmar wird die Flüchtlinge der Verlassenen aufnehmen, bis diese Krise überwunden ist. Fürs erste stehen wir unter Kriegsrecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13258] = { id = 13258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gelegenheit", description = "Wir sind kürzlich über Schemata gestolpert, die auf eine Schwachstelle in der Eiskronenzitadelle hinweisen - eine offene Stelle in ihrer Verteidigung, bildlich und wörtlich genommen.\n\nDie Pläne, die gefunden wurden, zeigen eine Öffnung, die mehrere hundert Meter in den Boden geht. Wir sind uns nicht sicher, welchem Zweck sie dient, doch unseren Aufklärungsberichten zufolge ist sie für die Geißel äußerst wichtig.\n\nSprecht mit Unteroffizier Kregga unterhalb der Eiskronenzitadelle. Sie leitet den dortigen Angriff.", sourceObjective = "Sprecht mit Unteroffizier Kregga unterhalb der Eiskronenzitadelle.", completion = "Gerade rechtzeitig, {name}. Koltira hatte gute Worte für Euch übrig. Vielleicht werdet Ihr in der Lage sein, die Situation zu unseren Gunsten zu ändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[13259] = { id = 13259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Überlegenheit sorgen", description = "Wir haben eine einzige Chance, dieser Zitadelle ein wenig Schaden zuzufügen - sorgen wir also dafür, dass wir's richtig machen.\n\nWir sind in den Besitz von schweren Saronitbomben gelangt, die von der Geißel hergestellt wurden. Doch bevor wir sie loslassen können, müssen wir erst die Gegend sichern.\n\nWir werden die Verteidigungsstellungen der Geißel schnell unter Kontrolle bringen müssen, bevor ihre Verstärkung eintrifft.\n\nSteht meinen Männern zur Seite und kommt wieder zurück, wenn Ihr bereit für ein kleines Feuerwerk seid.", sourceObjective = "Unteroffizier Kregga an der Eiskronenzitadelle möchte, dass Ihr 10 bullige Schrecken tötet.", completion = "Ihr habt kurzen Prozess mit der Geißel gemacht, {name}. Lasst uns zu Ende bringen, weswegen wir hier sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13260] = { id = 13260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Insider", description = "Obwohl wir keine Gelegenheit auslassen sollten, der Allianz einen Schlag zu versetzen, dürfen wir auf gar keinen Fall die Geißel vergessen.\n\nWir haben zwar nicht genug Männer, um in den nächsten Wochen einen vernünftigen Ausfall in den Gletscher zu wagen, doch sollte uns das nicht davon abhalten, so viel wie möglich über ihre Verteidigung in Erfahrung zu bringen.\n\nIch habe unseren Todesritter gebeten, Euch in dieser Sache zu beraten. Schließlich kennt niemand den Feind besser als sie.\n\nErlaubt mir, Euch Koltira Todesweber vorzustellen.", sourceObjective = "Himmelshäscher Korm wünscht, dass Ihr mit Koltira Todesweber auf der Orgrims Hammer sprecht.", completion = "<Koltira mustert Euch.>\n\nIch hoffe für Euch, dass Ihr dem gewachsen seid, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13261] = { id = 13261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verflüchtigung", description = "Wahuu! Es funktioniert! Nicht dass ich irgendwelche Zweifel an meiner übernatürlichen Genialität gehabt hätte... Ich war nur nicht ganz sicher, was für eine Art von Explosion kommen würde... Lasst uns einfach sagen, dass ich froh bin, dass Ihr Euch nicht die Augenbrauen abgefackelt habt... So, nun muss ich dem alten Korm nur zeigen, wie man die Wyrms auftaut. Dann muss er mich befördern zum... zum... zu was-auch-immer nach Chefingenieur kommt! Hier, nehmt noch eine Portion von dem Zeug und kehrt an die Front zurück, ich werde mit Korm reden...\n\nNa? Bewegt Euch!", sourceObjective = "Chefingenieur Kupferklammer möchte, dass Ihr Kupferklammers flüchtiges Öl an der Zerbrochenen Front benutzt, um 3 Frostbrutvollstrecker anzulocken.\n\nUm das Öl benutzen zu können, müsst Ihr auf dem dortigen Schlachtfeld einen Knochenhaufen, einen zurückgelassenen Helm und eine zurückgelassene Rüstung einsammeln.", completion = "Nichtsnutz!\n\nKorm sagte bloß, er sei zu beschäftigt, und als ich ihn endlich dazu gekriegt hab', nach oben zu kommen und es sich anzusehen, hattet Ihr auch schon alles Öl aufgebraucht. Jetzt ist er verärgert und will mich bis morgen nicht einmal mehr in seiner Nähe haben...\n\nKommt dann wieder und wir versuchen es nochmal!", sourceObjectiveStatus = "unverified-source-field" }
quests[13262] = { id = 13262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt es hoch!", description = "Besser werden wir die Sache hier wohl nicht unter Kontrolle bekommen. Legen wir los, {name}.\n\nIch brauche jemanden, der die Lunten an diesen Bomben anzündet, und es sieht so aus, als wärt Ihr derjenige.", sourceObjective = "Geht zu dem nahen Saronitbombenstapel und zündet die Lunte an.", completion = "Diese Bomben sehen ziemlich durchschlagskräftig aus. Sie sollten zumindest für eine ordentliche Delle in der umgebenden Struktur sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13263] = { id = 13263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine kurze Lunte", description = "Als Ihr die Lunte entzündet, merkt Ihr, dass sie viel schneller abbrennt, als Ihr erwartet hattet.\n\nDie Bomben sind kurz vor der Explosion und Eure beste Chance zu überleben ist, Euch nach vorne fallen zu lassen und zu hoffen, dass Euch der Sturz nicht tötet.", sourceObjective = "Haltet nach Hinweisen Ausschau, wo auch immer der Sturz Euch hinführt.", completion = "Dieses pulsierende Objekt ist von einer dicken Eisschicht umgeben. Es schimmert geheimnisvoll unter Wasser.", sourceObjectiveStatus = "unverified-source-field" }
quests[13264] = { id = 13264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist monströs!", description = "Monstrositäten...\n\nSie können sehr fähige Gegner sein. Ich habe mehr als einmal gesehen, wie sie den Ausgang einer Schlacht gewendet haben. Nur wenige erkennen, dass sie auch sehr fähige Freunde sein können.\n\nSie sind keine großen Denker. Wenn Ihr die Geheimnisse ihrer Erschaffung kennt, dann könnt Ihr ihnen einige Grundbefehle erteilen, die sie nicht hinterfragen werden.\n\nZu Eurem Glück kenne ich diese Geheimnisse.\n\nDieses Set wird die Überreste der Monstrositäten, die Ihr besiegt habt, wiederbeleben. Nehmt es und lernt, es gegen die Geißel am Tor des Todes einzusetzen.", sourceObjective = "Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr das Wiederbelebungsset für Monstrositäten benutzt, um eine wiedererweckte Monstrosität zu erschaffen, mit der Ihr 15 Eisghule, 15 heimtückische Spuke und 15 auferstandene Soldaten der Allianz töten sollt.", completion = "Seht Ihr, {class}?\n\nRaffinesse kann mitunter selbst in aussichtslos scheinenden Situationen für Chancengleichheit sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13265] = { id = 13265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Plündern von Stoffen", progress = "Dem Schnitt Eurer Kleider nach zu urteilen nehme ich an, dass Ihr selbst ein Schneider seid und somit leicht erlernen könnt, was ich beizubringen habe.\n\nViele der Humanoiden des Nordens tragen Kleider, die recht schnell in Stoff umgewandelt werden können, wenn man den Dreh raus hat.\n\nGegen eine kleine Gebühr kann ich Euch beibringen, wie man Stoffe plündert. Auf diese Weise werdet Ihr von den toten humanoiden Wesen in Nordend zusätzlichen Stoff erhalten.", completion = "Ihr findet extra Stoff? Macht aus ihm etwas Wunderschönes!" }
quests[13266] = { id = 13266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Leben ohne Reue", description = "Am Tage meines Todes möchte ich sagen können, dass ich ein Leben ohne Reue geführt habe. Diejenigen, die mein Dahinscheiden betrauern, werden wissen, dass ich ein Kriegshäuptling war, der die besten Entscheidungen für sein Volk getroffen hat.\n\nDoch Varimathras' und Putress' Verrat... Alles, wofür wir gearbeitet haben, ist umsonst gewesen.\n\n<Thrall gibt einen langen Seufzer von sich.>\n\nPortale nach Unterstadt werden vorübergehend aktiv sein. Vol'jin wird auf Euch warten. Ich werde Euch schon bald dort antreffen. Gemeinsam werden wir die Sache wieder bereinigen, {name}.", sourceObjective = "Nehmt das Portal nach Unterstadt, das sich in der Feste Grommash befindet, und meldet Euch bei Vol'jin.", completion = "Lasst mich Euch auf den neuesten Stand bringen, {name}.\n\nUnterstadt ist eine Kriegszone. Putress' Apotheker und Varimathras' Dämonen haben die Kontrolle übernommen. Sie haben sich drinnen verschanzt und setzen diese verdammte Seuche gegen unsere Truppen ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13267] = { id = 13267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Unterstadt", description = "Ganz Unterstadt steht unter Varimathras' Kontrolle. Unsere Soldaten stehen bereit und warten auf den Angriffsbefehl des Kriegshäuptlings.\n\nHelft der Horde, Unterstadt zurückzuerobern, und verdient Euch einen Platz unter unseren größten Champions! Erstattet Thrall Bericht, falls Ihr den Angriff überleben solltet.\n\nMeldet Euch beim Kriegshäuptling, sobald Ihr bereit seid loszulegen.", sourceObjective = "Unterstützt Thrall und Sylvanas, Unterstadt für die Horde zurückzuerobern.\n\nMeldet Euch bei Thrall, solltet Ihr erfolgreich sein.", completion = "Die Zukunft ist unsicher. Die Tage, an denen Horde und Allianz Seite an Seite gegen einen gemeinsamen Feind kämpften, sind gezählt. Dies ist der Beginn einer neuen Schlacht, {name} - eine Schlacht, in der es keinen Gewinner geben kann.\n\nDoch wir müssen unseren Marsch auf Eiskrone weiterführen. In dieser Hinsicht bleibt uns keine andere Wahl. Unsere Erlösung liegt in Helden wie Ihr es seid, {name}. Die Zukunft der Horde - die Zukunft der Welt - liegt in Euren Händen.\n\nKehren wir nach Orgrimmar zurück. Ihr müsst umgehend wieder nach Nordend reisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13268] = { id = 13268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Plündern von Stoffen", progress = "Ihr seht wie jemand aus, der weiß, wie man mit Nadel und Faden umgeht - vielleicht kann ich Euch dann helfen.\n\nDie Humanoiden des Nordens tragen Kleider, die, wenn man weiß wie, recht schnell in Stoff umgewandelt werden können.\n\nFür ein paar Gold würde ich Euch die Kunst beibringen, wie man Stoffe plündert. Auf diese Weise werdet Ihr von den toten humanoiden Wesen in Nordend zusätzlichen Stoff erhalten.", completion = "Kommt wieder zurück, wenn Ihr über ausreichend Können verfügt. Ich kann Euch alles beibringen, was ein Schneider nur lernen kann." }
quests[13269] = { id = 13269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Plündern von Stoffen", progress = "Die Humanoiden der Nordlande tragen Kleidungsstücke, die, wenn man weiß wie, in Stoff umgewandelt werden können.\n\nFür ein paar Gold würde ich Euch die Kunst beibringen, wie man Stoffe plündert. Auf diese Weise werdet Ihr von den toten Humanoiden in Nordend zusätzlichen Froststoff erhalten.", completion = "Möget Ihr viele humanoide Wesen töten und ihren Stoff nehmen." }
quests[13270] = { id = 13270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Plündern von Stoffen", progress = "Du siehst wie jemand aus, der weiß, wie man mit Nadel und Faden umgeht, also habe ich da was für dich.\n\nDie Humanoiden vom Norden tragen Sachen, die in Stoff umgewandelt werden können, wenn man nur weiß wie.\n\nWenn du ein bisschen Geld locker machen willst, dann kann ich dir beibringen, wie man Stoffe plündert. Dadurch wirst du von den Humanoiden aus Nordend noch mehr Froststoff bekommen.", completion = "Gut, mit dir Geschäfte zu machen." }
quests[13271] = { id = 13271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Stimme im Dunklen", description = "Das Objekt ist überhaupt kein Kristall, sondern etwas Organisches, das in Eis eingeschlossen ist.\n\nAls Ihr es berührt, zuckt Eure Hand vor Schmerz zurück. Es fühlt sich an, als hättet Ihr Euch in die Hand geschnitten, aber es ist keine Wunde zu sehen.\n\nAls Ihr Eure Gedanken sammelt, hört Ihr die Stimme eines Jungen in der Nähe.\n\n\"Das hättet Ihr nicht tun sollen.\"", sourceObjective = "Untersucht die nahe Stimme in Naz'anak, den Vergessenen Tiefen.", completion = "Ich sah, wie er es weggeworfen hat, wisst Ihr? Er hat es ganz bis hier herunter geworfen.\n\nSagte, er bräuchte es nicht mehr. Sagte, es würde ihn schwach machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13272] = { id = 13272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Plündern von Stoffen", progress = "Als Schneider meine ich, dass Ihr bereit seid, das zu lernen, was ich beizubringen habe.\n\nViele der humanoiden Wesen des Nordens tragen Kleidung, die sich mit dem geeigneten Wissen schnell in Stoff umwandeln lässt.\n\nFür ein paar Goldstücke kann ich Euch beibringen, wie man Stoffe plündert, um den Humanoiden aus Nordend zusätzlichen Stoff abzugewinnen.", completion = "Ich denke, dass Ihr diese Fähigkeit äußerst wichtig finden werdet, um zu schneiderischer Größe zu gelangen!" }
quests[13273] = { id = 13273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Kern hinterher", description = "Da wir nun Norgannons Schale in Händen halten, muss nur noch die zweite Hälfte des Archivschlüssels gefunden werden. Zum Glück habe ich die Forscherliga intensiv nach Hinweisen über den Aufenthaltsort des Kerns suchen lassen.\n\nWeit südöstlich der Bibliothek des Erfinders an den Hängen nördlich von Dun Niffelem befindet sich ein Lager, das meinen Namen trägt. Dort sind diejenigen der Forscherliga stationiert, die nach der zweiten Hälfte des Schlüssels suchen. Bringt mir die Karten und Notizen, die sie angefertigt haben, und die andere Schlüsselhälfte sollte sich finden lassen.", sourceObjective = "Geht zu Branns Basislager und sucht nach Ausgrabungsleiter Khronas Notizen und Ausgrabungsleiter Sorens Karten.", progress = "Habt Ihr diese Notizen mitgebracht?", completion = "Zerstört? Was soll das heißen. das Lager wurde zerstört?\n\n<Brann ballt wütend die Faust.>\n\nDiese Eisenzwerge werden dafür bezahlen! Wir können nur noch wenig tun. Wir müssen uns darauf konzentrieren, den Schlüssel fertig zu stellen. Doch sobald ich in die Hallen von Ulduar gelange, werden die Eisenzwerge und ihre Meister für das, was sie getan haben, zur Verantwortung gezogen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13274] = { id = 13274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hüter des Kerns", description = "Die Aufzeichnungen von Ausgrabungsleiter Soren erzählen uns, dass sich Norgannons Kern in der Obhut einer Schildwache namens Athan befindet - eine von Mimirs Schöpfungen.\n\nSoren meint, dass das Gewölbe, in dem Athan residiert, heutzutage \"Lokens Handel\" genannt wird.\n\nLoken, wie? Die Irdenen haben seinen Namen erwähnt.\n\nMan sagt, dass sich das Gewölbe südwestlich des zerstörten Lagers der Forscherliga befindet und dass dessen Eingang an einem Berghang mit Aussicht auf das Uralte Wintertal zu finden ist.\n\nFindet diesen Athan und beschafft Euch den Kern. Ich wäre jedoch nicht sonderlich überrascht, wenn Ihr auch kämpfen müsstet.", sourceObjective = "Beschafft Norgannons Kern.", progress = "Hatte Ausgrabungsleiter Soren recht? Habt Ihr Norgannons Kern endlich gefunden?", completion = "Das ist es! Der Schlüssel ist beinahe in Reichweite. Jetzt müssen wir nur noch herausfinden, wie wir die Schale und den Kern zu einem einzigen Schlüssel zusammenfügen können. Sehen wir einmal nach, was Ausgrabungsleiter Soren dazu zu sagen hatte...", sourceObjectiveStatus = "unverified-source-field" }
quests[13275] = { id = 13275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit zum Verstecken", description = "Ihr hättet das nicht berühren sollen. Nun, da Ihr es getan habt, wird er kommen und nach Euch suchen.\n\nUnd er wird Euch finden. Solange Ihr Euch nicht vor ihm versteckt.\n\nBringt mir Blut von den Gesichtslosen, wenn Ihr leben wollt.", sourceObjective = "Matthias Lehner möchte, dass Ihr ihm 3 Proben Blut des Gesichtslosen bringt.", progress = "Habt Ihr das Blut?", completion = "Worauf wartet Ihr dann noch? Ihr müsst Euch damit einreiben!\n\nSchnell! Oder er wird Euch sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13276] = { id = 13276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist monströs!", description = "Ihr wisst, was zu tun ist, {class}.\n\nNehmt dieses Set und erschafft mit den Eingeweiden ihrer Monstrositäten Eure eigene Monstrosität. Lasst sie dann die feindlichen Truppen am Tor angreifen.\n\nIhr tätet gut daran, die Taktik noch zu verfeinern, bevor wir das Tor angreifen.", sourceObjective = "Koltira Todesweber auf der Orgrims Hammer möchte, dass Ihr das Monstrositätenwiedererweckungsset benutzt, um eine wiedererweckte Monstrosität zu erschaffen, mit der Ihr dann 15 Eisghule, 15 heimtückische Spuke und 15 auferstandene Soldaten der Allianz töten sollt.", completion = "Wie ich sehe, entwickelt sich Eure Fertigkeit in Bezug auf Monstrositäten gut.\n\nSeid gewissenhaft, mein Freund, und schon bald wird das Tor der Horde gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[13277] = { id = 13277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen die Riesen", description = "Obwohl es entscheidend sein wird, die Geißel am Boden zu besiegen, dürfen wir nicht das Tor selbst vernachlässigen.\n\nDie Fleischriesen auf den Bollwerken sind in der Lage, große Felsen und Eisbrocken zu schleudern und damit verheerenden Schaden unter der anstürmenden Infanterie anzurichten.\n\nStellt eine Truppe zusammen und erledigt diese Riesen. Wir müssen einfach wissen, wie es um ihre wahre Stärke bestellt ist.\n\nOh... und bringt mir ihre Wirbelsäulen. Wenn meine Erinnerung mich nicht trügt, dann gibt es da einen kleinen Trick, den ich Euch zeigen kann.", sourceObjective = "Koltira Todesweber auf der Orgrims Hammer möchte, dass Ihr ihm 5 pustelige Wirbelsäulen von den pusteligen Schrecken auf Mord'rethar bringt.", progress = "Hattet Ihr Erfolg gegen die Riesen, {race}?", completion = "Hervorragend. Diese Exemplare sehen brauchbar aus.\n\nUnd wieder ist es an der Zeit, die Stärke des Gegners gegen ihn zu verwenden...", sourceObjectiveStatus = "unverified-source-field" }
quests[13278] = { id = 13278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koprus der Entweihte", description = "Ich habe Berichte von einem mächtigen Zombie am Tor des Todes erhalten, {class}.\n\nEine potentielle Gefahr wie diese können wir nicht ignorieren. Jede Information, die Ihr von einer Auseinandersetzung mit ihm gewinnen könnt, ist besser als das, was wir bisher wissen.\n\nGeht zur westlichen Kammer des Tores und findet diese Kreatur. Kämpft gegen sie und findet eine Schwäche, die wir ausnutzen können.", sourceObjective = "Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr Koprus den Entweihten bei Mord'rethar tötet.", completion = "Gut gemacht, {class}.\n\nMit einigen Nachforschungen können wir vielleicht herausfinden, wie sie eine derartige Kreatur erschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13279] = { id = 13279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundkenntnisse der Chemie", description = "<Koltira nimmt die pusteligen Wirbelsäulen und wringt ihre Flüssigkeit in ein Fläschchen.> Eine wenig bekannte Eigenart der Fleischriesen...\n\nIhre Rückenmarksflüssigkeit interagiert auf höchst interessante Art und Weise mit der Seuche, indem sie sie in ätzende Säure verwandelt.\n\nSchüttet man diese von den höher gelegenen Bollwerken, mag das nicht besonders erfreulich für die Truppen unten sein, aber zumindest werden die Opfer nicht wiederauferstehen und sich dem Gegner anschließen.\n\nSchüttet den Inhalt dieses Fläschchens in einen der Seuchenkessel in der westlichen Kammer des Tors des Todes.", sourceObjective = "Koltira Todesweber an Bord der Orgims Hammer möchte, dass Ihr pustelige Rückenmarksflüssigkeit in einen Seuchenkessel in Mord'rethar gießt.", completion = "Gute Arbeit, {class}.\n\nWenn unsere Armeen eintreffen, um gegen die Zitadelle zu marschieren, haben wir einen fundierten Plan, um das Tor des Todes einzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13280] = { id = 13280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König der Berge", description = "Ihr müsst meinen Hüpfboter nur so schnell wie möglich von Ymirheim zum Gipfel dieses Berges dort im Nordwesten bringen, {name}!\n\nDieser heimtückische, nichtsnutzige Bumm Donnerbombe arbeitet an seinem eigenen Bot und ich befürchte, dass er beinahe fertig ist. Wir werden ein Rennen bestimmen lassen, wer König der Berge wird!\n\nSteckt unsere Schlachtstandarte in den Knochenhaufen, sobald Ihr oben angekommen seid, und zeigt jedem, dass niemand besser ist, als die Allianz - und meine Ingenieursfertigkeiten!", sourceObjective = "Fetzi Gangzwinger in Ymirheim möchte, dass Ihr ihren Hüpfboter benutzt, um die Schlachtstandarte der Allianz in den Schädelhaufen auf dem Gipfel des Berges zu stecken.", progress = "Wartet mal eine Sekunde... Ihr habt unsere Schlachtstandarte noch nicht aufgestellt?!\n\nWas hält Euch auf?", completion = "IHR HABT ES GESCHAFFT! IHR HABT ES GESCHAFFT!\n\n<Fetzi springt in die Luft und umarmt Euch innig.>\n\n\n\nAch, Ihr seid einfach der Beste, den es gibt!\n\nDenkt Ihr, dass Ihr morgen wiederkommen könntet?", sourceObjectiveStatus = "unverified-source-field" }
quests[13281] = { id = 13281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seuche neutralisieren", description = "Ihr braucht nicht länger meine Hilfe, um die Seuchenkessel des Feindes zu neutralisieren, {race}.\n\nBringt die Fleischriesen am Tor des Todes zur Strecke und macht mithilfe ihrer Rückenmarksflüssigkeit den Inhalt der Kessel unwirksam.\n\nIhr führt einen Schlag gegen das zentrale strategische Mittel des Feindes durch. Diese Mission ist wichtig - für unsere Sache unerlässlich und sollte ausgeführt werden, wann auch immer sich die Gelegenheit bietet.\n\nVergesst nicht: Die Riesen und Seuchenkessel befinden sich bei Mord'rethar.", sourceObjective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr pustelige Rückenmarksflüssigkeit in einen Kessel bei Mord'rethar schüttet.\n\npustelige Rückenmarksflüssigkeit kann dadurch gewonnen werden, indem man das Fleischriesenrückgrat eines pusteligen Schreckens benutzt.", completion = "Ein Seuchenkessel weniger, um den wir uns kümmern müssen, wenn die Schlacht beginnt.\n\nEuer Kommandant wird äußerst zufrieden sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13282] = { id = 13282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr an die Oberfläche", description = "Ihr solltet nun gehen. Hinter mir findet Ihr ein Portal, das Euch an die Oberfläche bringen wird.\n\nWir werden uns wiedersehen. Er wird nach Euch suchen.\n\nEs ist nur eine Frage der Zeit, bis er Euch findet.", sourceObjective = "Kehrt zu Koltira Todesweber an Bord der Orgrims Hammer zurück.", completion = "{name}! Wir dachten, Ihr seid tot!\n\nWir haben ein paar Männer bei der Explosion verloren... doch wir haben den Dienern der Geißel auf jeden Fall gut Schaden zugefügt. Sie sind auf schleunigstem Rückzug zur Zitadelle und hinterlassen große Lücken in ihrer Verteidigung. Es ist Zeit vorzurücken.", sourceObjectiveStatus = "unverified-source-field" }
quests[13283] = { id = 13283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König der Berge", description = "Also, {name}, Ihr müsst meinen Hüpfboter zum Gipfel dieses Berges dort im Südosten bringen, wie gestern!\n\nDiese weibische, selbstgerechte Fetzi Gangzwinger meint, dass ihr Hüpfboter besser sei als meiner. Ha! Wir werden ein Rennen bestimmen lassen, wer König der Berge wird!\n\nSteckt unsere Schlachtstandarte in den Knochenhaufen, sobald Ihr oben angekommen seid, und zeigt jedem, dass die Horde und meine verrückten Ingenieursfertigkeiten die Besten sind!", sourceObjective = "Bumm Donnerbombe in Ymirheim möchte, dass Ihr seinen Hüpfboter benutzt, um die Schlachtstandarte der Horde in den Schädelhaufen auf dem Gipfel des Berges zu stecken.", progress = "Wartet mal eine Sekunde... Ihr habt unsere Schlachtstandarte noch nicht aufgestellt?!\n\nWie kommt das?", completion = "Ah, {race}, ich wusste, dass Ihr der Richtige für den Job sein würdet!\n\n\n\nIch muss zugeben, {class}, dass Euch das im Moment auf meiner Liste ganz weit oben stehen lässt!\n\nWas sagt Ihr dazu, diese Vorstellung morgen nochmal zu wiederholen? Es würde sich für Euch lohnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13284] = { id = 13284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bodenangriff", description = "Grüße, {class}.\n\nUnsere Truppen versuchen schon seit einer ganzen Weile Ymirheim zu erstürmen, doch diese Vrykul sind um einiges grausamer als alle anderen, denen wir bisher begegnet sind. Wenn wir versuchen, über den Pass zu kommen, laufen wir ständig in einen ihrer Hinterhalte, und wir haben viele Männer verloren.\n\nWir würden Euch gerne für Eure Mühen belohnen, falls Ihr dem Kampf beitreten und helfen solltet, meine Einheit sicher nach Ymirheim zu bringen. Sobald wir vor den Toren stehen, werden wir uns verschanzen und darauf warten, dass uns die Verstärkungstruppen einholen.", sourceObjective = "Eskortiert die Truppen der Himmelsbrecher zu den Toren von Ymirheim. Kehrt zu Feldkommandant Koup am Rand des Gletschers im Norden von Ymirheim zurück, nachdem Eure Aufgabe abgeschlossen ist, und holt Eure Belohnung ab.", completion = "Ihr habt meinen Dank.\n\nDiese Operation war gnadenlos, doch uns blieb keine bessere Möglichkeit - unseren Lufteinheiten haben sie genauso schonungslos zugesetzt. Wir müssen diese Vrykul loswerden, wenn wir auch nur den Hauch einer Chance haben wollen, in Eiskrone weiter vorzustoßen.\n\nWir werden später höchstwahrscheinlich noch mehr Hilfe benötigen. Bitte schließt euch uns wieder an, sollte sich die Möglichkeit ergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13285] = { id = 13285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schlüsselstein schmieden", description = "Aha! Da ist er ja: der Tempel des Erfindungsreichtums, Sitz von Hüter Mimir höchstpersönlich! Natürlich, dort würde man hingehen, um die zwei Teile des Schlüssels zusammenzufügen.\n\nDen Notizen des Ausgrabungsleiters zufolge ist der Tempel des Erfindungsreichtums einer der höchsten Punkte auf der westlichen Seite der Terrasse der Schöpfer. Das bedeutet, dass sich der Ort ungefähr östlich der Absturzstelle Grom'ash befinden sollte.\n\nIch treffe Euch im Tempel und wir werden die zwei Teile zusammenfügen.", sourceObjective = "Brann Bronzebart möchte, dass Ihr ihn im Tempel des Erfindungsreichtums trefft und ihm dabei helft, Norgannons Schale und Norgannons Kern zusammenzufügen. Meldet Euch bei Boktar Blutfurie bei der Absturzstelle Grom'ash, sobald dies getan ist.", completion = "<Boktar nickt zustimmend, als Ihr ihm davon erzählt, wie Ihr Brann dabei geholfen habt, die Teile zu beschaffen und sie zusammenzufügen.>\n\nBrann könnte genau der Verbündete sein, den wir brauchen, um herauszufinden, was wirklich in Ulduar vor sich geht. Es war gut von Euch, ihm zu helfen. Gegen diesen Loken und seine untergebenen Eisenzwerge benötigen wir jede Hilfe, die wir bekommen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13286] = { id = 13286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "... Jede Hilfe, die wir kriegen können", description = "Schlimme Zeiten, {class}...\n\nSo ungern ich das auch tue, ich bin mittlerweile bereit, Hilfe von wirklich jedem anzunehmen - selbst von unserem Todesritter.\n\nGeht zu Thassarian und seht, ob er uns dabei helfen kann, Taktiken gegen die Geißel zu entwickeln, die uns den Sieg bringen können, sobald wir einen weiteren Angriff beginnen können.\n\nWir sind so weit gekommen... wir dürfen jetzt nicht scheitern!", sourceObjective = "Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher möchte, dass Ihr mit Thassarian sprecht.", completion = "Es war weise von Stabshauptmann Bartlett, Euch zu mir zu schicken.\n\nWährend er sich um euren Konflikt mit der Horde sorgt, muss sich jemand voll und ganz auf die wahre Mission hier konzentrieren - den Marsch auf die Eiskronenzitadelle.\n\nWer könnte besser Eure Bemühungen koordinieren, als ein ehemaliger Diener des Lichkönigs?", sourceObjectiveStatus = "unverified-source-field" }
quests[13287] = { id = 13287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stechen und Stoßen", description = "Wie jemand mit Eurer Erfahrung sicher weiß, gibt es keinen besseren Weg, etwas über seinen Gegner herauszufinden, als sich ihm im Kampf gegenüberzustellen.\n\nObschon Ihr sicher nach dem Ruhm giert, die Eiskronenzitadelle einzunehmen, kann dies jedoch nicht passieren, bevor nicht jedes der Tore des Lichkönigs erobert ist. Vorerst müsst Ihr Eure Anstrengungen auf das erste der Tore konzentrieren...\n\nKehrt zur Zerbrochenen Front zurück. Verwickelt den Gegner in eine Schlacht. Sucht nach einer Schwäche, die wir ausnutzen könnten, und kehrt dann mit einem detaillierten Bericht zu mir zurück.", sourceObjective = "Thassarian auf der Himmelsbrecher möchte, dass Ihr 5 bullige Monstrositäten, 5 bösartige Totenbeschwörer und 5 Schattenadepten bei der Zerbrochenen Front tötet.", completion = "Ehrlich, {class}?\n\nNichts besonderes zu berichten?\n\n\n\nIch erlaube mir, das Gegenteil zu behaupten...", sourceObjectiveStatus = "unverified-source-field" }
quests[13288] = { id = 13288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist monströs!", description = "Monstrositäten...\n\nSie können sehr fähige Gegner sein. Ich habe mehr als einmal gesehen, wie sie den Ausgang einer Schlacht gewendet haben. Nur wenige erkennen, dass sie auch sehr fähige Freunde sein können.\n\nSie sind keine großen Denker. Wenn Ihr die Geheimnisse ihrer Erschaffung kennt, dann könnt Ihr ihnen einige Grundbefehle erteilen, die sie nicht hinterfragen werden.\n\nZu Eurem Glück kenne ich diese Geheimnisse.\n\nDieses Set wird die Überreste der Monstrositäten, die Ihr besiegt habt, wiederbeleben. Nehmt es und lernt, es gegen die Geißel am Tor des Todes einzusetzen.", sourceObjective = "Thassarian auf der Himmelsbrecher möchte, dass Ihr das Wiederbelebungsset für Monstrositäten benutzt, um eine wiedererweckte Monstrosität zu erschaffen, mit der Ihr 15 Eisghule, 15 heimtückische Spuke und 15 auferstandene Soldaten der Allianz töten sollt.", completion = "Seht Ihr, {class}?\n\nRaffinesse kann mitunter selbst in aussichtslos scheinenden Situationen für Chancengleichheit sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13289] = { id = 13289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist monströs!", description = "Ihr wisst, was Ihr zu tun habt, {class}.\n\nNehmt dieses Set hier und benutzt die Eingeweide ihrer Monstrositäten, um eine eigene zu erschaffen, dann befehlt ihr, die Streitkräfte des Gegners am Tor anzugreifen.\n\nIhr tätet gut daran, vor unserem nächsten Angriff auf das Tor diese Taktik zu verfeinern.", sourceObjective = "Thassarian auf der Himmelsbrecher möchte, dass Ihr das Wiederbelebungsset für Monstrositäten benutzt, um eine wiedererweckte Monstrosität zu erschaffen, mit der Ihr 15 Eisghule, 15 heimtückische Spuke und 15 auferstandene Soldaten der Allianz töten sollt.", completion = "Ich sehe, dass sich Eure Fähigkeiten mit den Monstrositäten beachtlich entwickelt haben.\n\nBleibt eifrig bei der Sache, Freund, und schon bald wird das Tor in der Hand der Allianz sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13290] = { id = 13290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bitte recht aufmerksam", description = "Chefingenieur Bolzenschlüssel hat sich als unabdingbar auf der Sturmbrecher erwiesen. Ohne seine Genialität lägen wir mittlerweile schon mehrfach über den halben Gletscher verstreut.\n\nDas Problem ist nur, dass er jede einzelne popelige Erfindung oder Entdeckung gleich diskutieren will - obwohl ich die Hälfte sowieso nicht verstehe.\n\nMein Augenmerk muss jetzt aber ausschließlich auf unseren Feinden liegen. Ich kann mir keine Ablenkungen erlauben.\n\nBitte stattet ihm einen Besuch an meiner Stelle ab, {name}. Und assistiert ihm, wenn Ihr könnt. Ihr findet ihn unter Deck.", sourceObjective = "Stabshauptmann Bartlett möchte, dass Ihr mit Chefingenieur Bolzenschlüssel in der Himmelsbrecher redet.", completion = "Cappy hat Euch an seiner Stelle geschickt, oder?\n\nNun gut, {class}. Krempelt Eure Ärmel hoch... es ist Zeit, an die Arbeit zu gehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13291] = { id = 13291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geliehene Technologie", description = "Ich kapier's ja, ich kapier's ja. Cappy ist zu beschäftigt, um es sich selber anzusehen. Selbst Schuld!\n\nSeht Ihr, ich habe es geschafft, eine gewisse Lieferung Lösungen vom Feind zu 'leihen'. Und so sehr ich es auch hasse, mit minderwertiger Goblintechnologie zu hantieren, so bin ich doch versucht, hier mal eine Ausnahme zu machen.\n\nNehmt diese Probe. Ihr müsst für mich einige Feldversuche durchführen, um ihre Nützlichkeit unter Beweis zu stellen, während ich versuche, ein wenig umgekehrte Ingenieurskunst zu betreiben und den Erschaffungsprozess zu duplizieren.\n\nGeht an die Front und sammelt das Material, um eine Attrappe zu bauen, dann benutzt das Öl.", sourceObjective = "Chefingenieur Bolzenschlüssel an Bord der Himmelsbrecher will, dass Ihr die geschmuggelte Lösung an der Zerbrochenen Front benutzt.\n\nUm die Lösung zu benutzen, braucht Ihr einen zurückgelassenen Helm, eine zurückgelassene Rüstung und einen Knochenhaufen, die allesamt an der Zerbrochenen Front gefunden werden müssen.", completion = "Gute Neuigkeiten!\n\nIch habe es geschafft, die Lösung zu reproduzieren - was natürlich kaum eine Errungenschaft darstellt.\n\nIch bezweifle, dass diese Neanderthaler von Goblins jemals etwas gebastelt bekommen, das wir Gnome nicht im Schlaf nachbauen könnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13292] = { id = 13292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lösungslösung", description = "Oh, ja, ja. Wieder zurück, hmm? Man kann nie genug Training haben, was?\n\nUnd hier ist sie, die Lösung für das ärgerliche Frostwyrmproblem.\n\nVerringert ihre Anzahl, {race}. Je mehr Ihr jetzt ausschaltet, desto weniger sitzen uns im Nacken, wenn wir uns aufmachen, die Zitadelle anzugreifen.\n\nViel Glück Euch. Und bringt doch bitte zurück, was Ihr nicht braucht.", sourceObjective = "Chefingenieur Bolzenschlüssel an Bord der Himmelsbrecher möchte, dass Ihr die geschmuggelte Lösung an der Zerbrochenen Front einsetzt.\n\nUm die Lösung benutzen zu können, benötigt Ihr einen zurückgelassenen Helm, zurückgelassene Rüstung und einen Knochenhaufen, die alle an der Zerbrochenen Front zu finden sind.", completion = "Großartig! Wirklich großartig. Ihr werdet noch zum Wyrmtöterprofi!\n\nKommt wieder, wenn Ihr bereit seid, Ihre Reihen weiter auszudünnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13293] = { id = 13293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Ymirheim!", description = "Ihr müsst hinunter nach Ymirheim, der großen Stadt der Frostvrykul im Zentrum von Eiskrone.\n\nUnser Kumpel, Bumm Donnerbombe, ist schon da, im Westen der Stadt und repräsentiert die Kriegshymnenoffensive in einem Wettkampf gegen die Allianz. Es steht sein Hüpfboter gegen ihren in einem Wettkampf um den Titel König der Berge!\n\nLasst uns nicht im Stich, {name}. Der Stolz der goblinischen Ingenieurskunst steht auf dem Spiel! Außerdem zählen alle Jungs hier auf dem Schiff auf Euch.\n\nDas, und dann haben wir noch Geld darauf gesetzt, dass Ihr diesen Feiglingen ordentlich in den Hintern tretet!", sourceObjective = "Redet mit Bumm Donnerbombe in Ymirheim.", completion = "Oh Mann, bin ich froh, Euch zu sehen. Hat Euch der Häuptling von der Hammer hergeschickt?", sourceObjectiveStatus = "unverified-source-field" }
quests[13294] = { id = 13294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen die Riesen", description = "Obwohl es entscheidend sein wird, die Geißel am Boden zu besiegen, dürfen wir nicht das Tor selbst vernachlässigen.\n\nDie Fleischriesen auf den Bollwerken sind in der Lage, große Felsen und Eisbrocken zu schleudern und damit verheerenden Schaden unter der anstürmenden Infanterie anzurichten.\n\nStellt eine Truppe zusammen und erledigt diese Riesen. Wir müssen einfach wissen, wie es um ihre wahre Stärke bestellt ist.\n\nOh... und bringt mir ihre Wirbelsäulen. Wenn meine Erinnerung mich nicht trügt, dann gibt es da einen kleinen Trick, den ich Euch zeigen kann.", sourceObjective = "Thassarian auf der Himmelsbrecher möchte, dass Ihr ihm 5 pustelige Wirbelsäulen von den pusteligen Spuken auf Mord'rethar bringt.", progress = "Hattet Ihr Erfolg gegen die Riesen, {race}?", completion = "Hervorragend. Diese Exemplare sehen brauchbar aus.\n\nUnd wieder ist es an der Zeit, die Stärke des Gegners gegen ihn zu verwenden...", sourceObjectiveStatus = "unverified-source-field" }
quests[13295] = { id = 13295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundkenntnisse der Chemie", description = "<Thassarian nimmt die pusteligen Wirbelsäulen und wringt ihre Flüssigkeit in ein Fläschchen.> Eine wenig bekannte Eigenart der Fleischriesen...\n\nIhre Rückenmarksflüssigkeit interagiert auf höchst interessante Art und Weise mit der Seuche, indem sie sie in ätzende Säure verwandelt.\n\nSchüttet man diese von den höher gelegenen Bollwerken, mag das nicht besonders erfreulich für die Truppen unten sein, aber zumindest werden die Opfer nicht wiederauferstehen und sich dem Gegner anschließen.\n\nSchüttet den Inhalt dieses Fläschchens in einen der Seuchenkessel in der westlichen Kammer des Tors des Todes.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr pustelige Rückenmarksflüssigkeit in einen Seuchenkessel in Mord'rethar gießt.", completion = "Gute Arbeit, {class}.\n\nWenn unsere Armeen eintreffen, um gegen die Zitadelle zu marschieren, haben wir einen fundierten Plan, um das Tor des Todes einzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13296] = { id = 13296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Ymirheim!", description = "Ihr müsst runter nach Ymirheim, der großen Frostvrykulstadt im Zentrum von Eiskrone.\n\nFetzi Gangzwinger ist schon da, im Süden der Stadt, und repräsentiert die Expedition 'Valianz' in einem Wettkampf gegen die Mistkerle der Horde. Es steht Fetzis Hüpfboter gegen ihren in einem Wettkampf um den Titel des Königs der Berge!\n\nLasst uns nicht im Stich, {name}. Der Stolz der gnomischen Ingenieurskunst steht auf dem Spiel! Außerdem zählen alle Jungs hier in der Feste auf Euch.\n\nDas, und dann haben wir noch Geld darauf gesetzt, dass Ihr diesen Idioten ordentlich in den Hintern tretet!", sourceObjective = "Sprecht mit Fetzi Gangzwinger in Ymirheim.", completion = "Hat Euch der Boss von der Himmelsbrecher hier runter geschickt? Ist das nicht süß?!", sourceObjectiveStatus = "unverified-source-field" }
quests[13297] = { id = 13297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seuche neutralisieren", description = "Ihr braucht nicht länger meine Hilfe, um die Seuchenkessel des Feindes zu neutralisieren, {race}.\n\nBringt die Fleischriesen am Tor des Todes zur Strecke und macht mithilfe ihrer Rückenmarksflüssigkeit den Inhalt der Kessel unwirksam.\n\nIhr führt einen Schlag gegen das zentrale strategische Mittel des Feindes durch. Diese Mission ist wichtig - für unsere Sache unerlässlich und sollte ausgeführt werden, wann auch immer sich die Gelegenheit bietet.\n\nVergesst nicht: Die Riesen und Seuchenkessel befinden sich bei Mord'rethar.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr pustelige Rückenmarksflüssigkeit in einen Kessel bei Mord'rethar schüttet.\n\npustelige Rückenmarksflüssigkeit kann dadurch gewonnen werden, indem man das Fleischriesenrückgrat eines pusteligen Schreckens benutzt.", completion = "Ein Seuchenkessel weniger, um den wir uns kümmern müssen, wenn die Schlacht beginnt.\n\nEuer Hauptmann wird äußerst zufrieden sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13298] = { id = 13298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koprus der Entweihte", description = "Ich habe Berichte von einem mächtigen Zombie am Tor des Todes erhalten, {class}.\n\nEine potentielle Gefahr wie diese können wir nicht ignorieren. Jede Information, die Ihr von einer Auseinandersetzung mit ihm gewinnen könnt, ist besser als das, was wir bisher wissen.\n\nGeht zur westlichen Kammer des Tores und findet diese Kreatur. Kämpft gegen sie und findet eine Schwäche, die wir ausnutzen können.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr Koprus den Entweihten in Mord'rethar tötet.", completion = "Gut gemacht, {class}.\n\nMit einigen Nachforschungen können wir vielleicht herausfinden, wie sie eine derartige Kreatur erschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13299] = { id = 13299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ZZOLDWisp Cloak" }
quests[13300] = { id = 13300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Saronit abhängig", description = "Unsere Leute werden gefangen genommen und als Sklaven in den Saronitminen eingesetzt, der Vrykulfeste in der Mitte von Eiskrone. Der Lichkönig lässt sie Tag und Nacht das unheilige Erz schürfen.\n\nIch habe Hochlord Fordring geschworen, dass wir die armen Kerle da rausholen werden, und genau das werden wir tun.\n\nUnglücklicherweise wurde mir der Befehl erteilt, auf diesem Schiff zu bleiben und der Expedition 'Valianz' als Botschafter zu dienen. Würdet Ihr sie bitte an meiner Statt retten, {name}?", sourceObjective = "Absalan der Fromme an Bord der Himmelsbrecher möchte, dass Ihr 10 Saronitminensklaven rettet.", completion = "Sie werden wahnsinnig gemacht? Stimmen in ihren Köpfen?\n\nStimmen in Eurem Kopf?!\n\nIch möchte, dass Ihr Eure Gedanken von dem Unheil befreit, das diesen Ort ergriffen hat, {class}.\n\nWir werden versuchen morgen den Rest von ihnen da rauszubekommen, wenn Ihr eine Chance hattet, Euch auszuruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13301] = { id = 13301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bodenangriff", description = "Grüße, {class}.\n\nUnsere Truppen versuchen schon seit einer ganzen Weile Ymirheim zu erstürmen, doch diese Vrykul sind um einiges grausamer als alle anderen, denen wir bisher begegnet sind. Wenn wir versuchen, über den Pass zu kommen, laufen wir ständig in einen ihrer Hinterhalte, und wir haben viele Männer verloren.\n\nWir würden Euch gerne für Eure Mühen belohnen, falls Ihr dem Kampf beitreten und helfen solltet, meine Einheit sicher nach Ymirheim zu bringen. Sobald wir vor den Toren stehen, werden wir uns verschanzen und darauf warten, dass uns die Verstärkungstruppen einholen.", sourceObjective = "Eskortiert die Truppen der Kor'kron zu den Toren von Ymirheim. Kehrt zu Feldkommandant Xutjja an der Kante des Gletschers im Norden von Ymirheim zurück, nachdem Eure Aufgabe abgeschlossen ist, und holt Eure Belohnung ab.", completion = "Ihr habt meinen Dank.\n\nDiese Operation war gnadenlos, doch uns blieb keine bessere Möglichkeit - unseren Lufteinheiten haben sie genauso schonungslos zugesetzt. Wir müssen diese Vrykul loswerden, wenn wir auch nur den Hauch einer Chance haben wollen, in Eiskrone weiter vorzustoßen.\n\nWir werden später höchstwahrscheinlich noch mehr Hilfe benötigen. Bitte schließt euch uns wieder an, sollte sich die Möglichkeit ergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13302] = { id = 13302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Saronit abhängig", description = "Unsere Leute werden gefangen genommen und als Sklaven in den Saronitminen eingesetzt, der Vrykulfeste in der Mitte von Eiskrone. Der Lichkönig lässt sie Tag und Nacht das unheilige Erz schürfen.\n\nIch habe Hochlord Fordring geschworen, dass wir die armen Kerle da rausholen werden, und genau das werden wir tun.\n\nUnglücklicherweise wurde mir der Befehl erteilt, auf diesem Schiff zu bleiben und der Kriegshymnenoffensive als Botschafter zu dienen. Würdet Ihr sie bitte an meiner Statt retten, {name}?", sourceObjective = "Bruder Keltan an Bord der Orgrims Hammer möchte, dass Ihr 10 Saronitminensklaven rettet.", completion = "Sie werden wahnsinnig gemacht? Stimmen in ihren Köpfen?\n\nStimmen in Eurem Kopf?!\n\nIch möchte, dass Ihr Eure Gedanken von dem Unheil befreit, das diesen Ort ergriffen hat, {class}.\n\nWir werden versuchen morgen den Rest von ihnen da rauszubekommen, wenn Ihr eine Chance hattet, Euch auszuruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13304] = { id = 13304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldreparaturen", description = "Die Geißel erholt sich noch immer von unserem Angriff, {name}. Jetzt ist die Zeit, die Gunst der Stunde zu nutzen und zuzuschlagen.\n\nDas strategisch wichtige Tal unter uns ist weit offen. Wir haben in der südöstlichen Ecke des Tals der Verlorenen Hoffnung ein zerlegtes Verwüsterfahrzeug entdeckt, das sich, so glauben wir, noch in einem funktionsfähigen Zustand befindet.\n\nFalls Ihr die restlichen Teile von den Aasfressern der Geißel beschaffen könntet, solltet Ihr es wieder zum Laufen bringen können. Ein einziger funktionierender Verwüster kann unter den Bodeneinheiten des Feindes verheerenden Schaden anrichten.", sourceObjective = "Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr 5 Verwüsterersatzteile von den aasfressenden Spuken im Tal der Verlorenen Hoffnung beschafft und sie zum defekten Verwüster bringt.", progress = "Der Verwüster wurde stark beschädigt.", completion = "Der Verwüster hat schon bessere Tage gesehen, aber die Struktur hat keinen dauerhaften Schaden genommen. Die Ersatzteile, die Ihr gebracht habt, sollten ausreichen, um ihn zumindest vorübergehend wieder ans Laufen zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13305] = { id = 13305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tut Euer Schlechtestes", description = "Ihr werdet diese Maschine gegen die Geißel einsetzen? Auf diese Weise werdet Ihr nicht gegen sie gewinnen können.\n\nIhr könnt Hunderte... sogar Tausende von ihnen zerstören, doch gewinnen werdet Ihr nicht - nicht hier draußen.\n\nTrefft mich im Norden, wenn Ihr genug mit Eurer Maschine gespielt habt. Dort gibt es ein altes Militärlager. Was ich Euch zeigen werde, wird Euch einen kleinen Einblick darüber gewähren, wem wir uns hier gegenübersehen.", sourceObjective = "Zerstört mithilfe des Runderneuerten Verwüsters 150 verrottete Ghule, 20 Frostschädelmagier und 2 Knochenriesen im Tal der Verlorenen Hoffnung. Sprecht mit Matthias Lehner im Vorhutslager der Ersten Legion, wenn Ihr die Aufgabe abgeschlossen habt.", completion = "Seht Ihr? Ihr habt Euren gerechten Anteil zwar getötet, doch für jeden Einzelnen, den Ihr vernichtet habt, kam ein weiterer aus der Erde, um dessen Platz einzunehmen.\n\nIhr wisst nicht, wem Ihr hier gegenübersteht, {name}. Lasst es mich Euch zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13306] = { id = 13306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Errichtet die Barrikaden", description = "Sobald unsere Truppen sich hinter Aldur'thar befinden, werden sie verwundbar durch Attacken vom Eisenwallbollwerk oder dem breiten Gletscher darunter sein.\n\nWir haben weder die Zeit noch das Material, um Befestigungen zu bauen, aber wir können ein paar Barrikaden errichten, um unsere Männer vor Feuer zu schützen und Angriffe der Geißel abprallen zu lassen.\n\nNehmt diesen Barrikadenbausatz mit zum Tal der Gefallenen Helden. Findet die Markierungen, die ich dort gesetzt habe und benutzt den Bausatz, um dort Eure Barrikaden zu errichten.", sourceObjective = "Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr 8 Barrikaden mithilfe Eures Barrikadenbausatzes errichtet.", completion = "<Koltira nickt kurz.>\n\nGut. Sie bieten nicht gerade viel Schutz, aber immer noch besser als nichts. Dieses Tor ist noch immer der perfekte Engpass, wenn die Geißelanführer wissen, was sie tun. Wir müssen so viel von dem umliegenden Gebiet wie möglich einnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13307] = { id = 13307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutbespritzte Banner", description = "Im Tal der Gefallenen Helden und am Eiskronengletscher, im Westen Aldur'thars, versucht die Geißel, die Gefallenen gegen uns zu verwenden. Die Kommandanten der Geißel haben die Toten aus dem Tal wiedererweckt und sie mit furchterregender Stärke und Leidenschaft erfüllt. Die Banner, die die Geißelanführer in der Gletschergegend bei sich tragen, sind die Quelle dieser Mächte. Tötet die Bannerträger und Ihr werdet die konvertierten Helden, die sie führen, schwächen.\n\nEs obliegt Euch, uns von diesem Hindernis zu befreien und den Widerstand auszudünnen, bevor die Hauptstreitmacht vorrücken kann.", sourceObjective = "Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr 5 Bannerträger der Geißel, 5 Konvertierer der Geißel und 20 konvertierte Helden tötet.", completion = "Ihr habt die Bannerträger der Geißel und ihre Lakaien entfernt? Gut. Unsere Vorbereitungen müssen weitergehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13308] = { id = 13308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geistiger Zwang", description = "<Die Kreatur spricht direkt über Euren Geist mit Euch. Ihre Gedanken sind schmerzhaft und seltsam.>\n\n{race}, ich brauche Eure Hilfe. Ich bin genau so wie Eure versklavten Freunde ein Opfer der dem Lichkönig dienenden Ymirjar und ihrer Habsucht. Sie nahmen mich gefangen, als ich die Tiefen verließ, um die Geräusche aus dieser Höhle zu untersuchen, und legten mich in Ketten.\n\nWürdet Ihr mir bitte helfen? Der Vorarbeiter dieser Minen trägt den Schlüssel zu meinen Ketten bei sich. Tötet ihn!\n\n<Ihr könnt ein drängendes Gefühl in Eurem Geist spüren, als würde die Kreatur versuchen, Euch zu zwingen.>", sourceObjective = "Dunkelsprecher R'khem in den Saronitminen möchte, dass Ihr den Schlüssel des Großknechts beschafft, um so seine Ketten zu öffnen.", progress = "Ihr werdet für den Dienst, den Ihr mir erwiesen habt, reich belohnt werden.\n\n<Der Dunkelsprecher lässt besänftigende Gefühle in Eurem Geist entstehen.>\n\nIhr werdet es nicht bereuen, mich zu entfesseln.", completion = "<Als Ihr auf die Kreatur zugeht, wird Euer Geist von einer weiteren Welle der Euphorie, vermischt mit ein wenig Schmerz, überwältigt.>\n\nGut... gut! Nur damit Ihr wisst, dass ich gerecht bin, werde ich Euch zuerst Eure versprochene Belohnung geben.\n\nUnd dann werdet Ihr mir freiwillig den Schlüssel geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13309] = { id = 13309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftangriff", description = "Ich habe ein paar geeignete Jungs, die bereit sind, in Ymirheim abgeworfen zu werden. Ihr könntet mir helfen, indem Ihr sie sicher dorthin bringt.\n\nDort haben die Vrykul so etwas wie automatische Speerkanonen aufgebaut, um unsere Transporter auszuschalten. Wir haben unsere Ingenieure einen Geschützturm bauen lassen, mit dem Rauchgranaten abgeschossen werden können, um diesen Speerkanonen etwas entgegenzusetzen. Schießt einfach in die Nähe der Kanonen. Das sollte ihre Sicht blockieren und sie außer Kraft setzen.\n\nSetzt Euch an einen der Türme und sorgt dafür, dass alle meine Jungs in einem Stück zu ihrem Abwurfgebiet gelangen.", sourceObjective = "Feldkommandant Koup an der Kante des Gletschers im Osten von Ymirheim hat Euch befohlen, den Geschützturm der Himmelsbrecher zu benutzen, um den Truppentransporter der Himmelsbrecher lange genug in der Luft zu halten, bis alle abgeworfen wurden.", completion = "Ausgezeichnete Arbeit, Soldat. Wir könnten hier noch mehr so fähige Leute wie Euch gebrauchen. Schaut doch einen anderen Tag noch mal vorbei, wenn die Operation noch im Gange ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[13310] = { id = 13310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftangriff", description = "Nun gut, Grünschnabel, ich hab' etwas für dich, damit du nicht völlig nutzlos bist.\n\nEine Einheit von hochtrainierten Spitzeln ist bereit für ihren Abwurf in Ymirheim. Die Vrykul dort haben automatische Speerkanonen aufgestellt, die unsere Transporter in Stücke geschossen haben, also haben wir unsere Ingenieure einen Geschützturm auf der Orgrims Hammer bauen lassen, mit dem Rauchgranaten abgeschossen werden können.\n\nIhr seid der Schütze. Feuert auf ihre Speerkanonen, um ihnen die Sicht zu nehmen und sie außer Kraft zu setzen. Sorgt dafür, dass alle meine Männer abgeworfen werden und der Transporter ganz bleibt.", sourceObjective = "Bodentruppenkommandant Xutjja an der Kante des Gletschers im Norden von Ymirheim hat Euch befohlen, den Geschützturm der Kor'kron zu benutzen, um den Truppentransporter der Kor'kron lange genug in der Luft zu halten, bis alle abgeworfen wurden.", progress = "Job erledigt?", completion = "Also nur zum Teil unnütz. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13311] = { id = 13311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonenkartenset", description = "Jetzt, da Ihr alle Dämonenkarten in einem Set gesammelt habt, erscheint eine weitere Karte. Sie zeigt einen Wahrsager, der Euch immer anzustarren scheint, egal wie Ihr die Karte haltet.\n\nIhr glaubt, dass man mithilfe der Karte womöglich mit irgendwem oder irgendetwas kommunizieren könnte.", sourceObjective = "Beschwört mithilfe des Dämonenkartensets einen Wahrsager des Dunkelmond-Jahrmarkts und gebt ihm das Set.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Set der Dämonenkarten zusammen zu bekommen! Glückwunsch!", completion = "Der Dunkelmond-Jahrmarkt hegt großes Interesse an den Tarotkarten, ruft also einfach nach uns, falls Ihr noch mehr gesammelt haben solltet. Wir verfügen auch über unsere eigenen ausgebildeten Handwerker - erlaubt uns also, Euch etwas im Austausch für die Karten anzubieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13312] = { id = 13312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Eisenwallbollwerk", description = "Das Eisenwallbollwerk blickt über das Tal der Gefallenen Helden westlich von Aldur'thar. Vom Bollwerk aus kann man die Felder zu allen Seiten hin kontrollieren. Wir werden nicht weiter vorstoßen können, wenn das Bollwerk nicht genommen werden kann - doch es wird von Grimkor dem Boshaften und seinen Jüngern des Kults der Verdammten gehalten.\n\nWenn Ihr Grimkor schwächen könnt, werden unsere Streitkräfte wissen, was sie bei ihrem Vormarsch erwarten wird. Hier, nehmt diese Rune der Verzerrung. Seine Macht in der Nähe von Grimkors Kugel am Ende des Bollwerks freizusetzen, sollte genügen, um die Aufmerksamkeit der Nekromanten zu erregen.", sourceObjective = "Besiegt Grimkor den Boshaften und kehrt zu Koltira Todesweber an Bord der Orgrims Hammer zurück.", completion = "Grimkor ist also durch Eure Hand gefallen? Ausgezeichnete Arbeit. Mit ihm aus dem Weg sind unsere Chancen, das Bollwerk während des Angriffs zu halten, um einiges größer.", sourceObjectiveStatus = "unverified-source-field" }
quests[13313] = { id = 13313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Augen im Himmel erblinden lassen", description = "Die Allianz hat es irgendwie geschafft, eine Schwadron von Aufklärungsfahrzeugen über das Tal der Gefallenen Helden und den Eiskronengletscher zu entsenden, die weiten Gebiete westlich von Aldur'thar.\n\nWir können ihnen nicht die Führung in diesem Kampf überlassen. Chefingenieur Kupferklammer hat mich mit der perfekten Waffe, um dieser Bedrohung Herr zu werden, ausgestattet. Er nennt seine neue Rakete die BGR-3. Ich habe seine Versicherung, dass sie die fliegenden Maschinen der Allianz mit einem einzigen Treffer ausschalten wird. Geht und benutzt diese Waffe dazu, uns die Oberhand zu verschaffen.", sourceObjective = "Benutzt die BGR-3, um damit 6 Kampfaufklärer der Himmelsbrecher abzuschießen. Dann meldet Euch wieder bei Himmelshäscher Korm Schwarznarbe an Bord der Orgrims Hammer.", completion = "Gut. Weniger dieser stinkenden Allianzler, die uns im Weg stehen. Wir werden ihnen zeigen, wie wahre Krieger aussehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13314] = { id = 13314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschafft die Nachricht", description = "Die Horde führt irgendetwas im Schilde - mir gefällt das nicht. Nach der verrückten Vorstellung, die sie an der Zerbrochenen Front geliefert haben, sind sie zu allem fähig, und es liegt an uns, sie aufzuhalten.\n\nEs herrscht viel Bewegung am Himmel über dem Eiskronengletscher westlich von Aldur'thar und dem Eisenwallbollwerk. Späher und Boten der Horde auf Drachenfalken fliegen wie der Wind ein und aus - Berichte und Befehle bei sich tragend. Nehmt diese Pfeilpistole und tötet mit ihr die Späher der Orgrims Hammer. Am besten wird es wahrscheinlich dann funktionieren, wenn Ihr auch fliegt.", sourceObjective = "Beschafft Euch 6 Sendungen der Orgrims Hammer von den Spähern der Orgrims Hammer und bringt sie zu Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher.", progress = "Habt Ihr die Sendungen abgefangen?", completion = "Es ist gut, jemanden Kompetenten zu haben, der unsere Mission ausführt, {name}. Wenn wir nur eine Armee von Leuten wie Euch hätten, könnten wir der Horde zeigen, aus was wir gemacht sind. Diese Berichte, die Ihr abgefangen habt, werden uns dabei helfen, in diesem Kampf die Oberhand zu behalten. Wir sind vielleicht am Boden, doch noch lange nicht K.O.", sourceObjectiveStatus = "unverified-source-field" }
quests[13315] = { id = 13315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorschau", description = "Wir machen Fortschritte. Uns steht eine vielversprechende Reihe von Taktiken zur Verfügung, die uns die Kontrolle über das Tor des Todes verschaffen sollten. Es wird zweifellos viele Verluste geben, doch am Ende sollten wir die Oberhand gewinnen, wenn sich die Horde, mit der Ihr Euch unbedingt messen wollt, nicht einmischen wird...\n\nWie dem auch sei: unser nächstes Ziel wird das Tor der Verwüstung sein. Fliegt hinunter und macht Euch mit der Konstruktion und den dort postierten Feinden vertraut.\n\nWenn Ihr wieder zurück seid, werde ich Eure Einsatzbeschreibungen vorbereitet haben.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr hinunter zum Tor der Verwüstung fliegt und Euch den südlichen, zentralen, nördlichen und nordwestlichen Bereich des Tors anseht.", completion = "Schön und gut, {class}.\n\nNun, da Ihr mit eigenen Augen gesehen habt, wem wir hier gegenüberstehen, ist es Zeit, an die Arbeit zu gehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[13316] = { id = 13316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wächter von Corp'rethar", description = "Corp'rethar, das Tor des Schreckens, ist das letzte Hindernis zwischen uns und der Eiskronenzitadelle. Es befindet sich südlich des Eisenwallbollwerks jenseits des Gletschers und des Großbrands. Wenn unsere Truppen erst einmal dort angekommen sind, werden sie erschöpft sein, falls ihnen nicht schon Schlimmeres zugestoßen ist.\n\nWir müssen seine Verteidigung schwächen, oder unsere Armee wird an seinen Mauern zugrunde gehen.\n\nDie Zinnen werden von einigen der stärksten und eifrigsten Dienern des Lichkönigs bemannt. Tut alles, was in Eurer Macht steht, um diese Wächter zu vernichten, und hofft, dass dies ausreicht.", sourceObjective = "Koltira Todesweber an Bord der Orgrims Hammer wünscht, dass Ihr 5 Herolde des Schreckens und 5 Wächter von Corp'rethar tötet.", completion = "Ich hoffe, dass sich Euer Erfolg bei Corp'rethar als Omen für die kommende Schlacht erweisen wird. Der Lichkönig kann nicht tatenlos herumstehen, während wir auf die Tore seiner Festung zumarschieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13317] = { id = 13317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "----" }
quests[13318] = { id = 13318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Gewandung", description = "Der Kult der Verdammten hält das Tor der Verwüstung, wie? Wundert mich nicht.\n\nZeit, ein wenig Spaß zu haben. Ihr habt erwähnt, dass am südlichen Ende des Tores neue Kultisten ausgebildet werden. Sie haben mit Sicherheit einen besonderen Gegenstand bei sich, den alle neuen Initianden erhalten - eine Kugel der Illusion.\n\nDiese Artefakte dienen Kultanhängern zur Tarnung, um sich sicheren Durchgang durch feindliche Reihen zu verschaffen, um diese zu infiltrieren oder schlichtweg zwischen ihnen unterzutauchen.\n\nTötet diese Narren, bis Ihr eine von den Kugeln gefunden habt, {class}, und wendet sie dann auf einen Unterwerfer an.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr Kugeln der Illusion von bitteren Initianden in Aldur'thar sammelt und sie dann auf 3 dunkle Unterwerfer anwendet.", completion = "Ein nützliches Werkzeug unter den gegebenen Umständen, meint Ihr nicht?\n\nDer wird einfach nie zu alt...", sourceObjectiveStatus = "unverified-source-field" }
quests[13319] = { id = 13319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehlskette", description = "Eurem Bericht und meinem Wissen über den Kult nach lassen sie einen Aufseher die Operation in jedem Lager am Tor leiten.\n\nIhre Anführer auszuschalten, wäre zwar nur ein vorübergehender Rückschlag für sie, doch es wird sie zumindest verlangsamen und aus dem Gleichgewicht bringen. Und das, {race}, ist für den Augenblick gut genug.\n\nSucht nach diesen Aufsehern und kommt wieder zu mir zurück, wenn sie beseitigt wurden.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr nach Aldur'thar geht und Aufseher Faedris, Aufseher Savryn, Aufseher Veraj und Aufseher Jhaeqon besiegt.", completion = "Gut gemacht, {race}. Doch brecht Euch beim \"Auf die Schulter klopfen\" nicht den Arm. Sie werden diese Aufseher im Nu ersetzt haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[13320] = { id = 13320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kann nicht reproduziert werden", description = "Ich kann ihre Kessel von hier aus riechen, doch was sie da zusammenbrauen, ist keine Seuche.\n\nDiejenigen, die dem Kult die Treue schwören, werden dazu gezwungen, ein Gemisch zu trinken, das ihren Willen raubt und sie für immer zu Sklaven des Lichkönigs macht.\n\nManche sagen, dass der Trank die verzerrte Seele eines Wesens beinhaltet, das gefoltert und schließlich gnadenlos getötet wurde, doch ich habe es noch nie geschafft, ihn zu reproduzieren...\n\nFüllt dieses Fläschchen mit Proben aus jedem der drei Kessel in der nordwestlichen Region des Tors auf und bringt sie zu Chefingenieur Bolzenschlüssel.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr das unterteilte Fläschchen an jedem der 3 Kessel der Kultisten auffüllt und es anschließend zu Chefingenieur Bolzenschlüssel bringt.", progress = "Was habt Ihr da, {race}?", completion = "<Bolzenschlüssel schüttet den Inhalt des Fläschchens in seinen Tetrahydropartikelanalysierer.>\n\nWas wir hier sehen, ist nichts weiter, als dass diese Flüssigkeit kein Gemisch bilden kann...", sourceObjectiveStatus = "unverified-source-field" }
quests[13321] = { id = 13321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt neu testen", description = "Das sollte seinen Zweck erfüllen!\n\nDiese verdrehten Hooligans suchen nach Seelen, die sie in ihren verrückten Saft mischen können? Dann lasst uns ihnen etwas aushelfen!\n\nNehmt einen Schluck hiervon - keine Sorge, ich habe es ausreichend verwässert... Der einzige Effekt wird sein, dass Ihr die Essenz der Kultisten werdet aufspüren können, sobald Ihr sie besiegt habt.\n\nSobald Ihr ein paar Essenzen habt, werft die sich windende Masse fehlgeleiteter Seelen in einen ihrer Kessel.\n\nWollen doch mal sehen, wie ihnen ihre eigene Medizin schmecken wird!", sourceObjective = "Chefingenieur Bolzenschlüssel an Bord der Himmelsbrecher möchte, dass Ihr eine windende Masse in einen der Kessel in Aldur'thar werft.", completion = "Juhuu!\n\nDas wird ihnen eine Lehre sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[13322] = { id = 13322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt neu testen", description = "Diese verdrehten Kultisten suchen nach Seelen, die sie in ihren verrückten Saft mischen können? Dann lasst uns ihnen etwas aushelfen!\n\nNehmt einen Schluck hiervon - keine Sorge, ich habe es ausreichend verwässert... Ich bin mir fast sicher, dass Ihr als Effekt die Essenzen der Kultisten aufspüren könnt.\n\nSobald Ihr ein paar davon habt, werft die sich windende Masse fehlgeleiteter Seelen in einen ihrer Kessel.\n\nWollen doch mal sehen, wie ihnen ihre eigene Medizin schmecken wird!", sourceObjective = "Chefingenieur Bolzenschlüssel an Bord der Himmelsbrecher möchte, dass Ihr das verdünnte Kulttonikum trinkt, Kultisten in Aldur'thar tötet und ihnen ihre besudelte Essenz abnehmt. Fügt danach 10 von den Essenzen zu einer windenden Masse zusammen und werft diese dann in einen ihrer Kessel.", completion = "Juhuu!\n\nDas wird ihnen eine Lehre sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[13323] = { id = 13323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Gewandung", description = "Es sieht aus, als würde die Zahl der Initianden wieder wachsen. Ihr wisst, was Ihr zu tun habt...\n\nDie neuen Kultisten werden am südlichen Ende des Tores eingewiesen. Sie haben mit Sicherheit einen besonderen Gegenstand bei sich, den alle neuen Initianden erhalten - eine Kugel der Illusion.\n\nDiese Artefakte dienen Kultanhängern zur Tarnung, um sich sicheren Durchgang durch feindliche Reihen zu verschaffen, um diese zu infiltrieren oder schlichtweg zwischen ihnen unterzutauchen.\n\nTötet diese Narren, bis Ihr einige davon habt, dann wendet sie auf die Unterwerfer dort an.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr Kugeln der Illusion von bitteren Initianden in Aldur'thar sammelt und sie dann auf 3 dunkle Unterwerfer anwendet.", completion = "Ein nützliches Werkzeug unter den gegebenen Umständen, meint Ihr nicht?\n\nDer wird einfach nie zu alt...", sourceObjectiveStatus = "unverified-source-field" }
quests[13324] = { id = 13324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prismenkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Prismenkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Prismenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Ah, wie ich sehe, habt Ihr ein komplettes Prismenkartenset! Glückwunsch!", completion = "Ihr habt es also geschafft ein Prismenkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13325] = { id = 13325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chaoskartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Chaoskartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Chaoskartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Ah, wie ich sehe, habt Ihr ein komplettes Chaoskartenset! Glückwunsch!", completion = "Ihr habt es also geschafft ein Chaoskartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13326] = { id = 13326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adligenkartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Adligenkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Adligenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Ah, wie ich sehe, habt Ihr ein komplettes Adligenkartenset! Glückwunsch!", completion = "Ihr habt es also geschafft ein Adligenkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13327] = { id = 13327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untodeskartenset des Dunkelmond-Jahrmarkts", description = "Jetzt, da Ihr alle Karten des Untodeskartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", sourceObjective = "Gebt das Untodeskartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", progress = "Ah, wie ich sehe, habt Ihr ein komplettes Untotenkartenset! Glückwunsch!", completion = "Ihr habt es also geschafft ein Untotenkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13328] = { id = 13328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Scherbenhaufen hinterlassen", description = "Oberhalb der Schlachtfelder von Corp'rethar haben die Günstlinge des Lichkönigs drei Kristalle aufgestellt, die Splitter des Schreckens, der Verzweiflung und des Leidens. Sollte es unseren Männern gelingen, die Mauern von Corp'rethar zu erreichen, so wird er diese Waffen gegen unsere Armee einsetzen.\n\nVoll zum Einsatz gebracht, werden diese Kristalle den Geist unserer Männer peinigen und sie mit Schmerz und Angst lähmen. Dann wird es der Geißel ein Leichtes sein, sie einfach so niederzumetzeln.\n\nFindet diese Splitter, zerstört sie und bringt mir ihre zerbrochenen Überreste. Wir dürfen nicht zulassen, dass der Lichkönig diese Waffen einsetzt!", sourceObjective = "Bringt Koltira Todesweber an Bord der Orgrims Hammer den zerbrochenen Splitter des Schreckens, den zerbrochenen Splitter der Verzweiflung und den zerbrochenen Splitter des Leidens.", progress = "Habt Ihr die neuen Waffen des Lichkönigs zerstört?", completion = "<Koltira nimmt die Kristallsplitter entgegen und spricht mit ruhiger Stimme.>\n\nIch erinnere mich hieran...\n\nSchwächere Männer würden leicht unter ihrem Angriff zusammenbrechen. Diese Bedrohung zu beenden war gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13329] = { id = 13329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor dem Tor des Schreckens", description = "Der Großbrand, das Gebiet vor Corp'rethar südlich des Eisenwallbollwerks, ist der Ort, an dem sich die Elitesoldaten des Lichkönigs zur Verteidigung der Zitadelle formiert haben.\n\nDer Weg wird von einer Legion Skeletthäscher versperrt, angeführt von einem Todesritterkontingent. Ich befürchte, dass, selbst wenn die Häscher beseitigt werden sollten, die Geißel sie einfach wieder aufstellen und gegen uns in den Kampf schicken würde.\n\nIch habe zwar einen Plan entwickelt, wie wir sie davon abhalten können, bin mir jedoch nicht sicher, ob es funktionieren wird. Hier, nehmt diese Lösung und zersetzt mit ihr die Überreste der Häscher.", sourceObjective = "Koltira Todesweber an Bord der Orgrims Hammer wünscht, dass Ihr mithilfe der flüchtigen Säure die Überreste von 6 Skeletthäschern zersetzt.", completion = "<Koltira hört sich Euren Bericht an.>\n\nGut. Ich werde die Ingenieure so viel wie möglich von der Säure zusammenmischen lassen, bevor wir Corp'rethar mit der Hauptstreitmacht angreifen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13330] = { id = 13330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut der Auserwählten", description = "Diejenigen Vrykul, die beim Lichkönig hoch im Ansehen stehen, nennen sich selbst die Ymirjar. Sie bewohnen eine Stadt im Zentrum von Eiskrone. Wir haben eine Menge Aufgaben zu erledigen, bevor wir die Eiskronenzitadelle angreifen können, und diejenige, die uns nun bevorsteht, ist, diese so genannten \"Auserwählten\" des Lichkönigs plattzumachen.\n\nBegebt Euch in Ihre Stadt, Ymirheim, und schlachtet sie in ihren Häusern ab. Hinterlasst keine Zweifel darüber, wer hier die stärkeren Kämpfer hat.", sourceObjective = "Kriegshetzer Davos Rabatz auf der Orgrims Hammer hat Euch entsandt, 20 Vrykul in Ymirheim zu töten.", completion = "Wohl doch nicht ganz so stark, wie? Der Lichkönig erntet nun, was er gesät hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13331] = { id = 13331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Allianz die Augen zuhalten", description = "Die Allianz ist hartnäckig, so viel gestehe ich ihr zu, aber es bedarf mehr, um uns aufzuhalten. Nehmt diese BGR-3 und schießt erneut die Kampfaufklärer der Himmelsbrecher ab.\n\nIch bezweifele zwar, dass die Nachricht in ihre dicken Schädel reingeht, aber wir verfügen über genügend Raketen, um unseren Punkt deutlich zu machen. Geht und haltet über dem Tal der Gefallenen Helden, westlich von Aldur'thar, nach ihren Aufklärern Ausschau. Und kommt nicht zurück, solange Ihr sie nicht in Trümmer gelegt habt.", sourceObjective = "Benutzt die BGR-3 um 6 Kampfaufklärer der Himmelsbrecher zu zerstören und erstattet dann dem Himmelshäscher Korm Schwarznarbe an Bord der Orgrims Hammer Bericht.", completion = "Mal wieder gut gemacht. Die Vorherrschaft der Horde ist gesichert, jedenfalls bis dieser Allianzlerabschaum sich entschließt, uns erneut herauszufordern.", sourceObjectiveStatus = "unverified-source-field" }
quests[13332] = { id = 13332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Errichtet die Barrikaden", description = "Sobald unsere Truppen sich hinter Aldur'thar befinden, werden sie verwundbar durch Attacken vom Eisenwallbollwerk oder dem breiten Gletscher darunter sein.\n\nWir haben weder die Zeit noch das Material, um Befestigungen zu bauen, aber wir können ein paar Barrikaden errichten, um unsere Männer vor Feuer zu schützen und Angriffe der Geißel abprallen zu lassen.\n\nNehmt diesen Barrikadenbausatz mit zum Tal der Gefallenen Helden. Findet die Markierungen, die ich dort gesetzt habe und benutzt den Bausatz, um dort Eure Barrikaden zu errichten.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr 8 Barrikaden mithilfe Eures Barrikadenbausatzes errichtet.", completion = "<Thassarian nickt kurz.>\n\nGut. Sie bieten nicht gerade viel Schutz, aber immer noch besser als nichts. Dieses Tor ist noch immer der perfekte Engpass, wenn die Geißelanführer wissen, was sie tun. Wir müssen so viel von dem umliegenden Gebiet wie möglich einnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13333] = { id = 13333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Sendungen abfangen", description = "Trotz unserer Anstrengungen schickt die Horde weiterhin Späher in diese Gegend des Eiskronengletschers, westlich des Eisenwallbollwerks und Aldur'thar.\n\nWir können es uns nicht leisten, der Horde bei dieser Erkundungsoperation die Oberhand zu lassen. Nehmt wieder diese Pfeilpistole mit Euch und zeigt den Spähern der Orgrims Hammer keine Gnade! Bringt die abgefangenen Sendungen zu mir.\n\nWir werden die Fehlschläge der Horde zu unseren Gunsten nutzen.", sourceObjective = "Fangt 6 Sendungen der Orgrims Hammer von den Spähern der Orgrims Hammer ab und bringt sie zu Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher.", progress = "Habt Ihr die Sendungen abgefangen?", completion = "<Der Hochkapitän nimmt die Sendungen entgegen.>\n\nDas ist genau, was wir brauchen. Selbst die Horde ist nicht so dumm, einen Ansturm auf die Geißel blind zu wagen. Mit ihren Berichten in Händen, werden wir gut vorbereitet sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13334] = { id = 13334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutbespritzte Banner", description = "Im Tal der Gefallenen Helden und am Eiskronengletscher, im Westen Aldur'thars, versucht die Geißel, die Gefallenen gegen uns zu verwenden. Die Kommandanten der Geißel haben die Toten aus dem Tal wiedererweckt und sie mit furchterregender Stärke und Leidenschaft erfüllt. Die Banner, die die Geißelanführer in der Gletschergegend bei sich tragen, sind die Quelle dieser Mächte. Tötet die Bannerträger und Ihr werdet die konvertierten Helden, die sie führen, schwächen.\n\nEs obliegt Euch, uns von diesem Hindernis zu befreien und zu testen, wie es um deren Widerstand steht, bevor die Hauptstreitmacht vorrücken kann.", sourceObjective = "Thassarian auf der Himmelsbrecher möchte, dass Ihr 5 Bannerträger der Geißel, 5 Konvertierer der Geißel und 20 konvertierte Helden tötet.", completion = "Ihr habt die Bannerträger der Geißel und ihre Lakaien entfernt? Gut. Unsere Vorbereitungen müssen weitergehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13335] = { id = 13335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor dem Tor des Schreckens", description = "Der Großbrand, das Gebiet vor Corp'rethar südlich des Eisenwallbollwerks, ist der Ort, an dem sich die Elitesoldaten des Lichkönigs zur Verteidigung der Zitadelle formiert haben.\n\nDer Weg wird von einer Legion Skeletthäscher versperrt, angeführt von einem Todesritterkontingent. Ich befürchte, dass, selbst wenn die Häscher beseitigt werden sollten, die Geißel sie einfach wieder aufstellen und gegen uns in den Kampf schicken würde.\n\nIch habe zwar einen Plan entwickelt, wie wir sie davon abhalten können, bin mir jedoch nicht sicher, ob es funktionieren wird. Hier, nehmt diese Lösung und zersetzt mit ihr die Überreste der Häscher.", sourceObjective = "Thassarian an Bord der Himmelsbrecher wünscht, dass Ihr mithilfe der flüchtigen Säure die Überreste von 6 Skeletthäschern zersetzt.", completion = "<Thassarian hört Euch zu, als Ihr von Eurem erfolgreichen Test erzählt.>\n\nDie Säure hat also funktioniert? Gut. Wir werden sie brauchen, wenn die Armee die Häscher mit voller Stärke angreifen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[13336] = { id = 13336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut der Auserwählten", description = "Diejenigen Vrykul, die beim Lichkönig hoch im Ansehen stehen, nennen sich selbst die Ymirjar. Sie bewohnen eine Stadt im Zentrum von Eiskrone. Wir haben eine Menge Aufgaben zu erledigen, bevor wir die Eiskronenzitadelle angreifen können, und diejenige, die uns nun bevorsteht, ist, diese so genannten \"Auserwählten\" des Lichkönigs plattzumachen.\n\nBegebt Euch in Ihre Stadt, Ymirheim, und schlachtet sie in ihren Häusern ab. Hinterlasst keine Zweifel darüber, wer hier die stärkeren Kämpfer hat.", sourceObjective = "Kürassier Drosche auf der Himmelsbrecher hat Euch entsandt, 20 Vrykul in Ymirheim zu töten.", completion = "Der Verräterkönig wird gestürzt werden. Daran hege ich keinen Zweifel.", sourceObjectiveStatus = "unverified-source-field" }
quests[13337] = { id = 13337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Eisenwallbollwerk", description = "Das Eisenwallbollwerk blickt über das Tal der Gefallenen Helden westlich von Aldur'thar. Vom Bollwerk aus kann man die Felder zu allen Seiten hin kontrollieren. Wir werden nicht weiter vorstoßen können, wenn das Bollwerk nicht genommen werden kann - doch es wird von Grimkor dem Boshaften und seinen Jüngern des Kults der Verdammten gehalten.\n\nWenn Ihr Grimkor schwächen könnt, werden unsere Streitkräfte wissen, was sie bei ihrem Vormarsch erwarten wird. Hier, nehmt diese Rune der Verzerrung. Seine Macht in der Nähe von Grimkors Kugel am Ende des Bollwerks freizusetzen, sollte genügen, um die Aufmerksamkeit der Nekromanten zu erregen.", sourceObjective = "Besiegt Grimkor den Boshaften und kehrt zu Thassarian an Bord der Himmelsbrecher zurück.", progress = "Habt Ihr Eure Mission abgeschlossen?", completion = "Grimkor ist also durch Eure Hand gefallen? Ausgezeichnete Arbeit. Mit ihm aus dem Weg sind unsere Chancen, das Bollwerk während des Angriffs zu halten, um einiges größer.", sourceObjectiveStatus = "unverified-source-field" }
quests[13338] = { id = 13338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wächter von Corp'rethar", description = "Corp'rethar, das Tor des Schreckens, ist das letzte Hindernis zwischen uns und der Eiskronenzitadelle. Es befindet sich südlich des Eisenwallbollwerks jenseits des Gletschers und des Großbrands. Wenn unsere Truppen erst einmal dort angekommen sind, werden sie erschöpft sein, falls ihnen nicht schon Schlimmeres zugestoßen ist.\n\nWir müssen seine Verteidigung schwächen, oder unsere Armee wird an seinen Mauern zugrunde gehen.\n\nDie Zinnen werden von einigen der stärksten und eifrigsten Dienern des Lichkönigs bemannt. Tut alles, was in Eurer Macht steht, um diese Wächter zu vernichten, und hofft, dass dies ausreicht.", sourceObjective = "Thassarian an Bord der Himmelsbrecher wünscht, dass Ihr 5 Herolde des Schreckens und 5 Wächter von Corp'rethar tötet.", completion = "Ich hoffe, dass sich Euer Erfolg bei Corp'rethar als Omen für die kommende Schlacht erweisen wird. Der Lichkönig kann nicht tatenlos herumstehen, während wir auf die Tore seiner Festung zumarschieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13339] = { id = 13339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Scherbenhaufen hinterlassen", description = "Oberhalb der Schlachtfelder von Corp'rethar haben die Günstlinge des Lichkönigs drei Kristalle aufgestellt, die Splitter des Schreckens, der Verzweiflung und des Leidens. Sollte es unseren Männern gelingen, die Mauern von Corp'rethar zu erreichen, so wird er diese Waffen gegen unsere Armee einsetzen.\n\nVoll zum Einsatz gebracht, werden diese Kristalle den Geist unserer Männer peinigen und sie mit Schmerz und Angst lähmen. Dann wird es der Geißel ein Leichtes sein, sie einfach so niederzumetzeln.\n\nFindet diese Splitter, zerstört sie und bringt mir ihre zerbrochenen Überreste. Wir dürfen nicht zulassen, dass der Lichkönig diese Waffen einsetzt!", sourceObjective = "Bringt Thassarian an Bord der Himmelsbrecher den zerbrochenen Splitter des Schreckens, den zerbrochenen Splitter der Verzweiflung und den zerbrochenen Splitter des Leidens.", progress = "Habt Ihr die neuen Waffen des Lichkönigs zerstört?", completion = "<Thassarian nimmt die Kristallsplitter entgegen und spricht mit ruhiger Stimme.>\n\nIch erinnere mich hieran...\n\nSchwächere Männer würden leicht unter ihrem Angriff zusammenbrechen. Diese Bedrohung zu beenden war gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13340] = { id = 13340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schließt Euch dem Angriff an", description = "Wir brauchen mehr Leute, die sich dem Hauptangriff auf Ymirheim anschließen.\n\nJeder Krieger mit einer halben Gehirnzelle kann Euch sagen, dass die Vrykul grimmige Krieger sind, die man nicht auf die leichte Schulter nehmen sollte. Das gilt erst recht für die Ymirjar. Sie haben uns bereits spüren lassen, warum der Lichkönig sie für würdig befunden hat.\n\nFeldkommandant Xutjja befehligt den Angriff. Die Stadt selber befindet sich im Zentrum von Eiskrone, und Xutjjas Truppen sind nahe der Kante des Gletschers im Norden der Stadt positioniert.", sourceObjective = "Meldet Euch bei Feldkommandant Xutjja an der Kante des Gletschers im Norden von Ymirheim.", completion = "Mehr Fleisch für den Schleifer. Willkommen in der Hölle, Soldat.\n\nMeine Männer werden den Angriff auf das Tor von hier aus beginnen, und wir werden einige Infiltratoren aus der Luft absetzen. Wir brauchen mehr Leute an beiden Fronten. Ich habe so das Gefühl, dass sich dieser Angriff eine ganze Weile ziehen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[13341] = { id = 13341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schließt Euch dem Angriff an", description = "Wir brauchen mehr Leute, die sich dem Hauptangriff auf Ymirheim anschließen.\n\nJeder Krieger mit einer halben Gehirnzelle kann Euch sagen, dass die Vrykul grimmige Krieger sind, die man nicht auf die leichte Schulter nehmen sollte. Das gilt erst recht für die Ymirjar. Sie haben uns bereits spüren lassen, warum der Lichkönig sie für würdig befunden hat.\n\nFeldkommandant Koup befehligt den Angriff. Die Stadt selber befindet sich im Zentrum von Eiskrone, und Koups Truppen sind nahe der Kante des Gletschers im Osten der Stadt positioniert.", sourceObjective = "Meldet Euch bei Feldkommandant Koup an der Kante des Gletschers im Osten von Ymirheim.", completion = "Willkommen in der Hölle, Soldat.\n\nMeine Männer werden den Angriff auf das Tor von hier aus beginnen, und wir werden einige Infiltratoren aus der Luft absetzen. Wir brauchen mehr Leute an beiden Fronten. Ich habe so das Gefühl, dass sich dieser Angriff eine ganze Weile ziehen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[13342] = { id = 13342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Wanze", description = "So, <mein Freund/meine Freundin>, es ist an der Zeit eine Wanze zu platzieren.\n\nBeruhigt Euch, es ist nicht wirklich eine Wanze, aber es wird unseren Zwecken dienlich sein.\n\nIm nördlichen Bereich von Aldur'thar versklaven die Leerenbeschwörer des Kults dämonische Lakaien. Benutzt diese Rute, um den Körpern dieser versklavten Lakaien die dunkle Materie zu entziehen, und dann benutzt ihren Beschwörungskristall, um unseren kleinen Spion zu erschaffen.\n\nBis er entdeckt wird, wird unser Bote unsere Augen und Ohren sein und ganz diskret die Handlungen unseres Gegners überwachen.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr 5 dunkle Materien sammelt und in Aldur'thar einen dunklen Boten beschwört.", completion = "Das habt Ihr gut gemacht, {class}.\n\nDer Bote hat uns bereits einige wertvolle Informationen zukommen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13343] = { id = 13343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnis der Ewigen, die 2.", description = "Da seid Ihr ja! Oder haben wir gerade erst miteinander gesprochen?\n\n<Chromie denkt über die Vielfalt der temporalen Möglichkeiten nach.>\n\nWie dem auch sei, die Ewigen sind hinter Euch her! Nun, an und für sich sind sie nicht hinter Euch her, sondern eher hinter der vergangenen Version von Euch, die einst das Stundenglas der Ewigkeit verteidigte. Ihr könnt Euch noch daran erinnern, oder?\n\nIhr wart das damals, nur seid Ihr es jetzt auch wieder. Halt, das ist nicht so wichtig. Was wichtig ist, ist, dass Ihr zurück zum Bronzedrachenschrein geht und Euch und das Stundenglas vor ihren Angriffen schützt, bevor man Euch aus der Geschichte entfernt!", sourceObjective = "Chromie auf der höchsten Ebene des Wyrmruhtempels wünscht, dass Ihr noch einmal zum Bronzedrachenschrein reist.\n\nSobald Ihr dort seid, sollt Ihr das Stundenglas der Ewigkeit auf den Boden stellen und Eurem vergangenen Selbst dabei helfen, es vor den Truppen des ewigen Drachenschwarms zu beschützen.", completion = "Ach du meine Güte, Ihr habt es geschafft! Ich war mir nicht sicher, ob es Euch gelingen würde.\n\nIhr seid während des Kampfes für einen Moment aus dem Zeitfluss verschwunden! Ich habe schon gedacht, wir hätten Euch verloren!\n\nDoch da seid Ihr gesund und munter - Euer vergangenes Selbst auf der anderen Seite der Zeitschleife, in der Ihr feststecktet, gerettet.\n\nIhr seid ein ziemlich temporaler Held, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13344] = { id = 13344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Wanze", description = "Die Kultisten haben den letzten Boten, den Ihr beschworen habt, entdeckt, {race}.\n\nEr hat uns zwar bereits sehr viele Informationen beschafft, aber es ist wichtig, dass wir weiter über jeden Schritt unserer Feinde informiert sind.\n\nBenutzt diese Rute, um den Körpern der versklavten Lakaien die dunkle Materie zu entziehen, und dann benutzt ihren Beschwörungskristall, um einen weiteren dunklen Boten zu erschaffen.\n\nBis er entdeckt wird, wird unser Bote unsere Augen und Ohren sein und ganz diskret die Handlungen unseres Gegners überwachen.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr 5 dunkle Materien sammelt und in Aldur'thar einen dunklen Boten beschwört.", completion = "Gut gemacht, Freund.\n\nDer Bote ist bereits bei der Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13345] = { id = 13345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brauche mehr Informationen", description = "Der Kult der Verdammten ist dafür berühmt, grandiose Pläne auszuarbeiten, die letzten Endes allerdings selten erfolgreich sind. Diesmal allerdings scheint es anders zu sein...\n\nVielleicht ist es die Nähe zum Lichkönig, die ihre Inbrunst angefacht hat. Was immer es auch ist, sie scheinen selbstbewusster denn je. Wir müssen herausfinden, was ihren Eifer befeuert und dieses dann ganz schnell unterbinden!\n\nIch glaube, dass der Schlüssel dazu ihre Forscher sind. Findet heraus, was sie im Schilde führen und berichtet mir dann.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr 3 Seiten Forschung der Kultisten von den Forschern der Kultisten in Aldur'thar sammelt, um damit eine These über den Kult der Verdammten zu erstellen.", progress = "Habt Ihr herausgefunden, was die Forscher im Schilde führen, {class}?", completion = "Das ist in der Tat alarmierend...", sourceObjectiveStatus = "unverified-source-field" }
quests[13346] = { id = 13346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es kann der Böseste nicht in Frieden ruhen...", description = "Die Dummköpfe sind übrigens über etwas gestolpert, das äußerst gefährlich für unsere Pläne werden könnte!\n\nAlumeth, der Anführer dieser Sekte, hat sich in einem Ritual selbst geopfert und nun versorgen seine Untergebenen seine Seele mit Macht.\n\nWenn wir ihn weiterhin in Ruhe lassen, werden sie ihn schon bald zu einem mächtigen Gegner machen.\n\nIn ihrer Kammer verteilt liegt sein Herz, Szepter, Schädel und seine Robe - kombiniert sie miteinander und benutzt das, was dabei rauskommt, in der Nähe der dortigen Kristalle.\n\nBeeilt Euch, {race}! Vernichtet ihn, bevor er noch mächtiger wird!", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr Alumeth den Aufgestiegenen in Aldur'thar besiegt.", completion = "Alumeth hat eine glatte Niederlage hinnehmen müssen, doch ich spüre, dass sich sein Geist noch immer hier aufhält...", sourceObjectiveStatus = "unverified-source-field" }
quests[13347] = { id = 13347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedergeboren aus der Asche", description = "Unser Schicksal steht schon von Geburt an fest. Bolvars Fall, wenn auch tragisch, war unvermeidlich.\n\nAlles, was Ihr jetzt noch tun könnt, {name}, ist, Eurem Helden die letzte Ehre zu erweisen. Geht zum Schlachtfeld, holt Euch Bolvars Schild und bringt ihn Eurem König. Übermittelt ihm bei der Übergabe diese Botschaft: \"Nicht alles ist verloren. Aus der Asche der Gefallenen wird eine Macht emporsteigen, die Reiche vereinen und das Böse aus dieser Welt treiben wird.\"\n\nEr darf den Glauben nicht verlieren. Geht jetzt, {name}. Euer Volk braucht einen Helden - es braucht Euch.", sourceObjective = "Geht zum Schlachtfeld vor Angrathar, der Pforte des Zorns, findet Fordragons Schild und bringt ihn zu König Varian Wrynn nach Burg Sturmwind in Sturmwind.", progress = "<König Wrynn wischt sich eine Träne aus dem Gesicht.>\n\n<Er nickt.>\n\nDas ist meine Schuld.", completion = "Die Drachenkönigin hat recht, {name}. Noch ist nicht alles verloren. Ich werde die Macht sein, die aus der Asche steigt, und ich werde das Böse der Horde aus der Welt schaffen. Der Tod unserer Brüder und Schwestern wird nicht umsonst gewesen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13348] = { id = 13348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sinnlosigkeit", description = "Seht Ihr es nun? Eure Männer gegen die Armeen des Prinzen zu entsenden sorgt nur dafür, dass ihre Reihen weiter anwachsen.\n\nIch erwarte nicht, dass Ihr es versteht... Ihr werdet vermutlich auch wie die anderen enden. Am besten kehrt Ihr zu denjenigen zurück, die Euch entsandt haben. Sie werden sich Sorgen machen.", sourceObjective = "Kehrt zu Koltira Todesweber an Bord der Orgrims Hammer zurück.", completion = "Da seid Ihr ja. Gute Arbeit unten im Tal. Das Gemetzel konnte man selbst von hier oben aus verfolgen.\n\nSeid Ihr in Ordnung? Ihr seht aus, als hättet Ihr einen Geist gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13349] = { id = 13349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wiege der Frostbrut", description = "Wir müssen unseren Vorteil ausnutzen und weitermachen. Lasst uns den Streitkräften der Geißel keine Pause gönnen.\n\nSindragosas Sturz liegt gleich östlich jenseits des Tals der Verlorenen Hoffnung. Der Kult der Verdammten operiert dort unter strenger Aufsicht der untoten Vrykullakaien des Lichkönigs.\n\nEs ist ein Ort großer Macht, möglicherweise ein Friedhof des blauen Drachenschwarms, in dem sie aus den Knochen blauer Drachen die gefürchtete Frostbrut erschaffen.\n\nEin Angriff dort würde es für den Feind erheblich schwieriger machen, an Frostwyrms heranzukommen. Was sagt Ihr dazu, {name}?", sourceObjective = "Koltira Todesweber an Bord der Orgrims Hammer möchte, dass Ihr 5 Wyrmwiedererwecker, 8 Verderber der Kultisten und 3 Nekrolords der Vrykul in Sindragosas Sturz tötet.", completion = "Das habt Ihr gut gemacht, {name}. Ihr ruht Euch besser für eine Weile aus. Ihr seht ein wenig blass aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[13350] = { id = 13350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es kann der Böseste nicht in Frieden ruhen...", description = "Es ist Alumeth... Seine Macht wächst wieder an. Ich kann es fühlen. Wieder versorgen seine Untergebenen seine Seele mit Energie.\n\nWenn wir zulassen, dass er sich weiter erholt, werden ihre Bemühungen ihn zu einem mächtigen Gegner machen.\n\nKehrt in seine Kammer im Norden von Aldur'thar zurück. Sammelt sein Herz, seinen Schädel, sein Zepter und seine Kleider und wendet seine Überreste dann auf den Kristall dort an.\n\nEilt Euch, {race}! Vernichtet ihn, bevor er noch mächtiger wird!", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr Alumeth den Aufgestiegenen in Aldur'thar vernichtet.", completion = "Alumeth hat eine glatte Niederlage hinnehmen müssen, doch ich spüre, dass sich sein Geist noch immer hier aufhält...", sourceObjectiveStatus = "unverified-source-field" }
quests[13351] = { id = 13351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorschau", description = "Wir machen Fortschritte. Uns steht eine vielversprechende Reihe von Taktiken zur Verfügung, die uns die Kontrolle über das Tor des Todes verschaffen sollten. Es wird zweifellos viele Verluste geben, doch am Ende sollten wir die Oberhand gewinnen - außer, die Allianz mischt sich ein.\n\nAls Nächstes werden wir uns auf Aldur'thar, das Tor der Verwüstung, konzentrieren. Fliegt hinunter und macht Euch mit der Konstruktion und den dort postierten Feinden vertraut.\n\nWenn Ihr wieder zurück seid, werde ich Eure Einsatzbeschreibungen vorbereitet haben.", sourceObjective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr hinunter zum Tor der Verwüstung fliegt und Euch den südlichen, zentralen, nördlichen und nordwestlichen Bereich des Tors anseht.", completion = "Schön und gut, {class}.\n\nNun, da Ihr mit eigenen Augen gesehen habt, wem wir hier gegenüberstehen, ist es Zeit, an die Arbeit zu gehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[13352] = { id = 13352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Gewandung", description = "Der Kult der Verdammten hält das Tor der Verwüstung, wie? Wundert mich nicht.\n\nZeit, ein wenig Spaß zu haben. Ihr habt erwähnt, dass am südlichen Ende des Tores neue Kultisten ausgebildet werden. Sie haben mit Sicherheit einen besonderen Gegenstand bei sich, den alle neuen Initianden erhalten - eine Kugel der Illusion.\n\nDiese Artefakte dienen Kultanhängern zur Tarnung, um sich sicheren Durchgang durch feindliche Reihen zu verschaffen, um diese zu infiltrieren oder schlichtweg zwischen ihnen unterzutauchen.\n\nTötet diese Narren, bis Ihr eine von den Kugeln gefunden habt, {class}, und wendet sie dann auf einen Unterwerfer an.", sourceObjective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr Kugeln der Illusion von bitteren Initianden in Aldur'thar sammelt und sie dann auf 3 dunkle Unterwerfer anwendet.", completion = "Ein nützliches Werkzeug unter den gegebenen Umständen, meint Ihr nicht?\n\nDer wird einfach nie zu alt...", sourceObjectiveStatus = "unverified-source-field" }
quests[13353] = { id = 13353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Gewandung", description = "Es sieht aus, als würde die Zahl der Initianden wieder wachsen. Ihr wisst, was Ihr zu tun habt...\n\nDie neuen Kultisten werden am südlichen Ende des Tores eingewiesen. Sie haben mit Sicherheit einen besonderen Gegenstand bei sich, den alle neuen Initianden erhalten - eine Kugel der Illusion.\n\nDiese Artefakte dienen Kultanhängern zur Tarnung, um sich sicheren Durchgang durch feindliche Reihen zu verschaffen, um diese zu infiltrieren oder schlichtweg zwischen ihnen unterzutauchen.\n\nTötet diese Narren, bis Ihr einige davon habt, dann wendet sie auf die Unterwerfer dort an.", sourceObjective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr Kugeln der Illusion von bitteren Initianden in Aldur'thar sammelt und sie dann auf 3 dunkle Unterwerfer anwendet.", completion = "Ein nützliches Werkzeug unter den gegebenen Umständen, meint Ihr nicht?\n\nDer wird einfach nie zu alt...", sourceObjectiveStatus = "unverified-source-field" }
quests[13354] = { id = 13354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehlskette", description = "Eurem Bericht und meinem Wissen über den Kult nach lassen sie einen Aufseher die Operation in jedem Lager am Tor leiten.\n\nIhre Anführer auszuschalten, wäre zwar nur ein vorübergehender Rückschlag für sie, doch es wird sie zumindest verlangsamen und aus dem Gleichgewicht bringen. Und das, {race}, ist für den Augenblick gut genug.\n\nSucht nach diesen Aufsehern und kommt wieder zu mir zurück, wenn sie beseitigt wurden.", sourceObjective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr nach Aldur'thar geht und Aufseher Faedris, Aufseher Savryn, Aufseher Veraj und Aufseher Jhaeqon besiegt.", completion = "Gut gemacht, {race}. Doch brecht Euch beim \"Auf die Schulter klopfen\" nicht den Arm. Sie werden diese Aufseher im Nu ersetzt haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[13355] = { id = 13355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kann nicht reproduziert werden", description = "Ich kann ihre Kessel von hier aus riechen, doch was sie da zusammenbrauen, ist keine Seuche.\n\nDiejenigen, die dem Kult die Treue schwören, werden dazu gezwungen, ein Gemisch zu trinken, das ihren Willen raubt und sie für immer zu Sklaven des Lichkönigs macht.\n\nManche sagen, dass der Trank die verzerrte Seele eines Wesens beinhaltet, das gefoltert und schließlich gnadenlos getötet wurde, doch ich habe es noch nie geschafft, ihn zu reproduzieren...\n\nFüllt dieses Fläschchen mit Proben aus jedem der drei Kessel in der nordwestlichen Region des Tors auf und bringt sie zu Chefingenieur Kupferklammer.", sourceObjective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr das unterteilte Fläschchen an jedem der 3 Kessel der Kultisten auffüllt und es anschließend zu Chefingenieur Kupferklammer bringt.", progress = "Was habt Ihr da, {race}?", completion = "<Kupferklammer schüttet den Inhalt des Fläschchens in seinen Partikelanalysierer.>\n\nAhh... ich weiß genau das Richtige!", sourceObjectiveStatus = "unverified-source-field" }
quests[13356] = { id = 13356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt neu testen", description = "Das sollte seinen Zweck erfüllen!\n\nDiese verdrehten Hooligans suchen nach Seelen, die sie in ihren Irren-Saft mischen können? Dann lasst uns ihnen etwas aushelfen!\n\nNehmt einen Schluck hiervon - keine Sorge, ich habe es ausreichend verwässert... Der einzige Effekt wird sein, dass Ihr die Essenz der Kultisten werdet aufspüren können, sobald Ihr sie besiegt habt.\n\nSobald Ihr ein paar Essenzen habt, werft die sich windende Masse fehlgeleiteter Seelen in einen ihrer Kessel.\n\nWollen doch mal sehen, wie ihnen ihre eigene Medizin schmecken wird!", sourceObjective = "Chefingenieur Kupferklammer an Bord der Orgrims Hammer möchte, dass Ihr eine windende Masse in einen der Kessel in Aldur'thar werft.", completion = "Juhuu!\n\nDas wird ihnen eine Lehre sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[13357] = { id = 13357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt neu testen", description = "Diese verdrehten Kultisten suchen nach Seelen, die sie in ihren verrückten Saft mischen können? Dann lasst uns ihnen etwas aushelfen!\n\nNehmt einen Schluck hiervon - keine Sorge, ich habe es ausreichend verwässert... Ich bin mir fast sicher, dass Ihr als Effekt die Essenzen der Kultisten aufspüren könnt.\n\nSobald Ihr ein paar davon habt, werft die sich windende Masse fehlgeleiteter Seelen in einen ihrer Kessel.\n\nWollen doch mal sehen, wie ihnen ihre eigene Medizin schmecken wird!", sourceObjective = "Chefingenieur Kupferklammer an Bord der Orgrims Hammer möchte, dass Ihr eine windende Masse in einen der Kessel in Aldur'thar werft.", completion = "Juhuu!\n\nDas wird ihnen eine Lehre sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[13358] = { id = 13358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Wanze", description = "So, <mein Freund/meine Freundin>, es ist an der Zeit eine Wanze zu platzieren.\n\nBeruhigt Euch, es ist nicht wirklich eine Wanze, aber es wird unseren Zwecken dienlich sein.\n\nIm nördlichen Bereich von Aldur'thar versklaven die Leerenbeschwörer des Kults dämonische Lakaien. Benutzt diese Rute, um den Körpern dieser versklavten Lakaien die dunkle Materie zu entziehen, und dann benutzt den Beschwörungskristall der Kultisten, um unseren kleinen Spion zu erschaffen.\n\nBis er entdeckt wird, wird unser Bote unsere Augen und Ohren sein und ganz diskret die Handlungen unseres Gegners überwachen.", sourceObjective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr 5 dunkle Materien sammelt und in Aldur'thar einen dunklen Boten beschwört.", completion = "Das habt Ihr gut gemacht, {class}.\n\nDer Bote hat uns bereits einige wertvolle Informationen zukommen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13359] = { id = 13359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo Drachen einst fielen", description = "Einst fiel hier eine ganze Brut von blauen Drachen. Und nun wird jeder einzelne von ihnen von seinen Dienern wiedererweckt.\n\nDen größten von ihnen hat er selbst wiedererweckt. Bringt mir ein wenig Knochenstaub von ihren Welpen und ich werde Euch ganz genau zeigen, wie er das gemacht hat.", sourceObjective = "Matthias Lehner in Sindragosas Sturz möchte, dass Ihr 6 Einheiten Welpenknochenstaub besorgt.", progress = "Habt Ihr den Staub bekommen, {name}?", completion = "Selbst die mächtigen Wyrm mussten seinem Ruf folgen. Wie könnte ein einfacher Sterblicher wie Ihr ihm widerstehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[13360] = { id = 13360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit für Antworten", description = "Ihr habt viele Fragen, {name}. Ihr seid <der Einzige, der/die Einzige> die; mich sehen kann, weil Ihr etwas berührt habt, das einst ihm gehörte... könnt Ihr Euch nicht mehr erinnern?\n\nIhr wisst nicht, was es ist? Nun, ich kann es Euch nicht einfach so sagen... das würde ihn ziemlich wütend machen. Er ist nicht mehr bloß ein Prinz... er ist jetzt der König!\n\nTrefft mich im Hof der Knochen nördlich der Eiskronenzitadelle und Ihr könnt es für Euch selbst sehen.", sourceObjective = "Sprecht mit Matthias Lehner im Hof der Knochen.", completion = "Da seid Ihr ja. Ich habe mich schon gefragt, wann Ihr auftauchen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13361] = { id = 13361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Jäger und der Prinz", description = "Bevor der Prinz König wurde, schlug er viele Schlachten... doch nur bei einer wäre er beinahe gestorben.\n\nSie fand genau hier statt. Nachdem ich Euch gezeigt habe, was hier einst geschah, werdet Ihr verstehen.\n\nSucht nach einem blutbefleckten Stein und hebt ihn auf. Ihr werdet sehen, was einst geschah.", sourceObjective = "Matthias Lehner im Hof der Knochen möchte, dass Ihr nach einem blutbefleckten Stein sucht und das Schicksal des Prinzen zu Ende bringt.", progress = "Habt Ihr es gesehen, {name}? Habt Ihr es gesehen?", completion = "Nach dem Kampf erkannte der Prinz, dass das, was ihn zurückhielt, seine Menschlichkeit war... Er konnte noch immer fühlen... konnte noch immer bluten. Er hatte noch immer ein Herz.\n\nSeine erste Handlung als König war es, sein Herz loszuwerden. Er warf es die Grube hinunter, in der wir uns zum ersten Mal begegneten. Und Ihr, {name}, wart der Erste, der es seitdem berührt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13362] = { id = 13362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen ist eine schreckliche Bürde", description = "Jetzt wisst Ihr, womit Ihr es zu tun habt, {name}. Ein Gegner, der keinen Schmerz mehr kennt... keine Zweifel... und auch keine Menschlichkeit. Ein Gegner, der alles tun würde, um das zu bekommen, was er will.\n\nDas Herz war seine Schwachstelle und er weiß jetzt, dass Ihr es gefunden habt.\n\nWenn Ihr zurückwollt, um es zu holen, dann nehmt Euch besser Hilfe mit. Er wird es nicht noch einmal unbewacht lassen.", sourceObjective = "Meldet Euch bei Koltira Todesweber an Bord der Orgrims Hammer.", completion = "Der Geist eines kleinen Kindes... Das Herz Arthas'... langsam, langsam... In meinem Kopf dreht sich alles.", sourceObjectiveStatus = "unverified-source-field" }
quests[13363] = { id = 13363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe vom Argentumkreuzzug", description = "Es gab Gerüchte unter den Todesrittern über die Ereignisse, von denen Ihr gesprochen habt. Ich hatte immer gedacht, dass sie etwas... symbolischer gemeint wären.\n\nWir müssen die anderen warnen, aber diskret. Sobald der Lichkönig von unserem Aufbruch erfährt, wird er das Herz an einen anderen Ort bringen lassen - solch eine Chance werden wir nie wieder bekommen.\n\nDie Horde und die Allianz wurden schon zuvor vom Kult der Verdammten infiltriert. Die Schwarze Klinge operiert zu nah an der Geißel.\n\nWir müssen mit Tirion Fordring und seinem Argentumkreuzzug sprechen.", sourceObjective = "Sprecht mit Hochlord Tirion Fordring im Kreuzfahrerturm.", completion = "Harte Worte, {name}. Hätte jemand anderes das gesagt, hätte ich ihn wahrscheinlich für verrückt erklärt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13364] = { id = 13364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tirions Schachzug", description = "Diesen Morgen haben mich meine Späher darüber informiert, dass eine Prozession des Kults der Verdammten mit einem Artefakt von der Eiskronenzitadelle in Richtung Kathedrale der Dunkelheit aufgebrochen ist.\n\nUnd nun wird mir gesagt, dass es sich hierbei um Arthas' eigenes Herz handelt... ein Gegenstand, der den letzten Rest seiner Menschlichkeit enthält.\n\nDies ist ein Zeichen des Lichts. Solange solch ein Artefakt existiert, besteht eine Chance, dass Arthas Menethil wieder ein Mensch werden kann!\n\nTrefft mich am Eingang der Kathedrale. Bringt auf jeden Fall eine Kultistenverkleidung mit - wir gehen inkognito.", sourceObjective = "Tirion Fordring auf dem Kreuzfahrerturm möchte, dass Ihr die Kultistenkapuze besorgt, diese anzieht und Euch mit ihm am Eingang zur Kathedrale der Dunkelheit nordwestlich der Eiskronenzitadelle trefft.", completion = "Ich betrachte das, was wir soeben durchgemacht haben, nicht als Fehlschlag, {name}... im Gegenteil.\n\nDadurch, dass ich einen Blick in sein Herz werfen konnte, habt Ihr mir erlaubt, das zu bestätigen, was ich wissen musste. Es gibt keinen Arthas Menethil mehr - nur noch den Lichkönig.", sourceObjectiveStatus = "unverified-source-field" }
quests[13365] = { id = 13365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Wanze", description = "Die Kultisten haben den letzten Boten, den Ihr beschworen habt, entdeckt, {race}.\n\nEr hat uns zwar bereits sehr viele Informationen beschafft, aber es ist wichtig, dass wir weiter über jeden Schritt des Kultes informiert sind.\n\nBenutzt diese Rute, um den Körpern der versklavten Lakaien die dunkle Materie zu entziehen, und dann benutzt ihren Beschwörungskristall, um einen weiteren dunklen Boten zu erschaffen.\n\nBis er entdeckt wird, wird unser Bote unsere Augen und Ohren sein und ganz diskret die Handlungen unseres Gegners überwachen.", sourceObjective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr 5 dunkle Materien sammelt und in Aldur'thar einen dunklen Boten beschwört.", completion = "Gut gemacht, Freund.\n\nDer Bote ist bereits bei der Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13366] = { id = 13366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brauche mehr Informationen", description = "Der Kult der Verdammten ist dafür berühmt, grandiose Pläne auszuarbeiten, die letzten Endes allerdings selten erfolgreich sind. Diesmal allerdings scheint es anders zu sein...\n\nVielleicht ist es die Nähe zum Lichkönig, die ihre Inbrunst angefacht hat. Was immer es auch ist, sie scheinen selbstbewusster denn je. Wir müssen herausfinden, was ihren Eifer befeuert und dieses dann ganz schnell unterbinden!\n\nIch glaube, dass der Schlüssel dazu ihre Forscher sind. Findet heraus, was sie im Schilde führen und berichtet mir dann.", sourceObjective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr 3 Seiten Forschung der Kultisten von den Forschern der Kultisten in Aldur'thar sammelt, um damit eine These über den Kult der Verdammten zu erstellen...", progress = "Habt Ihr herausgefunden, was die Forscher im Schilde führen, {class}?", completion = "Das ist in der Tat alarmierend...", sourceObjectiveStatus = "unverified-source-field" }
quests[13367] = { id = 13367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es kann der Böseste nicht in Frieden ruhen...", description = "Die Dummköpfe sind übrigens über etwas gestolpert, das äußerst gefährlich für unsere Pläne werden könnte!\n\nAlumeth, der Anführer dieser Sekte, hat sich in einem Ritual selbst geopfert und nun versorgen seine Untergebenen seine Seele mit Macht.\n\nWenn wir ihn weiterhin in Ruhe lassen, werden sie ihn schon bald zu einem mächtigen Gegner machen.\n\nIn ihrer Kammer verteilt liegt sein Herz, Szepter, Schädel und seine Robe - kombiniert sie miteinander und benutzt das, was dabei rauskommt, in der Nähe der dortigen Kristalle.\n\nBeeilt Euch, {race}! Vernichtet ihn, bevor er noch mächtiger wird!", sourceObjective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr Alumeth den Aufgestiegenen in Aldur'thar besiegt.", completion = "Alumeth hat eine glatte Niederlage hinnehmen müssen, doch ich spüre, dass sich sein Geist noch immer hier aufhält...", sourceObjectiveStatus = "unverified-source-field" }
quests[13368] = { id = 13368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es kann der Böseste nicht in Frieden ruhen...", description = "Es ist Alumeth... Seine Macht wächst wieder an. Ich kann es fühlen. Wieder versorgen seine Untergebenen seine Seele mit Energie.\n\nWenn wir zulassen, dass er sich weiter erholt, werden ihre Bemühungen ihn zu einem mächtigen Gegner machen.\n\nKehrt in seine Kammer im Norden von Aldur'thar zurück. Sammelt sein Herz, seinen Schädel, sein Zepter und seine Kleider und wendet seine Überreste dann auf den Kristall dort an.\n\nEilt Euch, {race}! Vernichtet ihn, solange noch Zeit ist!", sourceObjective = "Koltira an Bord der Orgrims Hammer möchte, dass Ihr Alumeth den Aufgestiegenen in Aldur'thar tötet.", completion = "Alumeth hat eine glatte Niederlage hinnehmen müssen, doch ich spüre, dass sich sein Geist noch immer hier aufhält...", sourceObjectiveStatus = "unverified-source-field" }
quests[13369] = { id = 13369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal wendet sich gegen Euch", description = "Auf Geheiß von Lady Prachtmeer werde ich eine diplomatische Mission nach Orgrimmar entsenden, um Thrall, dem Kriegshäuptling der Horde, ein paar Fragen zu stellen. Ihr werdet ihr auf dieser Reise zur Seite stehen und dafür sorgen, dass ihr nichts zustößt. Kehrt anschließend mit Nachricht aus Orgrimmar zu mir zurück.\n\nSprecht mit Jaina, wenn Ihr bereit seid zu gehen.", sourceObjective = "Steht Lady Jaina Prachtmeer in Orgrimmar zur Seite. Sprecht mit Thrall, dem Kriegshäuptling der Horde in Orgrimmar auf dem Kontinent Kalimdor.", completion = "Die Horde will keinen Krieg, {race}. Hört gut zu...", sourceObjectiveStatus = "unverified-source-field" }
quests[13370] = { id = 13370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein königlicher Coup", description = "Euer Champion Bolvar ist bei der Verteidigung unserer Welt ums Leben gekommen. Die Horde ist vom Verlust eines solch großen Helden schwer getroffen, jedoch war sie für die feigen Angriffe Putress' auf die Pforte des Zorns nicht verantwortlich. Wir haben auch Verluste unter unseren mächtigen Helden zu beklagen aufgrund dieses Verrats.\n\nSagt Eurem König, dass wir alles in unserer Macht Stehende tun werden, um diejenigen, die für diese feige Tat verantwortlich sind, zur Rechenschaft zu ziehen. Wir werden alles tun, um einen Konflikt mit der Allianz zu vermeiden, doch wir werden nicht zögern, uns zu verteidigen, sollte man uns provozieren.", sourceObjective = "Benutzt das Portal in der Feste Grommash, um nach Burg Sturmwind zurückzukehren und Thralls Nachricht an König Varian Wrynn zu übergeben.", completion = "Sie haben die Unterstadt verloren? Dann ist jetzt der Augenblick gekommen, zuzuschlagen. Wir werden uns Putress höchstpersönlich vorknöpfen und die Ruinen von Lordaeron für die Allianz zurückerobern!", sourceObjectiveStatus = "unverified-source-field" }
quests[13371] = { id = 13371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist Zeit, totzuschlagen", description = "Bevor Ihr nach Orgrimmar aufgebrochen seid, habe ich Broll und Valeera nach Unterstadt entsandt. Um genau zu sein, sind sie gerade am Eingang zur Kanalisation stationiert und erwarten Befehl.\n\nLady Prachtmeer wird außerhalb der Unterstadt ein Portal für unsere Truppen erschaffen. Geht dorthin und meldet Euch bei Broll. Jaina und ich werden dicht hinter Euch sein.", sourceObjective = "Benutzt das Portal nach Unterstadt im Inneren von Burg Sturmwind, um Euch nach Unterstadt zu teleportieren. Meldet Euch bei Broll Bärenfell, wenn Ihr am Zielort angekommen seid.", completion = "Wer sollt Ihr sein? Varian hat gesagt, dass er Helden schicken würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13372] = { id = 13372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlüssel der fokussierenden Iris", description = "Ihr spürt und hört, wie ein lautes Dröhnen magischer Natur von dem augenförmigen Juwel ausgeht, das Saphiron in seinen Klauen hielt. Für die Ohren eines Sterblichen ist es schon beinahe eine Qual, in Gegenwart des Steins zu sein.\n\nSolch ein bedeutungsvoller Gegenstand kann auf jeden Fall nur zur Königin der Großdrachen, Alexstrasza der Lebensbinderin, gebracht werden. Geht zur höchsten Ebene des Wyrmruhtempels in der Drachenöde und ersucht sie um Rat.", sourceObjective = "Liefert den Schlüssel zur fokussierenden Iris bei Alexstrasza der Lebensbinderin auf der höchsten Ebene des Wyrmruhtempels in der Drachenöde ab.", progress = "{name}, Ihr seid mit dem Schlüssel zur fokussierenden Iris in Berührung gekommen! Habt Ihr ihn dabei?\n\n\n\nWie konntet Ihr jemals in seinen Besitz gelangen? Oh, Saphiron hatte seinen Schlüssel noch immer?", completion = "Nur die ältesten Mitglieder des blauen Drachenschwarms sind in Besitz dieser Schlüssel. Malygos, ihr Meister, vertraut sie nur ihnen an.\n\nDas ist die Gelegenheit, auf die wir gewartet haben, um den Aspekt der Magie anzugreifen!<Die Königin der Drachen mustert Euch kurz.>\n\nIhr könnt mit dem Schlüssel, so wie er ist, keinen Zugang zur fokussierenden Iris erhalten, doch ich kann Euch mit einem Teil meiner Macht erfüllen; genug, um damit die Iris einen Spalt zu öffnen.\n\nEs wird genügen, um Malygos Zorn auf Euch zu ziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13373] = { id = 13373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorzüge der Grenzwissenschaft", description = "Ich habe unsere Infragrüntechnologie in die beschlagnahmten Bomber eingebaut - das wird Euch auf eurer ersten Mission in Feindgebiet beschützen! Sprecht mit Rizzy Ratschenwackel, um einen Bomber zu bekommen, und fliegt dann zum Bombardement!\n\nIhr werdet Bomben, Raketen und Schilde haben. Sorgt dafür, dass Eure Schilde aufgeladen bleiben, und werft die Bomben auf die Diener der Geißel im Bombardement ab. Kommt zurück, nachdem Ihr Eure Ziele getroffen habt, und es wird Euch noch mehr Arbeit erwarten.", sourceObjective = "Grenzwissenschaftsingenieurin Tezzla möchte, dass Ihr 40 Bombardementinfanteristen, 8 Bombardementhauptmänner und 15 Gargoylewegelagerer tötet.", progress = "Ihr habt Eure Trefferquote noch nicht erfüllt, {name}. Sind die Bomber zu schwer zu fliegen?", completion = "Ha, Ihr habt sie erwischt! Wie hat Euch der Bomber gefallen? Ich hoffe, dass Ihr den Dreh raus habt, denn ich habe noch mehr Missionen für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[13374] = { id = 13374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereit zur Revolte!", description = "{name}, nur unsere besten Piloten bekommen eine Mission wie diese. Eine Mission, bei der es sehr tief in Feindgebiet geht und bei der Ihr nur von Infragrüntechnologie beschützt werdet!\n\nBeantragt einen weiteren Bomber von Rizzel und fliegt mit ihm dieses Mal durch das Tal der Verlorenen Hoffnung. Bei dieser Mission habt Ihr Boden- und Luftziele - haltet also die Augen auf und sorgt dafür, dass Eure Schilde aufgeladen bleiben!\n\nViel Glück!", sourceObjective = "Grenzwissenschaftsingenieurin Tezzla möchte, dass Ihr Bombardementinfanteristen, Gargoylewegelagerer, Frostbrutspäher und Kriegsmaschinen der Geißel vernichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13375] = { id = 13375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der heroische Schlüssel der fokussierenden Iris", description = "Ihr spürt und hört, wie ein lautes Dröhnen magischer Natur von dem augenförmigen Juwel ausgeht, das Saphiron in seinen Klauen hielt. Für die Ohren eines Sterblichen ist es schon beinahe eine Qual, in Gegenwart des Steins zu sein.\n\nSolch ein bedeutungsvoller Gegenstand kann auf jeden Fall nur zur Königin der Großdrachen, Alexstrasza der Lebensbinderin, gebracht werden. Geht zur höchsten Ebene des Wyrmruhtempels in der Drachenöde und ersucht sie um Rat.", sourceObjective = "Liefert den heroischen Schlüssel zur fokussierenden Iris bei Alexstrasza der Lebensbinderin auf der höchsten Ebene des Wyrmruhtempels in der Drachenöde ab.", progress = "{name}, Ihr seid mit dem Schlüssel zur Iris in Berührung gekommen! Habt Ihr ihn dabei?\n\n\n\nWie konntet Ihr jemals in seinen Besitz gelangen? Oh, Saphiron hatte seinen Schlüssel noch immer?", completion = "Nur die ältesten Mitglieder des blauen Drachenschwarms sind in Besitz dieser Schlüssel. Malygos, ihr Meister, vertraut sie nur ihnen an.\n\nDas ist die Gelegenheit, auf die wir gewartet haben, um den Aspekt der Magie anzugreifen!<Die Königin der Drachen mustert Euch kurz.>\n\nIhr könnt mit dem Schlüssel, so wie er ist, keinen Zugang zur fokussierenden Iris erhalten, doch ich kann Euch mit einem Teil meiner Macht erfüllen; genug, um damit die Iris einen Spalt zu öffnen.\n\nEs wird genügen, um Malygos Zorn auf Euch zu ziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13376] = { id = 13376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totale Vernichtung: Das Tal der Verlorenen Hoffnung!", description = "{name}, der Kampf geht weiter. Zu unserem Glück haben wir uns mit Bomben und Raketen eingedeckt! Zeit für eine weitere Bombenmission - diese hier ist eine längere: Es geht über das Bombardement hinweg und zum Tal der Verlorenen Hoffnung. Setzt Euch wieder in einen Infragrünbomber, fliegt hinaus und verarbeitet die Diener der Geißel in kleine Geißelstückchen!", sourceObjective = "Grenzwissenschaftsingenieurin Tezzla möchte, dass Ihr 50 Bombardementinfanteristen, 20 Gargoylewegelagerer, 12 Frostbrutspäher und 12 Kriegsmaschinen der Geißel vernichtet.", progress = "Worauf wartet Ihr? Wir haben das Material und den Befehl... wir brauchen nur mutige Schützen wie Euch, um sie einzusetzen.", completion = "Ausgezeichnete Arbeit, {name}. Während Ihr dort draußen wart, habe ich andere Schützen über Euch reden hören... Denke, dass Ihr eine echte Zukunft als Angriffsflieger habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[13377] = { id = 13377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Unterstadt", description = "Tief im Inneren von Unterstadt versteckt er sich: der Meuchelmörder, der für den Tod Bolvars und den Tod unserer mutigen Soldaten an der Pforte des Zorns verantwortlich ist.\n\nVarian hat die geballte Macht der Allianz mitgebracht, um dabei zu helfen, die Stadt auseinanderzunehmen. Schließt Euch ihm und Lady Prachtmeer auf ihrer Jagd an und verdient Euch Euren Platz unter den größten Champions der Allianz!\n\nSprecht mit König Varian Wrynn, wenn Ihr bereit seid.", sourceObjective = "Helft König Varian Wrynn und Lady Jaina Prachtmeer, Großapotheker Putress zur Rechenschaft zu ziehen! Meldet Euch bei König Varian Wrynn, solltet Ihr erfolgreich sein.", completion = "Schon viel zu lange ist die Horde unbehelligt geblieben. Wir haben ihre Gebiete gedeihen lassen und als Gegenleistung für unsere Großzügigkeit haben sie daran gearbeitet, unseren Untergang herbeizurufen.\n\nFrieden? Zwecklos... nichts hat er uns gebracht. Wir haben einige unserer größten Helden an den \"Frieden\" verloren. Sehen wir einmal, was die Schlacht uns bringen wird...\n\nKehrt nach Nordend zurück, {name}. Erobert es für Euren König - FÜR DIE ALLIANZ!", sourceObjectiveStatus = "unverified-source-field" }
quests[13378] = { id = 13378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chefingenieur Kupferklammer", description = "Sprecht mit Chefingenieur Kupferklammer." }
quests[13379] = { id = 13379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grüne Technologie", description = "Tezzla ist diejenige, nach der Ihr sucht, genau... sie beherrscht nun eine neue Wellenlänge namens Infragrün und hält sich damit in der Nähe der Geißel versteckt! Nahe genug, um Bomben auf sie abzuwerfen!\n\nIch werde Euch Infragrünsicht verleihen, damit Ihr sie sehen könnt. Sie befindet sich über Aldur'thar, dem Tor der Verwüstung. Geht, los, geht... ich weiß, dass sie Arbeit für mutige Helden hat, die scharf darauf sind, in die Luft zu fliegen! Äh, ich meine: die scharf darauf sind, die Geißel in die Luft fliegen zu lassen!\n\nUnd {name}, die Allianz hat unsere Technologie gestohlen und ihren eigenen versteckten Flugplatz in der Nähe errichtet. Haltet Euch von der Plattform mit den Bannern der Allianz fern!", sourceObjective = "Sprecht mit Grenzwissenschaftsingenieurin Tezzla.", completion = "Ja, ja! Ihr habt mich gefunden! Und gerade rechtzeitig!", sourceObjectiveStatus = "unverified-source-field" }
quests[13380] = { id = 13380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Angriff leiten", description = "Infragrüntechnologie ermöglicht es uns, hier versteckt zu bleiben - direkt unter der Nase der Geißel! Außerdem haben wir spezielle Bomber mit Infragrüntechnologie ausgerüstet... doch nicht um sie zu tarnen, nein! Wir benutzen die Technologie, um sie zu schützen!\n\nSprecht mit Karen Nein und fordert einen Bomber an. Fliegt mit ihm zum Bombardement... benutzt seine Schilde und sein Geschütz, um Euch zu schützen, und seinen Bombenwerfer, um die Ziele der Geißel zu treffen. Trainiert gut, kommt dann wieder zu mir zurück und ich werde eine noch wichtigere Mission für Euch haben!", sourceObjective = "Kibli Killohertz möchte, dass Ihr 40 Bombardementinfanteristen, 8 Bombardementkapitäne und 15 Gargoylewegelagerer tötet.", progress = "{name}, die Bomber sind schwierig zu fliegen, doch Ihr müsst sie beherrschen, wenn wir unseren Kampf gegen die Geißel gewinnen wollen.", completion = "Ich konnte die Explosionen von hier aus hören, {name}. Haben die Schilde gut funktioniert? Haben sie Euren Bomber intakt gehalten?\n\nIch hoffe, dass dem so ist, weil ich jetzt noch mehr Missionen für Euch habe...", sourceObjectiveStatus = "unverified-source-field" }
quests[13381] = { id = 13381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Watt ist mein Ziel", description = "Zieht Euch warm an, {name}, und fangt an zu beten. Diese nächste Mission wird Euren Verstand und Eure innere Stärke auf die Probe stellen wie ein Besuch der Schwiegereltern!\n\nFordert einen weiteren Bomber von Karen Nein an. Fliegt mit ihm über das Bombardement und das Tal der Verlorenen Hoffnung hinweg. Diesmal habt Ihr mehr Ziele, am Boden und in der Luft. Sorgt dafür, dass Euer Schutzschild und Eure Munition geladen ist, {name}! Ich werde Euch wiedertreffen, wenn die Sache vorbei ist.", sourceObjective = "Kibli Killohertz wünscht, dass Ihr Bombardementinfanteristen, Gargoylewegelagerer, Frostbrutspäher und Kriegsmaschinen der Geißel vernichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13382] = { id = 13382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission mit Hertz: Das Tal der Verlorenen Hoffnung", description = "Der Kampf geht weiter! Eure neuen Befehle sind hier. Es handelt sich um eine Langstreckenbombenmission zum Bombardement und zum Tal der Verlorenen Hoffnung. Fragt Karen nach einem Bomber und macht der Geißel mit Euren Bomben und Raketen die Hölle heiß!", sourceObjective = "Kibli Killohertz möchte, dass Ihr 50 Bombardementinfanteristen, 20 Gargoylewegelagerer, 12 Frostbrutspäher und 12 Kriegsmaschinen der Geißel vernichtet.", progress = "Einfach draufhalten, {name}. Der Luftkampf wird sich nicht von alleine gewinnen lassen!", completion = "Willkommen zurück, {name}. Wie war die Schlacht? Aufregend? Ruht Euch erst einmal aus. Doch kommt wieder zurück, wenn Ihr neue Befehle habt.\n\nFür die Allianz!", sourceObjectiveStatus = "unverified-source-field" }
quests[13383] = { id = 13383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Killohertz", description = "Die Goblins hatten Glück: Sie haben eine neue Energie gefunden. Sie nennen sie Infragrün und ich soll ein einäugiger Oger sein, wenn diese Psychopathen damit keinen grünen Volltreffer gelandet haben.\n\nGeht und sucht nach Kibli Killohertz. Er befindet sich auf einem kleinen, versteckten Flugplatz der Allianz über Aldur'thar, dem Tor der Verwüstung, und ist dort für die umgekehrten Ingenieursbestrebungen in Bezug auf die Infragrüntechnologie zuständig. Ich werde Euch Infragrünsicht geben, damit Ihr ihn finden könnt. Geht zur Kuppel, auf der unsere Banner der Allianz wehen. Falls Ihr in der Nähe des Flugplatzes der Horde herumfliegen solltet, dann seid Ihr in jeder Menge grünen Schwierigkeiten.", sourceObjective = "Chefingenieur Bolzenschlüssel möchte, dass Ihr zum verborgenen Allianzflugplatz über Aldur'thar, dem Tor der Verwüstung, fliegt und Kibli Killohertz aufsucht.", completion = "Ja, ja, ja! So gut, Euch zu sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13384] = { id = 13384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entscheidung im Auge der Ewigkeit", description = "Es ist nun, da Ihr Zugang zur fokussierenden Iris habt, an der Zeit, dass Ihr vom Schlüssel Gebrauch macht.\n\nSo gerne ich Malygos wieder bei uns mit offenen Armen empfangen möchte, aber zu diesem Zeitpunkt wird dies einfach nicht möglich sein. Angesichts all dessen, was auf dem Spiel steht, haben sich die anderen Drachenaspekte dazu entschlossen, dass der Zauberwirker ausgeschaltet werden muss.\n\n<Krasus klingt sehr betroffen, als er diese letzten Worte ausspricht.>\n\n{name}, macht Euch auf den Weg zum Auge der Ewigkeit, begegnet Malygos und kehrt mit dem Herzen der Magie zurück.", sourceObjective = "Krasus auf der Spitze des Wyrmruhtempels in der Drachenöde möchte, dass Ihr mit dem Herzen der Magie zurückkehrt.\n\nDiese Quest ist für den normalen Modus, also für die 10-Mann-Version des Auges der Ewigkeit, gedacht.", progress = "Malygos und nur Malygos allein trägt das Herz der Magie bei sich. Es ist sein kostbarster Besitz.", completion = "Dies ist ein sehr trauriger Tag, nicht nur für uns Drachen, sondern für alle lebendigen Wesen Azeroths. Wir haben einen unserer nachdenklichsten, intelligentesten und ältesten Freunde verloren. Die Magie hat ihren Wächter verloren.\n\nLasst uns hoffen, dass sich dies in den kommenden Jahren als weise Entscheidung herausstellen wird, {name}. Am Horizont braut sich noch immer ein Sturm zusammen und uns fehlt einer unserer mächtigsten Verteidiger.", sourceObjectiveStatus = "unverified-source-field" }
quests[13385] = { id = 13385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroische Entscheidung im Auge der Ewigkeit", description = "Es ist nun, da Ihr Zugang zur fokussierenden Iris habt, an der Zeit, dass Ihr vom Schlüssel Gebrauch macht.\n\nSo gerne ich Malygos wieder bei uns mit offenen Armen empfangen möchte, aber zu diesem Zeitpunkt wird dies einfach nicht möglich sein. Angesichts all dessen, was auf dem Spiel steht, haben sich die anderen Drachenaspekte dazu entschlossen, dass der Zauberwirker ausgeschaltet werden muss.\n\n<Krasus klingt sehr betroffen, als er diese letzten Worte ausspricht.>\n\n{name}, macht Euch auf den Weg zum Auge der Ewigkeit, begegnet Malygos und kehrt mit dem Herzen der Magie zurück.", sourceObjective = "Krasus auf der Spitze des Wyrmruhtempels in der Drachenöde möchte, dass Ihr mit dem Herzen der Magie zurückkehrt.\n\nDiese Quest kann sowohl in der 10-Mann-Version als auch in der 25-Mann-Version des Auges der Ewigkeit abgeschlossen werden.", progress = "Malygos und nur Malygos allein trägt das Herz der Magie bei sich. Es ist sein kostbarster Besitz.", completion = "Dies ist ein sehr trauriger Tag, nicht nur für uns Drachen, sondern für alle lebendigen Wesen Azeroths. Wir haben einen unserer nachdenklichsten, intelligentesten und ältesten Freunde verloren. Die Magie hat ihren Wächter verloren.\n\nLasst uns hoffen, dass sich dies in den kommenden Jahren als weise Entscheidung herausstellen wird, {name}. Am Horizont braut sich noch immer ein Sturm zusammen und uns fehlt einer unserer mächtigsten Verteidiger.", sourceObjectiveStatus = "unverified-source-field" }
quests[13386] = { id = 13386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausnutzen einer Öffnung", description = "Ich habe eine interessante Aufgabe für Euch, {name}. Allerdings nur, wenn Ihr auf eine Herausforderung aus seid.\n\nWir haben von einer Öffnung unterhalb der Eiskronenzitadelle gehört. Unsere Ingenieure haben sie studiert und gehen davon aus, dass sie eine strukturelle Schwäche darstellt.\n\nWir haben ein paar Männer mit einer \"geborgten\" Ladung Saronitbomben dorthin entsandt. Sie stehen unter dem Kommando von Hauptmann Kendall.\n\nMit ein bisschen Hilfe könnten wir den Streitkräften der Geißel einen ordentlichen Schlag verpassen. Was sagt Ihr, {name}?", sourceObjective = "Redet mit Hauptmann Kendall unterhalb der Eiskronenzitadelle.", completion = "Seid gegrüßt, {name}. Thassarian sagte schon, dass Ihr kommen würdet. Jeder Freund von Thassarian ist auch mein Freund. Zumindest jeder lebende Freund... er umgibt sich mitunter mit seltsamer Gesellschaft.", sourceObjectiveStatus = "unverified-source-field" }
quests[13387] = { id = 13387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherung des Gebiets", description = "Die Saronitbomben sind platziert, {name}. Wir haben aber nur einen Versuch, also muss es unbedingt funktionieren.\n\nWir müssen für eine Weile die Kontrolle über das Gebiet haben, um eine sichere Detonation garantieren zu können. Lasst uns versuchen, die Anzahl der Geißel ein wenig zu reduzieren.", sourceObjective = "Kapitän Kendall bei der Eiskronenzitadelle möchte, dass Ihr 10 bullige Schrecken tötet.", progress = "Für die Allianz!", completion = "Ihr seid so gut, wie Thassarian gesagt hat. Gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[13388] = { id = 13388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst sie hochgehen!", description = "Das sieht doch schon mal alles recht gut aus. Also, gehen wir's an!\n\nDer Bombenstapel befindet sich gleich in der Nähe der Grube. Ich werde beginnen, die Männer zu evakuieren.", sourceObjective = "Hauptmann Kendall unterhalb der Eiskronenzitadelle möchte, dass Ihr die Lunte an dem nahegelegenen Saronitbombenstapel anzündet.", completion = "Diese Bomben sehen ziemlich durchschlagskräftig aus. Sie sollten zumindest eine ordentliche Delle in die umgebende Struktur machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13389] = { id = 13389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine kurze Lunte", description = "Als Ihr die Lunte entzündet, merkt Ihr, dass sie viel schneller abbrennt, als Ihr erwartet hattet.\n\nDie Bomben sind kurz vor der Explosion und Eure beste Chance zu überleben ist, Euch nach vorne fallen zu lassen und zu hoffen, dass Euch der Sturz nicht tötet.", sourceObjective = "Haltet nach Hinweisen Ausschau, wo auch immer der Sturz Euch hinführt.", completion = "Dieses pulsierende Objekt ist von einer dicken Eisschicht umgeben. Es schimmert geheimnisvoll unter Wasser.", sourceObjectiveStatus = "unverified-source-field" }
quests[13390] = { id = 13390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Stimme im Dunklen", description = "Das Objekt ist überhaupt kein Kristall, sondern etwas Organisches, das in Eis eingeschlossen ist.\n\nAls Ihr es berührt, zuckt Eure Hand vor Schmerz zurück. Es fühlt sich an, als hättet Ihr Euch in die Hand geschnitten, aber es ist keine Wunde zu sehen.\n\nAls Ihr Eure Gedanken sammelt, hört Ihr die Stimme eines Jungen in der Nähe.\n\n\"Das hättet Ihr nicht tun sollen.\"", sourceObjective = "Untersucht die nahe Stimme in Naz'anak, den Vergessenen Tiefen.", completion = "Ich sah, wie er es weggeworfen hat, wisst Ihr? Er hat es ganz bis hier herunter geworfen.\n\nSagte, er bräuchte es nicht mehr. Sagte, es würde ihn schwach machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13391] = { id = 13391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit zum Verstecken", description = "Ihr hättet das nicht berühren sollen. Nun, da Ihr es getan habt, wird er kommen und nach Euch suchen.\n\nUnd er wird Euch finden. Solange Ihr Euch nicht vor ihm versteckt.\n\nBringt mir Blut von den Gesichtslosen, wenn Ihr leben wollt.", sourceObjective = "Matthias Lehner möchte, dass Ihr ihm 3 Proben Blut des Gesichtslosen bringt.", progress = "Habt Ihr das Blut?", completion = "Worauf wartet Ihr dann noch? Ihr müsst Euch damit einreiben!\n\nSchnell! Oder er wird Euch sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13392] = { id = 13392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr an die Oberfläche", description = "Ihr solltet nun gehen. Hinter mir findet Ihr ein Portal, das Euch an die Oberfläche bringen wird.\n\nWir werden uns wiedersehen. Er wird nach Euch suchen.\n\nEs ist nur eine Frage der Zeit, bis er Euch findet.", sourceObjective = "Kehrt zu Thassarian an Bord der Himmelsbrecher zurück.", completion = "Ihr seid es, {name}! Wir dachten schon, es hätte Euch erwischt.\n\nEure Explosion hat der Geißel ganz schön wehgetan. Und dabei fast noch Hauptmann Kendalls Augenbrauen weggesengt...", sourceObjectiveStatus = "unverified-source-field" }
quests[13393] = { id = 13393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldreparaturen", description = "Alles klar. Lasst uns aber nicht zu früh feiern. Wir müssen aus dem Vorteil, den wir mit unserer kleinen Bombardierung errungen haben, Kapital schlagen.\n\nWir haben ein funktionierendes Katapult der Verwüster-Klasse von der Horde auf dem Feld unten entdeckt. Die Spuke scheinen es auseinanderzunehmen.\n\nWenn Ihr es wieder zusammensetzen könntet, wären wir in der Lage, den Armeen der Geißel im Tal ernstlichen Schaden zuzufügen.\n\nKlar, Ihr werdet ziemlich in der Unterzahl sein, aber ich setze großes Vertrauen in Euch.", sourceObjective = "Thassarian an Bord der Himmelsbrecher möchte, dass Ihr 5 Verwüsterersatzteile von den aasfressenden Spuken sammelt und sie zu dem defekten Verwüster im Tal der Verlorenen Hoffnung bringt.", progress = "Der Verwüster wurde stark beschädigt.", completion = "Der Verwüster hat schon bessere Tage gesehen, aber die Struktur hat keinen dauerhaften Schaden genommen. Die Ersatzteile, die Ihr gebracht habt, sollten ausreichen, um ihn zumindest vorübergehend wieder ans Laufen zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13394] = { id = 13394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tut Euer Schlechtestes", description = "Ihr werdet diese Maschine gegen die Geißel einsetzen? Auf diese Weise werdet Ihr nicht gegen sie gewinnen können.\n\nIhr könnt Hunderte... sogar Tausende von ihnen zerstören, doch gewinnen werdet Ihr nicht - nicht hier draußen.\n\nTrefft mich im Norden, wenn Ihr genug mit Eurer Maschine gespielt habt. Dort gibt es ein altes Militärlager. Was ich Euch zeigen werde, wird Euch einen kleinen Einblick darüber gewähren, wem wir uns hier gegenübersehen.", sourceObjective = "Zerstört mithilfe des Runderneuerten Verwüsters 150 verrottete Ghule, 20 Frostschädelmagier und 2 Knochenriesen im Tal der Verlorenen Hoffnung. Sprecht mit Matthias Lehner im Vorhutslager der Ersten Legion, wenn Ihr die Aufgabe abgeschlossen habt.", progress = "Habt Ihr genug mit Euren Kriegsmaschinen gespielt?", completion = "Seht Ihr? Ihr habt Euren gerechten Anteil zwar getötet, doch für jeden Einzelnen, den Ihr vernichtet habt, kam ein weiterer aus der Erde, um dessen Platz einzunehmen.\n\nIhr wisst nicht, wem Ihr hier gegenübersteht, {name}. Lasst es mich Euch zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13395] = { id = 13395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armee der Verdammten", description = "Ihr meint wohl, Ihr seid ziemlich stark... diese Untoten zu bekämpfen und ihre Knochen mit Euren Kriegsmaschinen zu zerquetschen.\n\nDas ist aber noch gar nichts, verglichen mit der Stärke, derer es bedarf, um sie zu erschaffen.\n\nIch habe selbst gesehen, wie der Prinz es gemacht hat. Ich kann Euch zeigen, wie das geschehen ist... wenn Ihr wollt.", sourceObjective = "Matthias Lehner beim Vorhutslager der Ersten Legion möchte, dass Ihr eine Armee von 100 ghulischen Dienern aufstellt.", completion = "Die wahre Stärke des Prinzen lag nicht darin, Armeen aus Leichen zu erschaffen... das war leicht.\n\nAber seine eigenen Männer zu töten, mit denen er in vielen Schlachten Seite an Seite gefochten hatte... die wahre Stärke des Prinzen war seine Fähigkeit, zu tun, was getan werden musste.", sourceObjectiveStatus = "unverified-source-field" }
quests[13396] = { id = 13396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sinnlosigkeit", description = "Seht Ihr es nun? Eure Männer gegen die Armeen des Prinzen zu entsenden sorgt nur dafür, dass ihre Reihen weiter anwachsen.\n\nIch erwarte nicht, dass Ihr es versteht... Ihr werdet vermutlich auch wie die anderen enden. Am besten kehrt Ihr zu denjenigen zurück, die Euch entsandt haben. Sie werden sich Sorgen machen.", sourceObjective = "Kehrt zu Thassarian an Bord der Himmelsbrecher zurück.", completion = "Gut geschossen, {name}. Die Geißel hatte keine Chance.\n\nGeht es Euch gut? Ihr seht aus, als hättet ihr einen Geist gesehen. Naja, wenn ich so darüber nachdenke, wäre das in diesen Gegenden kein wirklich unüblicher Anblick.", sourceObjectiveStatus = "unverified-source-field" }
quests[13397] = { id = 13397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sindragosas Sturz", description = "Ihr seid ein echter Star, {name}. Wisst Ihr, wenn ich einem der anderen Soldaten einen Auftrag erteile, stehen die Chancen, dass er ihn erfolgreich ausführt, etwa fünfzig zu fünfzig. Die Chancen, dass er lebend zurückkommt... nun, unwesentlich schlechter.\n\nAber bei Euch ist die Sache stets geritzt. Zuverlässig wie ein gnomisches Uhrwerk!\n\nWie dem auch sei, ich habe noch einen für Euch. Sindragosas Sturz, im Osten des Tals. Dort gehen verstärkte Aktivitäten der Kultisten vor sich, inklusive und sich nicht beschränkend auf die Erschaffung von Frostwyrms. Ich brauche Euch, um denen mal ordentlich die Zähne einzutreten.\n\nIch hasse Kultisten.", sourceObjective = "Thassarian an Bord Himmelsbrecher möchte, dass Ihr 5 Wyrmwiedererwecker, 8 Verderber der Kultisten und 3 Nekrolords der Vrykul in Sindragosas Sturz tötet.", completion = "Gute Arbeit, {name}. Neben Euch verblasst der Rest von uns!", sourceObjectiveStatus = "unverified-source-field" }
quests[13398] = { id = 13398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo Drachen einst fielen", description = "Einst fiel hier eine ganze Brut von blauen Drachen. Und nun wird jeder einzelne von ihnen von seinen Dienern wiedererweckt.\n\nDen größten von ihnen hat er selbst wiedererweckt. Bringt mir ein wenig Knochenstaub von ihren Welpen und ich werde Euch ganz genau zeigen, wie er das gemacht hat.", sourceObjective = "Matthias Lehner in Sindragosas Sturz möchte, dass Ihr 6 Einheiten Welpenknochenstaub besorgt.", progress = "Habt Ihr den Staub bekommen, {name}?", completion = "Selbst die mächtigen Wyrm mussten seinem Ruf folgen. Wie könnte ein einfacher Sterblicher wie Ihr ihm widerstehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[13399] = { id = 13399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit für Antworten", description = "Ihr habt viele Fragen, {name}. Ihr seid <der Einzige, der/die Einzige> die; mich sehen kann, weil Ihr etwas berührt habt, das einst ihm gehörte... könnt Ihr Euch nicht mehr erinnern?\n\nIhr wisst nicht, was es ist? Nun, ich kann es Euch nicht einfach so sagen... das würde ihn ziemlich wütend machen. Er ist nicht mehr bloß ein Prinz... er ist jetzt der König!\n\nTrefft mich im Hof der Knochen nördlich der Eiskronenzitadelle und Ihr könnt es für Euch selbst sehen.", sourceObjective = "Sprecht mit Matthias Lehner im Hof der Knochen.", completion = "Da seid Ihr ja. Ich habe mich schon gefragt, wann Ihr auftauchen würdet.", sourceObjectiveStatus = "unverified-source-field" }
